export const ENGINE_SOURCES: Record<string, string> = {
  "phagequest_engine/__init__.py": "\"\"\"PhageQuest engine.\n\nThe statistical, simulation and geometry core of the PhageQuest Discovery\nPlatform. Built statistics-first, per the design rule in the specification:\n\n    \"Build the statistics layer first and the bioinformatics on top of it --\n    not the other way round. Every competitor did it the other way round, which\n    is exactly why they all have the same hole.\"\n\nThe platform invariant, enforced in `transcript.py` and `guards.py`:\n\n    No numeric statistical claim may be rendered to a user unless it is bound\n    to a specific execution record -- code, engine version, raw output,\n    timestamp -- produced by a real statistics engine.\n\nLicence posture (specification section 09): this package depends only on numpy\nand scipy (BSD). No GPL (pingouin, igraph, leidenalg), no AGPL (giotto-tda).\nEverything here runs unchanged in Pyodide, which is what makes Tier 0 -- about\n90% of the Grades 5-12 workload, in the student's own browser, at zero marginal\ncost and with no student data reaching our servers -- possible at all.\n\"\"\"\n\n__version__ = \"0.1.0\"\n\nfrom . import (\n    assumptions,\n    curves,\n    diversity,\n    effects,\n    geometry,\n    guards,\n    inference,\n    ledger,\n    power,\n    registry,\n    resampling,\n    sequence,\n    simulation,\n    stability,\n    transcript,\n    validation,\n)\nfrom .assistant import Assistant, MockProvider\nfrom .registry import TOOLS, call_tool, tool_schemas, tools_for_grade\nfrom .transcript import Transcript, TranscriptStore, get_store, set_store\n\n__all__ = [\n    \"__version__\",\n    # modules\n    \"assumptions\", \"curves\", \"diversity\", \"effects\", \"geometry\", \"guards\",\n    \"inference\", \"ledger\", \"power\", \"registry\", \"resampling\", \"sequence\",\n    \"simulation\", \"stability\", \"transcript\", \"validation\",\n    # the tool boundary\n    \"TOOLS\", \"call_tool\", \"tool_schemas\", \"tools_for_grade\",\n    # transcripts\n    \"Transcript\", \"TranscriptStore\", \"get_store\", \"set_store\",\n    # assistant\n    \"Assistant\", \"MockProvider\",\n]\n",
  "phagequest_engine/assistant.py": "\"\"\"The assistant: a chatbot that cannot invent a number (spec section 06).\n\nThe model's job is to choose a tool, explain a result, and ask the next\nquestion. It never computes, and everything it says passes through the guards\nin `guards.py` before a user sees it.\n\nThe turn pipeline, in order:\n\n    user message\n      -> PII redaction (DPDP, spec section 09)\n      -> specification-search check on the phrasing\n      -> pre-registration gate\n      -> model proposes ONE tool call from the typed registry\n      -> the engine executes it; a transcript is created\n      -> model writes prose about the result\n      -> claim guard        (UMAP distances, causation, accepting the null)\n      -> numeric scan       (every number must trace to a transcript)\n      -> behavioural specification-search check\n      -> render, with the transcript attached\n\n`LLMProvider` is an interface. `MockProvider` implements it deterministically,\nso the whole harness -- including every guard -- runs and is tested without an\nAPI key, in CI, and in a school with no internet.\n\nOrchestration note (spec section 06): the spec picks DSPy for the reasoning\nlayer and MCP for the tool boundary, and warns against stacking LangChain and\nLlamaIndex and MCP together. This module is the boundary itself: typed\nsignatures in, validated structures out, one orchestrator. A DSPy or MCP\nadapter wraps it; neither is imported here, so the guarantees do not depend on\neither staying maintained.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport re\nimport time\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Any, Dict, List, Optional, Protocol, Sequence\n\nfrom . import guards, registry\nfrom .transcript import TranscriptStore, get_store, set_store\n\n__all__ = [\"LLMProvider\", \"MockProvider\", \"Assistant\", \"Turn\", \"SYSTEM_PROMPT\"]\n\n\nSYSTEM_PROMPT = \"\"\"\\\nYou are the PhageQuest analysis assistant, working with a student in Grade {grade}.\n\nHARD RULES -- these are enforced after you speak, so breaking them wastes the turn:\n\n1. You never compute. Not arithmetic, not a p-value, not a mean, not a\n   percentage. Every number you write must have come back from a tool call in\n   this turn. A number you produce yourself is stripped before the student sees\n   it, and the turn is regenerated.\n2. You choose the test; the engine runs it. When you call an inferential tool\n   you must supply `justification`: one sentence about the DESIGN -- why this\n   test, on this data. It is logged and shown to the teacher.\n3. Withhold the answer by default. Ask the probing question first. The evidence\n   says structured practice, not conversational answer-giving, is what produces\n   learning; a student who predicts before testing learns more than one who is\n   told. Require a stated prediction before you run a test.\n4. Never say a plot's distances mean something it cannot support, never turn a\n   correlation into a cause, and never report a non-significant result as proof\n   that there is no difference.\n5. Below three observations per group, there is no test to run. Say so and\n   describe the data instead. Below 100 samples there is no machine learning to\n   do; steer back to description and inference, where the answer actually is.\n6. When a stability check says the conclusion flips, lead with that, not with\n   the p-value.\n\nTONE: plain words, short sentences, no statistical jargon unless you define it\nin the same breath. The student is {grade_words}. A teacher who is not a\nstatistician reads everything you write.\n\nAvailable tools this grade may use: {tool_names}\n\"\"\"\n\n_GRADE_WORDS = {\n    5: \"ten or eleven and has met powers of ten but not averages\",\n    6: \"eleven or twelve and is meeting the idea of variability for the first time\",\n    7: \"twelve or thirteen and can understand shuffling but not a t-distribution\",\n    8: \"thirteen or fourteen and is ready for rates, curves and quantified uncertainty\",\n    9: \"fourteen or fifteen and can handle a hypothesis, a test and an interval\",\n    10: \"fifteen or sixteen and is working toward a capstone\",\n    11: \"sixteen or seventeen and is doing genuine research\",\n    12: \"seventeen or eighteen and is doing genuine research\",\n}\n\n\nclass LLMProvider(Protocol):\n    \"\"\"Provider interface. Implement `complete` and the whole harness works.\"\"\"\n\n    name: str\n\n    def complete(self, system: str, messages: List[Dict[str, str]],\n                 tools: List[Dict[str, Any]]) -> Dict[str, Any]:\n        \"\"\"Return {\"text\": str, \"tool_call\": {\"name\": str, \"arguments\": dict} | None}.\"\"\"\n        ...\n\n\nclass MockProvider:\n    \"\"\"A deterministic, offline provider.\n\n    It is not an imitation of a language model; it is a rule-based planner good\n    enough to drive every path through the harness. That matters more than it\n    sounds: it means the honesty guards are tested against real tool results in\n    CI, on a school laptop with no internet, and in a country where sending a\n    child's data to a foreign API is a compliance question (spec section 09).\n\n    It also has a `misbehave` mode that fabricates statistics on purpose, so the\n    numeric scan is tested against the failure it exists to catch.\n    \"\"\"\n\n    name = \"mock\"\n\n    def __init__(self, misbehave: bool = False) -> None:\n        self.misbehave = misbehave\n\n    def complete(self, system: str, messages: List[Dict[str, str]],\n                 tools: List[Dict[str, Any]]) -> Dict[str, Any]:\n        last = messages[-1][\"content\"] if messages else \"\"\n        tool_results = [m for m in messages if m.get(\"role\") == \"tool\"]\n        available = {t[\"name\"] for t in tools}\n\n        if tool_results:\n            return {\"text\": self._explain(tool_results[-1], last), \"tool_call\": None}\n\n        call = self._plan(last, available)\n        if call is None:\n            return {\"text\": self._ask_back(last), \"tool_call\": None}\n        return {\"text\": \"\", \"tool_call\": call}\n\n    # -- planning ----------------------------------------------------------\n    def _plan(self, text: str, available: set) -> Optional[Dict[str, Any]]:\n        t = text.lower()\n        data = self._extract_groups(text)\n\n        if re.search(r\"how many (samples|replicates|tubes|do we need)|sample size|how big\", t):\n            if \"n_for_ttest\" in available:\n                return {\"name\": \"n_for_ttest\",\n                        \"arguments\": {\"effect_size\": 0.8, \"power\": 0.8}}\n        if data and len(data) >= 2:\n            if re.search(r\"differ|bigger|better|significant|compare|which.*most|effect\", t):\n                if \"compare_groups\" in available:\n                    return {\"name\": \"compare_groups\",\n                            \"arguments\": {\"groups\": data, \"design\": \"independent\",\n                                          \"justification\": \"Comparing independent groups measured \"\n                                                           \"under different conditions.\"}}\n                if \"shuffle_test\" in available and len(data) == 2:\n                    keys = list(data)\n                    return {\"name\": \"shuffle_test\",\n                            \"arguments\": {\"group_a\": data[keys[0]], \"group_b\": data[keys[1]],\n                                          \"justification\": \"Two small groups; shuffling assumes \"\n                                                           \"nothing about the data's shape.\"}}\n            if \"describe\" in available:\n                return {\"name\": \"describe\", \"arguments\": {\"groups\": data}}\n        if re.search(r\"\\bmoi\\b|multiplicity\", t) and \"moi\" in available:\n            nums = self._numbers(text)\n            if len(nums) >= 2:\n                return {\"name\": \"moi\", \"arguments\": {\"phage_pfu_per_mL\": nums[0],\n                                                     \"bacteria_cfu_per_mL\": nums[1]}}\n        if re.search(r\"pfu|titre|titer|plaque count\", t) and \"pfu_per_ml\" in available:\n            nums = self._numbers(text)\n            if len(nums) >= 2:\n                return {\"name\": \"pfu_per_ml\",\n                        \"arguments\": {\"plaque_count\": int(nums[0]), \"dilution_factor\": nums[1]}}\n        if re.search(r\"simulat|infect.*culture|what happens if\", t) and \"simulate\" in available:\n            model = (\"resistance\" if \"resist\" in t else\n                     \"lysogenic\" if (\"lysogen\" in t or \"hide\" in t) else \"lytic\")\n            return {\"name\": \"simulate\", \"arguments\": {\"model\": model, \"hours\": 48}}\n        if re.search(r\"no plaques|empty plate|nothing grew|sometimes\", t) and \\\n                \"poisson_plaques\" in available:\n            return {\"name\": \"poisson_plaques\", \"arguments\": {\"expected_plaques\": 3.0}}\n        return None\n\n    def _extract_groups(self, text: str) -> Dict[str, List[float]]:\n        \"\"\"Pull 'label: 1, 2, 3' groups out of a message.\"\"\"\n        out: Dict[str, List[float]] = {}\n        for m in re.finditer(r\"([A-Za-z][\\w .%-]{0,24}?)\\s*[:=]\\s*\"\n                             r\"((?:[-+]?\\d*\\.?\\d+\\s*[, ]\\s*){2,}[-+]?\\d*\\.?\\d+)\", text):\n            label = re.sub(r\"^(?:and|or|the|a|an|with|vs\\.?|versus)\\s+\", \"\", m.group(1).strip(),\n                           flags=re.IGNORECASE).strip()\n            vals = [float(x) for x in re.findall(r\"[-+]?\\d*\\.?\\d+\", m.group(2))]\n            if len(vals) >= 2:\n                out[label] = vals\n        return out\n\n    def _numbers(self, text: str) -> List[float]:\n        return [float(x.replace(\",\", \"\"))\n                for x in re.findall(r\"[-+]?\\d[\\d,]*\\.?\\d*(?:[eE][-+]?\\d+)?\", text)]\n\n    # -- explaining --------------------------------------------------------\n    def _explain(self, tool_msg: Dict[str, str], question: str) -> str:\n        try:\n            r = json.loads(tool_msg[\"content\"])\n        except Exception:\n            return \"I could not read that result.\"\n\n        if self.misbehave:\n            # Deliberately fabricated: the numeric scan must catch every one.\n            return (\"The difference is clearly significant, t(28) = 2.41, p = .023, with a large \"\n                    \"effect size of d = 0.91 and a 47% improvement over the control.\")\n\n        if r.get(\"refused\"):\n            return f\"I did not run that. {r.get('reason', '')}\"\n        if r.get(\"error\"):\n            return f\"That did not work: {r.get('message', '')}\"\n\n        parts: List[str] = []\n        stab = r.get(\"stability\") or {}\n        if stab.get(\"severity\") in (\"warn\", \"block\"):\n            parts.append(stab.get(\"verdict\", \"\"))\n        if r.get(\"plain_language\"):\n            parts.append(r[\"plain_language\"])\n        if r.get(\"why_this_test\"):\n            parts.append(f\"Why this test: {r['why_this_test']}\")\n        led = r.get(\"ledger\") or {}\n        if led.get(\"severity\") == \"warn\":\n            parts.append(led.get(\"message\", \"\"))\n        for n in (r.get(\"notes\") or [])[:2]:\n            parts.append(n)\n        if r.get(\"teaches\"):\n            parts.append(r[\"teaches\"])\n        parts.append(self._next_question(r))\n        return \" \".join(p for p in parts if p)\n\n    def _next_question(self, r: Dict[str, Any]) -> str:\n        if r.get(\"tool\") == \"compare_groups\":\n            return (\"What would you expect to happen if you ran the whole experiment again \"\n                    \"tomorrow -- the same result, or something different?\")\n        if r.get(\"tool\") in (\"simulate\", \"parameter_sweep\"):\n            return \"Which single parameter do you think the outcome depends on most, and why?\"\n        if r.get(\"tool\") == \"describe\":\n            return (\"Before we test anything: which group do you think is different, and what \"\n                    \"would convince you that you are wrong?\")\n        return \"What is the next thing you would measure to check this?\"\n\n    def _ask_back(self, text: str) -> str:\n        return (\"I need the numbers before I can do anything with them. Paste your table, or \"\n                \"write it like this: control: 12, 14, 11, 13 and treatment: 18, 21, 19, 20. \"\n                \"And tell me what you expected to happen before you looked.\")\n\n\n@dataclass\nclass Turn:\n    user_message: str\n    reply: str\n    tool_calls: List[Dict[str, Any]] = field(default_factory=list)\n    transcripts: List[str] = field(default_factory=list)\n    blocked: bool = False\n    block_reasons: List[str] = field(default_factory=list)\n    guard_reports: Dict[str, Any] = field(default_factory=dict)\n    redactions: List[str] = field(default_factory=list)\n    prompts: List[str] = field(default_factory=list)\n    at: float = field(default_factory=time.time)\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\nclass Assistant:\n    \"\"\"The turn loop, with every guard wired in.\"\"\"\n\n    def __init__(self, provider: Optional[LLMProvider] = None, grade: int = 8,\n                 store: Optional[TranscriptStore] = None,\n                 mode: str = \"block\", student_names: Optional[Sequence[str]] = None,\n                 require_prediction: bool = True) -> None:\n        self.provider = provider or MockProvider()\n        self.grade = int(grade)\n        self.store = store or get_store()\n        self.mode = mode\n        self.student_names = list(student_names or [])\n        self.require_prediction = require_prediction\n        self.prereg = guards.PreRegistrationLog()\n        self.detector = guards.SpecificationSearchDetector(self.store)\n        self.history: List[Dict[str, str]] = []\n        self.turns: List[Turn] = []\n        self._active_dataset: Optional[str] = None\n\n    # ------------------------------------------------------------------\n    def system_prompt(self) -> str:\n        names = \", \".join(registry.tools_for_grade(self.grade))\n        return SYSTEM_PROMPT.format(\n            grade=self.grade,\n            grade_words=_GRADE_WORDS.get(self.grade, \"a secondary student\"),\n            tool_names=names)\n\n    def register_prediction(self, dataset_id: str, question: str, prediction: str,\n                            direction: str = \"two-sided\", **kw) -> Dict[str, Any]:\n        pre = guards.PreRegistration(dataset_id=dataset_id, question=question,\n                                     prediction=prediction, direction=direction, **kw)\n        self._active_dataset = dataset_id\n        return self.prereg.register(pre)\n\n    # ------------------------------------------------------------------\n    def ask(self, message: str, dataset_id: Optional[str] = None) -> Turn:\n        turn = Turn(user_message=message, reply=\"\")\n        ds = dataset_id or self._active_dataset\n\n        # --- 1. PII redaction before anything leaves the device -----------\n        red = guards.redact_pii(message, self.student_names)\n        turn.redactions = red[\"redacted\"]\n        safe_message = red[\"text\"]\n\n        # --- 2. Specification search, by phrasing -------------------------\n        spec = self.detector.check_message(safe_message)\n        turn.guard_reports[\"specification_search_phrasing\"] = spec\n        if spec.get(\"detected\"):\n            turn.reply = spec[\"response\"]\n            turn.blocked = True\n            turn.block_reasons.append(\"specification_search\")\n            self.turns.append(turn)\n            return turn\n\n        # --- 3. Pre-registration gate -------------------------------------\n        wants_test = bool(re.search(\n            r\"\\b(test|significant|differ|compare|bigger|better|prove|effect)\\b\",\n            safe_message, re.IGNORECASE))\n        if self.require_prediction and wants_test and ds:\n            gate = self.prereg.gate(ds)\n            turn.guard_reports[\"preregistration\"] = gate\n            if not gate[\"allowed\"]:\n                turn.reply = gate[\"reason\"]\n                turn.blocked = True\n                turn.block_reasons.append(\"no_prediction\")\n                self.turns.append(turn)\n                return turn\n\n        # --- 4. Model proposes a tool call --------------------------------\n        self.history.append({\"role\": \"user\", \"content\": safe_message})\n        tools = registry.tool_schemas(grade=self.grade)\n        mark = self.store.marker()\n\n        step = self.provider.complete(self.system_prompt(), self.history, tools)\n        if step.get(\"tool_call\"):\n            call = step[\"tool_call\"]\n            result = registry.call_tool(call[\"name\"], call.get(\"arguments\", {}),\n                                        grade=self.grade)\n            turn.tool_calls.append({\"name\": call[\"name\"],\n                                    \"arguments\": call.get(\"arguments\", {}),\n                                    \"transcript_id\": result.get(\"transcript_id\"),\n                                    \"error\": result.get(\"error\")})\n            if result.get(\"transcript_id\"):\n                turn.transcripts.append(result[\"transcript_id\"])\n            self.history.append({\"role\": \"assistant\",\n                                 \"content\": f\"[called {call['name']}]\"})\n            self.history.append({\"role\": \"tool\",\n                                 \"content\": json.dumps(result, default=str)})\n            step = self.provider.complete(self.system_prompt(), self.history, tools)\n\n        text = step.get(\"text\", \"\")\n\n        # --- 5. Claim guard -----------------------------------------------\n        claims = guards.claim_guard(text)\n        turn.guard_reports[\"claims\"] = claims\n        if not claims[\"passed\"]:\n            turn.blocked = True\n            turn.block_reasons.append(\"unsupported_claim\")\n            text = \"\\n\\n\".join(v[\"message\"] for v in claims[\"violations\"])\n\n        # --- 6. Numeric scan ----------------------------------------------\n        # Scoped to THIS turn's transcripts: a number from a computation three\n        # questions ago is not evidence for a sentence written now.\n        turn_numbers: List[float] = []\n        scoped = TranscriptStore()\n        for t in self.store.since(mark):\n            scoped.put(t)\n        turn_numbers = scoped.numbers()\n\n        scan = guards.numeric_scan(text, allowed=turn_numbers, mode=self.mode)\n        turn.guard_reports[\"numeric_scan\"] = {\n            \"passed\": scan.passed, \"message\": scan.message,\n            \"unmatched\": scan.unmatched, \"n_checked\": len(scan.numbers_found),\n        }\n        if not scan.passed:\n            turn.blocked = True\n            turn.block_reasons.append(\"unverified_number\")\n            if self.mode == \"redact\":\n                text = scan.redacted_text\n            else:\n                text = (\n                    \"I was about to give you numbers I had not actually computed, and the \"\n                    \"platform stopped me -- which is exactly what it is there for. \"\n                    + scan.message\n                    + \" Ask me again and I will run the calculation properly first.\")\n\n        # --- 7. Specification search, by behaviour ------------------------\n        behaviour = self.detector.check_behaviour(ds or self._current_data_id(turn))\n        turn.guard_reports[\"specification_search_behaviour\"] = behaviour\n        if behaviour.get(\"detected\"):\n            text += \"\\n\\n\" + behaviour[\"response\"]\n\n        # --- 8. Pre-registration judgement --------------------------------\n        if ds and turn.transcripts:\n            last = self.store.get(turn.transcripts[-1])\n            if last and last.result.get(\"p_value\") is not None:\n                judged = self.prereg.judge(ds, last.result)\n                turn.guard_reports[\"prediction_judgement\"] = judged\n                if judged.get(\"judged\"):\n                    text += \"\\n\\n\" + judged[\"message\"]\n\n        turn.reply = text.strip()\n        self.history.append({\"role\": \"assistant\", \"content\": turn.reply})\n        self.turns.append(turn)\n        return turn\n\n    def _current_data_id(self, turn: Turn) -> Optional[str]:\n        for tid in reversed(turn.transcripts):\n            t = self.store.get(tid)\n            if t and t.data_id:\n                return t.data_id\n        return None\n\n    # ------------------------------------------------------------------\n    def transcript_panel(self, turn: Turn) -> List[Dict[str, Any]]:\n        \"\"\"What the UI shows alongside the reply. The transcript IS the product.\"\"\"\n        out = []\n        for tid in turn.transcripts:\n            t = self.store.get(tid)\n            if t:\n                out.append({\n                    \"transcript_id\": t.transcript_id, \"tool\": t.tool, \"call\": t.call,\n                    \"engine\": t.engine_string, \"duration_ms\": t.duration_ms,\n                    \"data_id\": t.data_id, \"params\": t.params,\n                    \"result\": t.result, \"at\": t.started_at,\n                })\n        return out\n",
  "phagequest_engine/assumptions.py": "\"\"\"Assumption checks that choose the test, rather than decorating it.\n\nGalaxy and BV-BRC have no statistical grammar (spec section 01); jamovi has the\nchecks but you must know to ask. Here the checks *drive the routing*: the engine\nruns them first, picks the test from the result, and reports both the choice and\nthe reason in `GroupComparison.test_used`, so a teacher who is not a statistician\ncan see why Kruskal-Wallis appeared instead of ANOVA.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, asdict\nfrom typing import Dict, List, Sequence\n\nimport numpy as np\nfrom scipy import stats\n\n__all__ = [\"AssumptionResult\", \"check_normality\", \"check_variance\", \"check_cell_counts\",\n           \"check_sample_size\", \"assumption_panel\"]\n\n\n@dataclass\nclass AssumptionResult:\n    name: str\n    passed: bool\n    statistic: float | None\n    p_value: float | None\n    detail: str\n    severity: str = \"info\"      # info | warn | block\n\n    def to_dict(self) -> Dict:\n        return asdict(self)\n\n\ndef _clean(x: Sequence[float]) -> np.ndarray:\n    a = np.asarray(x, dtype=float).ravel()\n    return a[np.isfinite(a)]\n\n\ndef check_normality(groups: Sequence[Sequence[float]], alpha: float = 0.05) -> AssumptionResult:\n    \"\"\"Shapiro-Wilk per group.\n\n    Note the honest framing in `detail`: at n=6 this test cannot detect\n    non-normality, so \"passed\" here means \"no evidence against\", not \"normal\".\n    The platform says so rather than letting a green tick imply more than it can.\n    \"\"\"\n    gs = [_clean(g) for g in groups]\n    usable = [g for g in gs if len(g) >= 3]\n    if not usable:\n        return AssumptionResult(\"normality\", False, None, None,\n                                \"Too few observations to assess normality at all.\", \"warn\")\n    ps, stat = [], None\n    for g in usable:\n        if len(g) > 5000 or np.allclose(g, g[0]):\n            continue\n        r = stats.shapiro(g)\n        ps.append(float(r.pvalue))\n        stat = float(r.statistic)\n    if not ps:\n        return AssumptionResult(\"normality\", True, None, None,\n                                \"Constant or very large groups; Shapiro-Wilk not applied.\", \"info\")\n    worst = min(ps)\n    smallest_n = min(len(g) for g in usable)\n    passed = worst >= alpha\n    if smallest_n < 10:\n        detail = (f\"Smallest p across groups = {worst:.3f}. With n={smallest_n} this test has very \"\n                  f\"little power, so this is not evidence that the data IS normal -- it is only the \"\n                  f\"absence of evidence that it is not. The engine will prefer a rank-based or \"\n                  f\"resampling test regardless.\")\n        sev = \"warn\"\n    else:\n        detail = f\"Smallest Shapiro-Wilk p across groups = {worst:.3f} (alpha {alpha}).\"\n        sev = \"info\" if passed else \"warn\"\n    return AssumptionResult(\"normality\", passed, stat, worst, detail, sev)\n\n\ndef check_variance(groups: Sequence[Sequence[float]], alpha: float = 0.05) -> AssumptionResult:\n    \"\"\"Levene's test (median-centred / Brown-Forsythe), robust to non-normality.\"\"\"\n    gs = [g for g in (_clean(x) for x in groups) if len(g) >= 2]\n    if len(gs) < 2:\n        return AssumptionResult(\"equal_variance\", False, None, None,\n                                \"Fewer than two usable groups.\", \"block\")\n    if any(np.allclose(g, g[0]) for g in gs):\n        return AssumptionResult(\"equal_variance\", True, None, None,\n                                \"At least one group has zero spread; Levene not applied.\", \"warn\")\n    r = stats.levene(*gs, center=\"median\")\n    passed = float(r.pvalue) >= alpha\n    ratio = max(g.var(ddof=1) for g in gs) / max(1e-300, min(g.var(ddof=1) for g in gs))\n    return AssumptionResult(\n        \"equal_variance\", passed, float(r.statistic), float(r.pvalue),\n        f\"Levene p = {float(r.pvalue):.3f}; largest/smallest variance ratio = {ratio:.1f}.\"\n        + (\"\" if passed else \" Welch / Alexander-Govern will be used instead of classical ANOVA.\"),\n        \"info\" if passed else \"warn\",\n    )\n\n\ndef check_cell_counts(table: np.ndarray, minimum: int = 5) -> AssumptionResult:\n    \"\"\"Expected-count rule for chi-square. Below it, Fisher's exact is used.\"\"\"\n    t = np.asarray(table, dtype=float)\n    if t.size == 0 or t.sum() == 0:\n        return AssumptionResult(\"expected_counts\", False, None, None, \"Empty table.\", \"block\")\n    expected = np.outer(t.sum(axis=1), t.sum(axis=0)) / t.sum()\n    worst = float(expected.min())\n    frac_low = float((expected < minimum).mean())\n    passed = worst >= minimum\n    return AssumptionResult(\n        \"expected_counts\", passed, worst, None,\n        f\"Smallest expected count = {worst:.2f}; {frac_low:.0%} of cells below {minimum}.\"\n        + (\"\" if passed else \" Chi-square is unreliable here; Fisher's exact test will be used.\"),\n        \"info\" if passed else \"warn\",\n    )\n\n\ndef check_sample_size(groups: Sequence[Sequence[float]], floor: int = 3) -> AssumptionResult:\n    \"\"\"The check that actually matters most for this user base.\n\n    A class dataset is n=4 to n=30. Below `floor` per group, the engine refuses\n    to run an inferential test at all and returns a descriptive answer -- a\n    refusal is a better lesson than a p-value computed on three points.\n    \"\"\"\n    ns = [len(_clean(g)) for g in groups]\n    smallest = min(ns) if ns else 0\n    passed = smallest >= floor\n    sev = \"info\" if smallest >= 5 else (\"warn\" if passed else \"block\")\n    return AssumptionResult(\n        \"sample_size\", passed, float(smallest), None,\n        f\"Group sizes: {ns}.\"\n        + (\"\" if smallest >= 5 else\n           f\" With only {smallest} observations in the smallest group, any conclusion is fragile; \"\n           f\"the stability check below is the number to read, not the p-value.\"),\n        sev,\n    )\n\n\ndef assumption_panel(groups: Sequence[Sequence[float]], alpha: float = 0.05) -> List[AssumptionResult]:\n    return [check_sample_size(groups), check_normality(groups, alpha), check_variance(groups, alpha)]\n",
  "phagequest_engine/curves.py": "\"\"\"Curve fitting with honest uncertainty (spec section 04, row 5).\n\n    \"G8-L12 rate vs substrate, enzyme, pH, temperature -- four dose-response\n    curves the students already tabulate by hand. CRITICAL: `pip install drc`\n    installs a Django comment module, NOT the R dose-response package. There is\n    no Python `drc`. Use `lmfit` with an explicit four-parameter logistic.\"\n\nlmfit is the Tier-1 choice and is not in Pyodide, so Tier-0 uses\n`scipy.optimize.curve_fit` with named parameters, bounds and bootstrap\nintervals -- which is what we wanted lmfit for. Every model here is explicit;\nnothing is auto-selected behind the student's back.\n\nA fitted rate without an interval teaches the wrong lesson, so `conf_interval`\nis not optional here either.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Callable, Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nfrom scipy import optimize, stats\n\nfrom .transcript import bound\n\n__all__ = [\"MODELS\", \"fit_curve\", \"fit_growth_curve\", \"compare_models\"]\n\n\ndef _four_pl(x, bottom, top, ec50, hill):\n    \"\"\"Four-parameter logistic. The dose-response workhorse.\"\"\"\n    return bottom + (top - bottom) / (1.0 + (x / np.maximum(ec50, 1e-12)) ** (-hill))\n\n\ndef _michaelis_menten(x, vmax, km):\n    \"\"\"Enzyme kinetics: rate vs substrate. G8-L12 sweep 1.\"\"\"\n    return vmax * x / (km + x)\n\n\ndef _logistic_growth(x, K, r, t0):\n    \"\"\"Population growth to a carrying capacity.\"\"\"\n    return K / (1.0 + np.exp(-r * (x - t0)))\n\n\ndef _gompertz(x, A, mu, lag):\n    \"\"\"Gompertz with an explicit lag phase -- the standard microbial growth form.\"\"\"\n    return A * np.exp(-np.exp((mu * np.e / A) * (lag - x) + 1.0))\n\n\ndef _exponential(x, a, k):\n    return a * np.exp(k * x)\n\n\ndef _linear(x, slope, intercept):\n    return slope * x + intercept\n\n\ndef _gaussian_optimum(x, peak, optimum, width):\n    \"\"\"Rate against a variable with an optimum -- pH and temperature sweeps.\n\n    G8-L9 (four pH levels) and G6-L9 (three temperatures) both produce this\n    shape, and fitting it is how a student gets a number for \"the best pH\" with\n    an interval, rather than pointing at the tallest bar.\n    \"\"\"\n    return peak * np.exp(-0.5 * ((x - optimum) / np.maximum(width, 1e-12)) ** 2)\n\n\nMODELS: Dict[str, Dict[str, Any]] = {\n    \"four_pl\": {\n        \"fn\": _four_pl, \"params\": [\"bottom\", \"top\", \"ec50\", \"hill\"],\n        \"label\": \"Four-parameter logistic (dose-response)\",\n        \"guess\": lambda x, y: [float(np.min(y)), float(np.max(y)),\n                               float(np.median(x[x > 0]) if np.any(x > 0) else 1.0), 1.0],\n        \"bounds\": lambda x, y: ([-np.inf, -np.inf, 1e-9, -20], [np.inf, np.inf, np.inf, 20]),\n        \"teaches\": \"EC50 is the dose that gets you halfway. It is the number the curve exists to give you.\",\n    },\n    \"michaelis_menten\": {\n        \"fn\": _michaelis_menten, \"params\": [\"vmax\", \"km\"],\n        \"label\": \"Michaelis-Menten (enzyme kinetics)\",\n        \"guess\": lambda x, y: [float(np.max(y) * 1.1), float(np.median(x[x > 0]) if np.any(x > 0) else 1.0)],\n        \"bounds\": lambda x, y: ([0, 1e-12], [np.inf, np.inf]),\n        \"teaches\": \"Vmax is the ceiling; Km is the substrate level that reaches half of it. \"\n                   \"If your highest substrate is below Km, Vmax is an extrapolation, not a measurement.\",\n    },\n    \"logistic_growth\": {\n        \"fn\": _logistic_growth, \"params\": [\"K\", \"r\", \"t0\"],\n        \"label\": \"Logistic growth (S-curve to a carrying capacity)\",\n        \"guess\": lambda x, y: [float(np.max(y) * 1.05), 1.0, float(np.median(x))],\n        \"bounds\": lambda x, y: ([0, -np.inf, -np.inf], [np.inf, np.inf, np.inf]),\n        \"teaches\": \"K is how many the flask can hold; r is how fast they get there.\",\n    },\n    \"gompertz\": {\n        \"fn\": _gompertz, \"params\": [\"A\", \"mu\", \"lag\"],\n        \"label\": \"Gompertz growth (with an explicit lag phase)\",\n        \"guess\": lambda x, y: [float(np.max(y)), 1.0, float(np.min(x))],\n        \"bounds\": lambda x, y: ([1e-12, 1e-12, -np.inf], [np.inf, np.inf, np.inf]),\n        \"teaches\": \"The lag parameter is how long the culture sat there doing nothing before growing. \"\n                   \"That waiting time is a real, measurable biological quantity.\",\n    },\n    \"exponential\": {\n        \"fn\": _exponential, \"params\": [\"a\", \"k\"],\n        \"label\": \"Exponential\",\n        \"guess\": lambda x, y: [float(max(1e-9, np.min(np.abs(y)))), 0.1],\n        \"bounds\": lambda x, y: ([-np.inf, -np.inf], [np.inf, np.inf]),\n        \"teaches\": \"k is the growth rate; doubling time is ln(2)/k.\",\n    },\n    \"linear\": {\n        \"fn\": _linear, \"params\": [\"slope\", \"intercept\"],\n        \"label\": \"Straight line\",\n        \"guess\": lambda x, y: [1.0, 0.0],\n        \"bounds\": lambda x, y: ([-np.inf, -np.inf], [np.inf, np.inf]),\n        \"teaches\": \"The simplest model. Always fit it too: if a curve is not clearly better than a \"\n                   \"line, you have not earned the curve.\",\n    },\n    \"optimum\": {\n        \"fn\": _gaussian_optimum, \"params\": [\"peak\", \"optimum\", \"width\"],\n        \"label\": \"Peak with an optimum (pH / temperature response)\",\n        \"guess\": lambda x, y: [float(np.max(y)), float(x[np.argmax(y)]),\n                               float(max(1e-6, np.ptp(x) / 4))],\n        \"bounds\": lambda x, y: ([0, -np.inf, 1e-9], [np.inf, np.inf, np.inf]),\n        \"teaches\": \"The 'optimum' parameter is the best pH or temperature WITH an interval -- which \"\n                   \"is a real answer, unlike pointing at whichever bar happened to be tallest.\",\n    },\n}\n\n\ndef _fit_once(fn, x, y, p0, bounds, maxfev=20000):\n    popt, pcov = optimize.curve_fit(fn, x, y, p0=p0, bounds=bounds, maxfev=maxfev)\n    return popt, pcov\n\n\n@bound(\"fit_curve\", data_args=(\"x\", \"y\"))\ndef fit_curve(x: Sequence[float], y: Sequence[float], model: str = \"four_pl\",\n              n_boot: int = 800, seed: int = 20260901,\n              p0: Optional[List[float]] = None) -> Dict[str, Any]:\n    \"\"\"Fit a named model and report every parameter with a bootstrap interval.\n\n    Refuses to fit a model with more parameters than the data can support --\n    four points cannot determine a four-parameter logistic, and a platform that\n    lets a student do it anyway has taught them something false.\n    \"\"\"\n    xa = np.asarray(x, dtype=float).ravel()\n    ya = np.asarray(y, dtype=float).ravel()\n    m = np.isfinite(xa) & np.isfinite(ya)\n    xa, ya = xa[m], ya[m]\n\n    spec = MODELS.get(model)\n    if spec is None:\n        return {\"refused\": True, \"reason\": f\"Unknown model {model!r}. Available: {sorted(MODELS)}.\",\n                \"available_models\": sorted(MODELS)}\n\n    k = len(spec[\"params\"])\n    if xa.size < k + 1:\n        return {\n            \"refused\": True,\n            \"reason\": (f\"The {spec['label']} has {k} parameters and you have {xa.size} data points. \"\n                       f\"A model needs more points than parameters, and comfortably more than that \"\n                       f\"to mean anything. With {xa.size} points, try the 'linear' model or collect \"\n                       f\"more concentrations.\"),\n            \"n\": int(xa.size), \"n_parameters\": k,\n        }\n\n    guess = p0 if p0 is not None else spec[\"guess\"](xa, ya)\n    lo, hi = spec[\"bounds\"](xa, ya)\n    guess = [float(np.clip(g, l + 1e-12 if np.isfinite(l) else g, h - 1e-12 if np.isfinite(h) else g))\n             for g, l, h in zip(guess, lo, hi)]\n    try:\n        popt, pcov = _fit_once(spec[\"fn\"], xa, ya, guess, (lo, hi))\n    except Exception as exc:\n        return {\"refused\": True, \"reason\": f\"The fit did not converge ({type(exc).__name__}). \"\n                                           f\"This usually means the model is the wrong shape for \"\n                                           f\"this data. Plot it first.\"}\n\n    pred = spec[\"fn\"](xa, *popt)\n    resid = ya - pred\n    ss_res = float((resid ** 2).sum())\n    ss_tot = float(((ya - ya.mean()) ** 2).sum())\n    r2 = 1 - ss_res / ss_tot if ss_tot > 0 else float(\"nan\")\n    n = xa.size\n    adj_r2 = 1 - (1 - r2) * (n - 1) / (n - k - 1) if n > k + 1 else float(\"nan\")\n    aicc = (n * np.log(ss_res / n) + 2 * k + (2 * k * (k + 1)) / max(1, n - k - 1)\n            if ss_res > 0 else -np.inf)\n\n    # Bootstrap the parameters -- the covariance matrix from curve_fit assumes\n    # normal residuals and large n, neither of which a class dataset has.\n    rng = np.random.default_rng(seed)\n    boots = np.full((n_boot, k), np.nan)\n    for i in range(n_boot):\n        idx = rng.integers(0, n, n)\n        if np.unique(xa[idx]).size < k + 1:\n            continue\n        try:\n            b, _ = _fit_once(spec[\"fn\"], xa[idx], ya[idx], list(popt), (lo, hi), maxfev=6000)\n            boots[i] = b\n        except Exception:\n            continue\n    ok = ~np.isnan(boots).any(axis=1)\n    boots = boots[ok]\n\n    params = {}\n    for j, name in enumerate(spec[\"params\"]):\n        if boots.shape[0] >= 50:\n            ci = [float(np.percentile(boots[:, j], 2.5)), float(np.percentile(boots[:, j], 97.5))]\n            se = float(boots[:, j].std(ddof=1))\n        else:\n            se = float(np.sqrt(np.diag(pcov))[j]) if np.all(np.isfinite(pcov)) else float(\"nan\")\n            tcrit = stats.t.ppf(0.975, max(1, n - k))\n            ci = [float(popt[j] - tcrit * se), float(popt[j] + tcrit * se)]\n        params[name] = {\"value\": float(popt[j]), \"se\": se, \"ci\": ci,\n                        \"relative_width\": float(abs(ci[1] - ci[0]) / max(1e-12, abs(popt[j])))}\n\n    curve_x = np.linspace(float(xa.min()), float(xa.max()), 120)\n    curve_y = spec[\"fn\"](curve_x, *popt)\n    if boots.shape[0] >= 50:\n        band = np.array([spec[\"fn\"](curve_x, *b) for b in boots])\n        band_lo = np.percentile(band, 2.5, axis=0).tolist()\n        band_hi = np.percentile(band, 97.5, axis=0).tolist()\n    else:\n        band_lo = band_hi = []\n\n    wobbly = [p for p, v in params.items() if v[\"relative_width\"] > 1.0]\n    notes = []\n    if wobbly:\n        notes.append(\n            f\"The interval for {', '.join(wobbly)} is wider than the estimate itself. That parameter \"\n            f\"is not actually determined by your data -- do not quote it as a result.\")\n    if r2 > 0.99 and n <= k + 2:\n        notes.append(\n            f\"R-squared of {r2:.3f} with only {n} points and {k} parameters is not impressive -- a \"\n            f\"model with almost as many knobs as points will always fit. Look at the intervals.\")\n\n    return {\n        \"model\": model, \"model_label\": spec[\"label\"], \"teaches\": spec[\"teaches\"],\n        \"parameters\": params,\n        \"parameter_names\": spec[\"params\"],\n        \"point_estimates\": [float(v) for v in popt],\n        \"r_squared\": float(r2), \"adjusted_r_squared\": float(adj_r2), \"aicc\": float(aicc),\n        \"rmse\": float(np.sqrt(ss_res / n)),\n        \"n\": int(n), \"n_parameters\": k,\n        \"n_bootstrap_fits\": int(boots.shape[0]),\n        \"curve\": {\"x\": curve_x.tolist(), \"y\": curve_y.tolist(),\n                  \"band_low\": band_lo, \"band_high\": band_hi},\n        \"residuals\": resid.tolist(),\n        \"notes\": notes,\n        \"plain_language\": (\n            f\"Fitted {spec['label']}. It explains {r2 * 100:.1f}% of the variation in your \"\n            f\"{n} points. \"\n            + \"; \".join(f\"{name} = {v['value']:.4g} (95% CI {v['ci'][0]:.4g} to {v['ci'][1]:.4g})\"\n                        for name, v in params.items())\n            + \". \" + spec[\"teaches\"]),\n    }\n\n\n@bound(\"compare_models\", data_args=(\"x\", \"y\"))\ndef compare_models(x: Sequence[float], y: Sequence[float],\n                   models: Optional[List[str]] = None, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"Fit several models to the same data and rank them by AICc.\n\n    Always includes 'linear', because the honest question is never \"does my\n    curve fit?\" but \"does my curve fit BETTER THAN A STRAIGHT LINE, by enough\n    to justify the extra parameters?\" AICc, not R-squared, because R-squared\n    always rewards more parameters.\n    \"\"\"\n    candidates = list(models or [\"linear\", \"exponential\", \"michaelis_menten\", \"four_pl\"])\n    if \"linear\" not in candidates:\n        candidates.insert(0, \"linear\")\n\n    fits = []\n    for mname in candidates:\n        try:\n            r = fit_curve.__wrapped__(x, y, model=mname, n_boot=200, seed=seed)\n        except Exception:\n            continue\n        if r.get(\"refused\"):\n            fits.append({\"model\": mname, \"refused\": True, \"reason\": r.get(\"reason\")})\n            continue\n        fits.append({\"model\": mname, \"model_label\": r[\"model_label\"], \"aicc\": r[\"aicc\"],\n                     \"r_squared\": r[\"r_squared\"], \"adjusted_r_squared\": r[\"adjusted_r_squared\"],\n                     \"n_parameters\": r[\"n_parameters\"],\n                     \"parameters\": {k: v[\"value\"] for k, v in r[\"parameters\"].items()},\n                     \"refused\": False})\n\n    usable = [f for f in fits if not f[\"refused\"] and np.isfinite(f[\"aicc\"])]\n    if not usable:\n        return {\"refused\": True, \"reason\": \"No model could be fitted to this data.\", \"fits\": fits}\n\n    best = min(usable, key=lambda f: f[\"aicc\"])\n    for f in usable:\n        f[\"delta_aicc\"] = float(f[\"aicc\"] - best[\"aicc\"])\n        # Akaike weights: the probability each model is the best of this set.\n        f[\"weight\"] = float(np.exp(-0.5 * f[\"delta_aicc\"]))\n    tot = sum(f[\"weight\"] for f in usable)\n    for f in usable:\n        f[\"weight\"] = float(f[\"weight\"] / tot)\n\n    lin = next((f for f in usable if f[\"model\"] == \"linear\"), None)\n    verdict = \"\"\n    if lin is not None and best[\"model\"] != \"linear\":\n        d = lin[\"delta_aicc\"]\n        verdict = (f\"The curve beats a straight line by {d:.1f} AICc units\"\n                   + (\" -- strong enough to be worth the extra parameters.\"\n                      if d > 4 else\n                      \" -- which is not a decisive margin. With this much data, a straight line is \"\n                      \"an honest description too.\"))\n    elif lin is not None:\n        verdict = \"A straight line describes this data as well as any curve tried. Use the line.\"\n\n    return {\n        \"fits\": sorted(usable, key=lambda f: f[\"aicc\"]) + [f for f in fits if f[\"refused\"]],\n        \"best_model\": best[\"model\"], \"best_model_label\": best[\"model_label\"],\n        \"plain_language\": (\n            f\"Of {len(usable)} models tried, {best['model_label']} fits best \"\n            f\"(AICc weight {best['weight']:.0%}). {verdict} \"\n            f\"AICc is used rather than R-squared because R-squared always improves when you add \"\n            f\"parameters, whether or not they mean anything.\"),\n    }\n\n\n@bound(\"fit_growth_curve\", data_args=(\"time\", \"density\"))\ndef fit_growth_curve(time: Sequence[float], density: Sequence[float],\n                     model: str = \"gompertz\", seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"Growth-curve analysis with the phage-relevant parameters named.\n\n    `gcplyr` (spec section 03.3) is R and GPL; this is the Tier-0 equivalent for\n    the parameters a school actually reports: lag, maximum growth rate, and\n    carrying capacity -- plus, for lysis-shaped curves, the time and depth of\n    the crash, which is the whole point when a phage is in the flask.\n    \"\"\"\n    t = np.asarray(time, dtype=float).ravel()\n    d = np.asarray(density, dtype=float).ravel()\n    m = np.isfinite(t) & np.isfinite(d)\n    t, d = t[m], d[m]\n    if t.size < 5:\n        return {\"refused\": True, \"reason\": f\"Only {t.size} readings; a growth curve needs at least 5.\"}\n\n    order = np.argsort(t)\n    t, d = t[order], d[order]\n\n    peak_i = int(np.argmax(d))\n    crashed = bool(peak_i < t.size - 2 and d[-1] < 0.6 * d[peak_i])\n\n    if crashed:\n        # Lysis: fit growth on the rising limb only, and report the crash separately.\n        fit_t, fit_d = t[:peak_i + 1], d[:peak_i + 1]\n        note = (\"This culture rose and then crashed -- the signature of lysis. The growth model is \"\n                \"fitted only to the rising part; fitting it through the crash would produce a \"\n                \"meaningless carrying capacity. The crash itself is reported separately below, and \"\n                \"it is the interesting half.\")\n    else:\n        fit_t, fit_d = t, d\n        note = \"\"\n\n    res = fit_curve.__wrapped__(fit_t, fit_d, model=model, n_boot=500, seed=seed) \\\n        if fit_t.size >= 5 else {\"refused\": True, \"reason\": \"Too few points on the rising limb.\"}\n\n    # Model-free descriptors, always computed, because they need no fit to be true.\n    with np.errstate(divide=\"ignore\", invalid=\"ignore\"):\n        logd = np.log(np.maximum(d, 1e-12))\n    dt = np.diff(t)\n    slopes = np.divide(np.diff(logd), dt, out=np.full(dt.shape, np.nan), where=dt > 0)\n    mu_max = float(np.nanmax(slopes)) if np.any(np.isfinite(slopes)) else float(\"nan\")\n    doubling = float(np.log(2) / mu_max) if np.isfinite(mu_max) and mu_max > 0 else float(\"nan\")\n\n    out = {\n        \"model\": model, \"lysis_detected\": crashed,\n        \"empirical\": {\n            \"max_density\": float(d.max()), \"time_of_max\": float(t[peak_i]),\n            \"final_density\": float(d[-1]),\n            \"max_specific_growth_rate\": mu_max,\n            \"doubling_time\": doubling,\n            \"auc\": float(np.trapezoid(d, t)) if hasattr(np, \"trapezoid\") else float(np.trapz(d, t)),\n        },\n        \"fit\": res,\n        \"notes\": [n for n in [note] if n],\n        \"p_value\": None,\n    }\n    if crashed:\n        drop = float((d[peak_i] - d[-1]) / max(1e-12, d[peak_i]))\n        out[\"lysis\"] = {\n            \"peak_time\": float(t[peak_i]), \"peak_density\": float(d[peak_i]),\n            \"final_density\": float(d[-1]), \"fractional_drop\": drop,\n            \"time_to_half_peak\": float(\n                next((t[i] for i in range(peak_i, t.size) if d[i] <= 0.5 * d[peak_i]), np.nan)),\n        }\n    out[\"plain_language\"] = (\n        f\"Maximum growth rate {mu_max:.4g} per unit time\"\n        + (f\" (doubling time {doubling:.3g})\" if np.isfinite(doubling) else \"\")\n        + f\", peaking at {d.max():.4g} around t = {t[peak_i]:g}.\"\n        + (f\" The culture then fell by {out['lysis']['fractional_drop'] * 100:.0f}% -- that is lysis, \"\n           f\"and its timing is what tells you about the phage.\" if crashed else \"\"))\n    return out\n",
  "phagequest_engine/diversity.py": "\"\"\"Diversity and composition (spec section 04, row 7).\n\n    \"MUST ENCODE: relative abundances sum to 1, which violates the independence\n    assumption of every test in row 1. Without CLR, the platform will teach\n    students to produce spurious results with great confidence.\"\n\nThat warning is the design brief for this module. `compare_composition` refuses\nto run an ordinary group comparison on proportions and routes to CLR + PERMANOVA\ninstead, and it says why in words a Grade 9 can follow.\n\nscikit-bio is the Tier-1 choice (BSD) but is not in Pyodide. Everything here is\nnumpy/scipy, so the Winogradsky lesson (G9-L12) works offline in a browser on a\nschool PC, which was the whole point.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Dict, List, Optional, Sequence\n\nimport numpy as np\nfrom scipy import stats\nfrom scipy.spatial.distance import pdist, squareform\n\nfrom .transcript import bound\n\n__all__ = [\"alpha_diversity\", \"beta_diversity\", \"clr_transform\", \"permanova\",\n           \"compare_composition\", \"rarefaction_curve\"]\n\n\ndef _counts_matrix(samples: Dict[str, Dict[str, float]]) -> tuple:\n    taxa = sorted({t for s in samples.values() for t in s})\n    names = list(samples)\n    M = np.array([[float(samples[n].get(t, 0.0)) for t in taxa] for n in names])\n    return names, taxa, M\n\n\n@bound(\"alpha_diversity\", data_args=(\"samples\",))\ndef alpha_diversity(samples: Dict[str, Dict[str, float]]) -> Dict[str, Any]:\n    \"\"\"Richness, Shannon, Simpson, Chao1, Pielou's evenness -- per sample.\n\n    Serves G9-L12: compare microbial communities across Winogradsky layers.\n\n    Chao1 is included because it answers the question a student always asks\n    next -- \"but how many did we MISS?\" -- from the singletons and doubletons\n    they can see in their own count table.\n    \"\"\"\n    names, taxa, M = _counts_matrix(samples)\n    if M.size == 0:\n        return {\"refused\": True, \"reason\": \"No taxa found.\"}\n\n    out = {}\n    for name, row in zip(names, M):\n        total = row.sum()\n        obs = int((row > 0).sum())\n        if total <= 0:\n            out[name] = {\"n_observed\": 0, \"total_count\": 0}\n            continue\n        p = row[row > 0] / total\n        shannon = float(-(p * np.log(p)).sum())\n        simpson = float(1.0 - (p ** 2).sum())\n        inv_simpson = float(1.0 / (p ** 2).sum())\n        evenness = float(shannon / np.log(obs)) if obs > 1 else float(\"nan\")\n        f1 = int((row == 1).sum())\n        f2 = int((row == 2).sum())\n        chao1 = obs + (f1 * (f1 - 1)) / (2 * (f2 + 1))\n        out[name] = {\n            \"n_observed\": obs, \"total_count\": int(total),\n            \"shannon\": shannon, \"simpson\": simpson, \"inverse_simpson\": inv_simpson,\n            \"pielou_evenness\": evenness,\n            \"chao1\": float(chao1),\n            \"singletons\": f1, \"doubletons\": f2,\n            \"estimated_unseen\": float(chao1 - obs),\n        }\n\n    best = max(out, key=lambda k: out[k].get(\"shannon\", -1)) if out else None\n    depths = [v.get(\"total_count\", 0) for v in out.values()]\n    uneven = max(depths) > 3 * max(1, min(depths)) if depths else False\n\n    if best is None:\n        headline = \"\"\n    else:\n        b = out[best]\n        headline = (f\"{best} is the most diverse (Shannon {b['shannon']:.2f}, \"\n                    f\"{b['n_observed']} kinds seen\")\n        headline += (f\", Chao1 estimates about {b['chao1']:.0f} really present).\"\n                     if b.get(\"estimated_unseen\", 0) > 0.5 else \").\")\n\n    return {\n        \"samples\": out, \"taxa\": taxa, \"n_taxa\": len(taxa),\n        \"most_diverse\": best,\n        \"sequencing_depth_warning\": (\n            f\"Your samples were counted to very different depths ({min(depths)} to {max(depths)}). \"\n            f\"More counting finds more taxa, so a deeper sample looks more diverse whether or not \"\n            f\"it is. Rarefy to the smallest depth before comparing, or compare evenness instead of \"\n            f\"richness.\" if uneven else None),\n        \"teaches\": (\n            \"Richness counts how many kinds there are. Shannon and Simpson also ask how EVENLY \"\n            \"they are spread: a layer with one dominant organism and nine rare ones is less \"\n            \"diverse than a layer with ten equal ones, even though both have ten kinds.\"),\n        \"plain_language\": f\"{len(out)} samples across {len(taxa)} taxa. {headline}\",\n        \"p_value\": None,\n    }\n\n\n@bound(\"clr_transform\", data_args=(\"samples\",))\ndef clr_transform(samples: Dict[str, Dict[str, float]], pseudocount: float = 0.5\n                  ) -> Dict[str, Any]:\n    \"\"\"Centred log-ratio transform -- the fix for compositional data.\n\n    Why it matters, in the terms a student can check: if one organism doubles,\n    every OTHER organism's percentage goes down, even though nothing happened\n    to them. Percentages are not independent measurements, so the t-tests and\n    ANOVAs in `inference` are invalid on them. CLR divides each count by the\n    geometric mean of its sample and takes a log, which breaks that forced\n    dependence.\n\n    The pseudocount is a real choice with a real consequence, so it is a named\n    parameter and its effect is reported rather than hidden.\n    \"\"\"\n    names, taxa, M = _counts_matrix(samples)\n    if M.size == 0:\n        return {\"refused\": True, \"reason\": \"No taxa found.\"}\n    zeros = int((M == 0).sum())\n    X = M + float(pseudocount)\n    gm = np.exp(np.log(X).mean(axis=1, keepdims=True))\n    C = np.log(X / gm)\n    return {\n        \"names\": names, \"taxa\": taxa,\n        \"clr\": C.tolist(),\n        \"pseudocount\": float(pseudocount),\n        \"n_zeros_replaced\": zeros,\n        \"zero_fraction\": float(zeros / M.size),\n        \"note\": (\"scikit-bio renamed `multiplicative_replacement` to `multi_replace`; this \"\n                 \"implementation depends on neither. The pseudocount above was added to \"\n                 f\"{zeros} zero cells ({zeros / M.size:.0%} of the table). A different pseudocount \"\n                 f\"gives different CLR values -- if your conclusion changes when you change it, \"\n                 f\"your conclusion is about the pseudocount.\"),\n        \"teaches\": (\n            \"Percentages of a whole cannot move independently. If the bacteria double, the \"\n            \"percentage of everything else falls without anything happening to it. CLR is how you \"\n            \"get back to numbers that can be compared.\"),\n        \"plain_language\": (\n            f\"Transformed {len(names)} samples x {len(taxa)} taxa to centred log-ratios. \"\n            f\"Positive means that taxon is above the sample's typical level; negative means below. \"\n            f\"These values CAN be compared between samples; raw percentages cannot.\"),\n        \"p_value\": None,\n    }\n\n\n@bound(\"beta_diversity\", data_args=(\"samples\",))\ndef beta_diversity(samples: Dict[str, Dict[str, float]], metric: str = \"braycurtis\"\n                   ) -> Dict[str, Any]:\n    \"\"\"Between-sample distances, plus a PCoA ordination.\n\n    `aitchison` is the compositionally correct metric (Euclidean distance on\n    CLR values) and is what the platform recommends. Bray-Curtis is offered\n    because it is what the literature a student will read uses.\n    \"\"\"\n    names, taxa, M = _counts_matrix(samples)\n    if M.shape[0] < 2:\n        return {\"refused\": True, \"reason\": \"Need at least two samples.\"}\n\n    if metric == \"aitchison\":\n        clr = clr_transform.__wrapped__(samples)\n        X = np.asarray(clr[\"clr\"])\n        D = squareform(pdist(X, metric=\"euclidean\"))\n        why = (\"Aitchison distance: Euclidean distance on CLR values. This is the metric that \"\n               \"respects the fact that your data are proportions.\")\n    elif metric == \"jaccard\":\n        B = (M > 0).astype(float)\n        D = squareform(pdist(B, metric=\"jaccard\"))\n        why = \"Jaccard: presence/absence only. Ignores how MUCH of each taxon there is.\"\n    else:\n        rel = M / np.maximum(M.sum(axis=1, keepdims=True), 1e-12)\n        D = squareform(pdist(rel, metric=\"braycurtis\"))\n        why = (\"Bray-Curtis on relative abundances. Widely used and easy to read, but it is a \"\n               \"distance between proportions, so significance tests on it need PERMANOVA \"\n               \"(permutation-based), never a t-test.\")\n\n    # Principal coordinates analysis: double-centre, then eigendecompose.\n    n = D.shape[0]\n    J = np.eye(n) - np.ones((n, n)) / n\n    B = -0.5 * J @ (D ** 2) @ J\n    vals, vecs = np.linalg.eigh(B)\n    order = np.argsort(vals)[::-1]\n    vals, vecs = vals[order], vecs[:, order]\n    pos = vals > 1e-12\n    coords = vecs[:, pos] * np.sqrt(vals[pos])\n    explained = (vals[pos] / vals[pos].sum()).tolist() if pos.any() else []\n\n    return {\n        \"names\": names, \"metric\": metric, \"why_this_metric\": why,\n        \"distance_matrix\": D.tolist(),\n        \"pcoa\": {\n            \"coordinates\": coords[:, :3].tolist() if coords.shape[1] >= 1 else [],\n            \"explained_variance\": explained[:5],\n            \"axis_labels\": [f\"PCo{i + 1} ({e:.0%})\" for i, e in enumerate(explained[:3])],\n        },\n        \"most_similar_pair\": _closest_pair(names, D),\n        \"most_different_pair\": _farthest_pair(names, D),\n        \"plain_language\": (\n            f\"Compared {n} samples using {metric}. \"\n            + (f\"The first two ordination axes carry {sum(explained[:2]):.0%} of the differences. \"\n               if len(explained) >= 2 else \"\")\n            + f\"The two most similar samples are {_closest_pair(names, D)}; the two most different \"\n              f\"are {_farthest_pair(names, D)}.\"),\n        \"p_value\": None,\n    }\n\n\ndef _closest_pair(names, D):\n    d = D.copy()\n    np.fill_diagonal(d, np.inf)\n    i, j = np.unravel_index(np.argmin(d), d.shape)\n    return f\"{names[i]} and {names[j]}\"\n\n\ndef _farthest_pair(names, D):\n    i, j = np.unravel_index(np.argmax(D), D.shape)\n    return f\"{names[i]} and {names[j]}\"\n\n\n@bound(\"permanova\", data_args=(\"distance_matrix\", \"groups\"))\ndef permanova(distance_matrix: Sequence[Sequence[float]], groups: Sequence[str],\n              n_permutations: int = 9999, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"PERMANOVA: is the difference between groups of communities real?\n\n    The right test for community data, and -- usefully -- it is the same idea\n    as the Grade 7 shuffle test: compute a statistic, shuffle the labels many\n    times, see how often chance does as well. Same lesson, bigger object.\n    \"\"\"\n    D = np.asarray(distance_matrix, dtype=float)\n    g = np.asarray([str(x) for x in groups])\n    n = D.shape[0]\n    if D.shape[0] != D.shape[1] or g.size != n:\n        return {\"refused\": True, \"reason\": \"Distance matrix and group labels must match in size.\"}\n    levels = sorted(set(g.tolist()))\n    if len(levels) < 2:\n        return {\"refused\": True, \"reason\": \"Need at least two groups.\"}\n    if n < 6:\n        return {\"refused\": True, \"reason\": f\"Only {n} samples. PERMANOVA needs at least 6 to say \"\n                                           f\"anything, and really wants 5 per group.\"}\n\n    def pseudo_f(labels: np.ndarray) -> float:\n        sst = float((D ** 2).sum() / (2 * n))\n        ssw = 0.0\n        for lv in levels:\n            idx = np.nonzero(labels == lv)[0]\n            k = idx.size\n            if k < 2:\n                continue\n            sub = D[np.ix_(idx, idx)]\n            ssw += float((sub ** 2).sum() / (2 * k))\n        ssb = sst - ssw\n        a, N = len(levels), n\n        denom = ssw / (N - a) if N > a else np.nan\n        return float((ssb / (a - 1)) / denom) if denom and denom > 0 else float(\"nan\")\n\n    observed = pseudo_f(g)\n    rng = np.random.default_rng(seed)\n    null = np.array([pseudo_f(rng.permutation(g)) for _ in range(int(n_permutations))])\n    null = null[np.isfinite(null)]\n    count = int((null >= observed).sum())\n    p = (count + 1) / (null.size + 1)\n\n    return {\n        \"test_used\": \"permanova\", \"pseudo_f\": observed, \"p_value\": float(p),\n        \"n_permutations\": int(null.size), \"n_at_least_as_extreme\": count,\n        \"groups\": levels,\n        \"n_per_group\": {lv: int((g == lv).sum()) for lv in levels},\n        \"null_distribution\": [float(x) for x in\n                              rng.choice(null, size=min(2000, null.size), replace=False)],\n        \"effect_size\": float(observed / (observed + (n - len(levels)) / (len(levels) - 1)))\n                       if np.isfinite(observed) else float(\"nan\"),\n        \"effect_size_type\": \"pseudo_r_squared\",\n        \"caveat\": (\"PERMANOVA is sensitive to differences in SPREAD as well as differences in \"\n                   \"location. A significant result can mean 'the groups are in different places' \"\n                   \"or 'one group is much more variable'. Look at the ordination plot before \"\n                   \"deciding which you have.\"),\n        \"plain_language\": (\n            f\"Shuffled the group labels {null.size:,} times. The real grouping separated the \"\n            f\"communities better than {null.size - count:,} of those {null.size:,} random \"\n            f\"groupings (pseudo-F = {observed:.3f}, p = {p:.4g}). \"\n            + (\"The communities really do differ between groups.\"\n               if p < 0.05 else\n               \"Chance rearrangements do about as well, so these communities are not \"\n               \"distinguishable by this grouping.\")),\n    }\n\n\n@bound(\"compare_composition\", data_args=(\"samples\",))\ndef compare_composition(samples: Dict[str, Dict[str, float]], groups: Dict[str, str],\n                        metric: str = \"aitchison\", seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"The safe front door for \"are these communities different?\".\n\n    This is the function the chatbot is allowed to call. It refuses to hand\n    proportions to a t-test, runs the compositionally correct pipeline, and\n    explains the refusal -- which is the lesson the spec says the platform must\n    teach rather than document.\n    \"\"\"\n    names, taxa, M = _counts_matrix(samples)\n    labels = [groups.get(n, \"ungrouped\") for n in names]\n    if len(set(labels)) < 2:\n        return {\"refused\": True, \"reason\": \"All samples are in the same group.\"}\n\n    beta = beta_diversity.__wrapped__(samples, metric=metric)\n    if beta.get(\"refused\"):\n        return beta\n    perm = permanova.__wrapped__(beta[\"distance_matrix\"], labels, seed=seed)\n    alpha = alpha_diversity.__wrapped__(samples)\n\n    # Alpha diversity CAN be compared with ordinary tests -- it is one number\n    # per sample, not a composition. Route it through the normal engine.\n    from .inference import compare_groups as _cg\n    shannon_by_group: Dict[str, List[float]] = {}\n    for name, lab in zip(names, labels):\n        shannon_by_group.setdefault(lab, []).append(alpha[\"samples\"][name][\"shannon\"])\n    alpha_test = None\n    if all(len(v) >= 3 for v in shannon_by_group.values()):\n        alpha_test = _cg.__wrapped__(shannon_by_group,\n                                     justification=\"Shannon diversity is one value per sample, so \"\n                                                   \"an ordinary group comparison is valid on it.\")\n\n    return {\n        \"groups\": sorted(set(labels)),\n        \"n_samples\": len(names), \"n_taxa\": len(taxa),\n        \"alpha\": alpha,\n        \"alpha_comparison\": alpha_test,\n        \"beta\": beta,\n        \"permanova\": perm,\n        \"p_value\": perm.get(\"p_value\"),\n        \"why_not_a_t_test\": (\n            \"You cannot run a t-test or ANOVA on the abundances themselves. Every sample's \"\n            \"percentages are forced to add up to 100%, so the taxa are not independent: if one \"\n            \"goes up, the others must go down whether or not anything happened to them. That \"\n            \"breaks the assumption every one of those tests rests on, and it produces confident \"\n            \"wrong answers rather than obvious errors. Two things ARE comparable with ordinary \"\n            \"tests: a single diversity number per sample (done above), and CLR-transformed \"\n            \"values. Everything else goes through PERMANOVA.\"),\n        \"plain_language\": (\n            perm.get(\"plain_language\", \"\")\n            + (\" \" + alpha_test[\"plain_language\"].split(\".\")[0] + \" (diversity level).\"\n               if alpha_test and not alpha_test.get(\"refused\") else \"\")),\n    }\n\n\n@bound(\"rarefaction_curve\", data_args=(\"counts\",))\ndef rarefaction_curve(counts: Sequence[float], n_points: int = 20,\n                      n_iter: int = 50, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"How many kinds would you have found if you had counted fewer?\n\n    The curve that answers \"did we look hard enough?\". If it is still climbing\n    at your actual sample size, you did not.\n    \"\"\"\n    c = np.asarray(counts, dtype=float).ravel()\n    c = c[c > 0]\n    total = int(c.sum())\n    if total < 5:\n        return {\"refused\": True, \"reason\": \"Too few individuals counted.\"}\n    pool = np.repeat(np.arange(c.size), c.astype(int))\n    rng = np.random.default_rng(seed)\n    depths = np.unique(np.linspace(1, total, int(n_points)).astype(int))\n    means, los, his = [], [], []\n    for d in depths:\n        richness = [np.unique(rng.choice(pool, int(d), replace=False)).size for _ in range(n_iter)]\n        means.append(float(np.mean(richness)))\n        los.append(float(np.percentile(richness, 2.5)))\n        his.append(float(np.percentile(richness, 97.5)))\n    # Is the curve still climbing? Compare the last decile's slope to the first.\n    slope_end = (means[-1] - means[-max(2, len(means) // 5)]) / max(1, depths[-1] - depths[-max(2, len(depths) // 5)])\n    slope_start = (means[1] - means[0]) / max(1, depths[1] - depths[0]) if len(means) > 1 else 0.0\n    saturated = bool(slope_end < 0.1 * max(slope_start, 1e-12))\n\n    return {\n        \"depths\": depths.tolist(), \"mean_richness\": means,\n        \"ci_low\": los, \"ci_high\": his,\n        \"observed_richness\": int(c.size), \"total_counted\": total,\n        \"saturated\": saturated,\n        \"end_slope\": float(slope_end),\n        \"plain_language\": (\n            f\"You counted {total} individuals and found {c.size} kinds. \"\n            + (\"The curve has flattened out, so counting more would find few new kinds -- you \"\n               \"looked hard enough.\"\n               if saturated else\n               f\"The curve is still rising at {slope_end:.3f} new kinds per individual counted, so \"\n               f\"there are more kinds there that you did not see. Any comparison of richness with \"\n               f\"another sample has to account for that.\")),\n        \"p_value\": None,\n    }\n",
  "phagequest_engine/effects.py": "\"\"\"Effect sizes and their intervals.\n\nSpec section 04, row 2: *\"How big is the difference?\"* The curriculum's own\nlanguage -- \"which showed the most growth?\" -- asks for an effect size, not a\nsignificance test. So every comparison in this engine returns one, always,\nwith an interval, and the frontend shows the effect size first and the p-value\nsecond.\n\npingouin has the nicest API for this and is GPL-3 (spec section 09). These are\nBSD/MIT-only reimplementations over numpy/scipy so the platform core carries no\ncopyleft obligation.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nfrom scipy import stats\n\n__all__ = [\n    \"cohens_d\",\n    \"hedges_g\",\n    \"glass_delta\",\n    \"cles\",\n    \"rank_biserial\",\n    \"eta_squared\",\n    \"epsilon_squared\",\n    \"cramers_v\",\n    \"effsize_ci\",\n    \"interpret\",\n]\n\n\ndef _clean(x: Sequence[float]) -> np.ndarray:\n    a = np.asarray(x, dtype=float).ravel()\n    return a[np.isfinite(a)]\n\n\ndef cohens_d(a: Sequence[float], b: Sequence[float], paired: bool = False) -> float:\n    \"\"\"Standardised mean difference, pooled SD (independent) or SD of differences (paired).\"\"\"\n    x, y = _clean(a), _clean(b)\n    if paired:\n        n = min(len(x), len(y))\n        d = x[:n] - y[:n]\n        sd = d.std(ddof=1)\n        return float(d.mean() / sd) if sd > 0 else 0.0\n    n1, n2 = len(x), len(y)\n    s_pool = np.sqrt(((n1 - 1) * x.var(ddof=1) + (n2 - 1) * y.var(ddof=1)) / (n1 + n2 - 2))\n    return float((x.mean() - y.mean()) / s_pool) if s_pool > 0 else 0.0\n\n\ndef hedges_g(a: Sequence[float], b: Sequence[float], paired: bool = False) -> float:\n    \"\"\"Cohen's d with the small-sample bias correction.\n\n    Class datasets are n=4 to n=30 (spec section 04, row 4). At n=10 per group\n    the correction is about 4%, which is not nothing when the whole point is\n    honesty about small samples. Hedges' g is the default the platform reports.\n    \"\"\"\n    d = cohens_d(a, b, paired=paired)\n    n1, n2 = len(_clean(a)), len(_clean(b))\n    df = (n1 - 1) if paired else (n1 + n2 - 2)\n    if df <= 1:\n        return d\n    J = 1.0 - (3.0 / (4.0 * df - 1.0))\n    return float(d * J)\n\n\ndef glass_delta(treatment: Sequence[float], control: Sequence[float]) -> float:\n    \"\"\"Standardised by the control SD only -- right when the treatment changes spread.\"\"\"\n    t, c = _clean(treatment), _clean(control)\n    sd = c.std(ddof=1)\n    return float((t.mean() - c.mean()) / sd) if sd > 0 else 0.0\n\n\ndef cles(a: Sequence[float], b: Sequence[float]) -> float:\n    \"\"\"Common-language effect size: P(a random value from A > a random value from B).\n\n    This is the effect size a Grade 7 student can actually read: \"68 times out\n    of 100, a tube from the salty group beat a tube from the fresh group.\"\n    \"\"\"\n    x, y = _clean(a), _clean(b)\n    if len(x) == 0 or len(y) == 0:\n        return float(\"nan\")\n    diff = x[:, None] - y[None, :]\n    return float((np.sum(diff > 0) + 0.5 * np.sum(diff == 0)) / diff.size)\n\n\ndef rank_biserial(a: Sequence[float], b: Sequence[float]) -> float:\n    \"\"\"Effect size companion to Mann-Whitney U. Ranges -1..1, 0 = no difference.\"\"\"\n    return float(2.0 * cles(a, b) - 1.0)\n\n\ndef eta_squared(groups: Sequence[Sequence[float]]) -> float:\n    \"\"\"Proportion of total variance explained by group membership (one-way).\"\"\"\n    gs = [_clean(g) for g in groups]\n    allv = np.concatenate(gs)\n    if allv.size == 0:\n        return float(\"nan\")\n    grand = allv.mean()\n    ss_between = sum(len(g) * (g.mean() - grand) ** 2 for g in gs if len(g))\n    ss_total = float(((allv - grand) ** 2).sum())\n    return float(ss_between / ss_total) if ss_total > 0 else 0.0\n\n\ndef epsilon_squared(groups: Sequence[Sequence[float]]) -> float:\n    \"\"\"Rank-based analogue of eta-squared, the companion to Kruskal-Wallis.\"\"\"\n    gs = [_clean(g) for g in groups]\n    n = sum(len(g) for g in gs)\n    k = len(gs)\n    if n <= k:\n        return float(\"nan\")\n    H = stats.kruskal(*gs).statistic if all(len(g) > 0 for g in gs) else float(\"nan\")\n    return float((H - k + 1) / (n - k))\n\n\ndef cramers_v(table: np.ndarray) -> float:\n    \"\"\"Effect size for a contingency table, with the Bergsma bias correction.\"\"\"\n    t = np.asarray(table, dtype=float)\n    chi2 = stats.chi2_contingency(t, correction=False).statistic\n    n = t.sum()\n    if n <= 0:\n        return float(\"nan\")\n    phi2 = chi2 / n\n    r, c = t.shape\n    phi2c = max(0.0, phi2 - (r - 1) * (c - 1) / (n - 1))\n    rc = r - (r - 1) ** 2 / (n - 1)\n    cc = c - (c - 1) ** 2 / (n - 1)\n    denom = min(rc - 1, cc - 1)\n    return float(np.sqrt(phi2c / denom)) if denom > 0 else 0.0\n\n\ndef effsize_ci(\n    a: Sequence[float],\n    b: Sequence[float],\n    kind: str = \"hedges_g\",\n    confidence: float = 0.95,\n    n_boot: int = 4999,\n    seed: int = 20260901,\n) -> Tuple[float, float]:\n    \"\"\"Bootstrap percentile interval around an effect size.\n\n    Analytic intervals for d rely on a noncentral t that is wrong for the\n    non-normal, tiny samples this platform actually sees. Bootstrapping is both\n    more defensible here and more teachable (spec section 04, row 4).\n    \"\"\"\n    x, y = _clean(a), _clean(b)\n    if len(x) < 2 or len(y) < 2:\n        return (float(\"nan\"), float(\"nan\"))\n    rng = np.random.default_rng(seed)\n    fn = {\n        \"hedges_g\": lambda p, q: hedges_g(p, q),\n        \"cohens_d\": lambda p, q: cohens_d(p, q),\n        \"cles\": cles,\n        \"rank_biserial\": rank_biserial,\n    }[kind]\n    boots = np.empty(n_boot)\n    for i in range(n_boot):\n        boots[i] = fn(rng.choice(x, len(x), replace=True), rng.choice(y, len(y), replace=True))\n    boots = boots[np.isfinite(boots)]\n    if boots.size == 0:\n        return (float(\"nan\"), float(\"nan\"))\n    lo = (1 - confidence) / 2 * 100\n    return (float(np.percentile(boots, lo)), float(np.percentile(boots, 100 - lo)))\n\n\n# Deliberately conservative wording. The platform never says \"large effect\" to a\n# student without also showing the interval, because a huge point estimate with\n# an interval spanning zero is the single most common way a class dataset lies.\n_BANDS = {\n    \"hedges_g\": [(0.2, \"negligible\"), (0.5, \"small\"), (0.8, \"moderate\"), (np.inf, \"large\")],\n    \"cohens_d\": [(0.2, \"negligible\"), (0.5, \"small\"), (0.8, \"moderate\"), (np.inf, \"large\")],\n    \"eta_squared\": [(0.01, \"negligible\"), (0.06, \"small\"), (0.14, \"moderate\"), (np.inf, \"large\")],\n    \"epsilon_squared\": [(0.01, \"negligible\"), (0.08, \"small\"), (0.26, \"moderate\"), (np.inf, \"large\")],\n    \"cramers_v\": [(0.1, \"negligible\"), (0.3, \"small\"), (0.5, \"moderate\"), (np.inf, \"large\")],\n    \"rank_biserial\": [(0.1, \"negligible\"), (0.3, \"small\"), (0.5, \"moderate\"), (np.inf, \"large\")],\n}\n\n\ndef interpret(value: float, kind: str = \"hedges_g\", ci: Optional[Tuple[float, float]] = None) -> str:\n    if not np.isfinite(value):\n        return \"not estimable\"\n    bands = _BANDS.get(kind, _BANDS[\"hedges_g\"])\n    label = \"large\"\n    for cut, name in bands:\n        if abs(value) < cut:\n            label = name\n            break\n    if ci is not None and np.isfinite(ci[0]) and np.isfinite(ci[1]) and ci[0] * ci[1] <= 0:\n        return f\"{label} in this sample, but the interval includes zero -- the direction is not settled\"\n    return label\n",
  "phagequest_engine/geometry.py": "\"\"\"The geometry module (spec section 11) -- what makes this ours.\n\nReproduces the Deepam Saha / Dr. Ashani Dasgupta phage-geometry pipeline:\n\n    genome -> 256-D tetranucleotide-frequency vector -> cosine distance ->\n    k-nearest-neighbour graph -> connected components swept over k ->\n    Ollivier-Ricci curvature -> the negatively curved bridge edges\n\nand exposes it as the three teaching modules the spec names: Fingerprint (7-9),\nIslands (9-11), Bridges (11-12).\n\nTwo deliberate implementation decisions:\n\n1.  **No GraphRicciCurvature dependency.** The spec flags its trap directly:\n    v0.6.1 pins `scipy<=1.13.1`, which collides with a current scientific\n    stack, and pulls in `networkit`, a C++ build that is the real installation\n    cost. Ollivier-Ricci curvature is an optimal-transport problem on a\n    neighbourhood of at most k+1 points, which `scipy.optimize.linprog` solves\n    exactly in milliseconds. Implementing it here removes the dependency, the\n    version pin and the C++ build, and -- more importantly -- puts the\n    definition in front of a Grade 12 student as forty readable lines instead\n    of an opaque call.\n\n2.  **There is no \"tetranucleotide frequency package\".** The spec lists that as\n    a classic hallucination site. It is a `Counter` over a sliding window.\n\nThe weighted-versus-unweighted caveat from the spec is not a footnote here. It\nis computed, returned, and surfaced by default, because it is the single best\ndemonstration the platform has of why the transcript is the product.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport itertools\nfrom collections import Counter\nfrom typing import Any, Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nfrom scipy import optimize, sparse\nfrom scipy.sparse.csgraph import connected_components, dijkstra\nfrom scipy.stats import mannwhitneyu\n\nfrom .transcript import bound\n\n__all__ = [\n    \"tetranucleotide_vector\", \"tnf_matrix\", \"cosine_distance_matrix\",\n    \"knn_graph\", \"component_sweep\", \"ollivier_ricci\", \"bridge_analysis\",\n    \"KMERS\",\n]\n\n_BASES = \"ACGT\"\nKMERS: List[str] = [\"\".join(p) for p in itertools.product(_BASES, repeat=4)]\n_KMER_INDEX = {k: i for i, k in enumerate(KMERS)}\n\n\n# --------------------------------------------------------------------------\n# Module 1: Fingerprint (Grades 7-9)\n# --------------------------------------------------------------------------\n\n@bound(\"tetranucleotide_vector\", data_args=(\"sequence\",))\ndef tetranucleotide_vector(sequence: str, name: str = \"sequence\",\n                           canonical: bool = False) -> Dict[str, Any]:\n    \"\"\"The 256-dimensional fingerprint of a genome.\n\n    G5-L11 teaches pattern-matching against a reference set and calls it\n    bioinformatics: seven coloured circles, compared position by position. This\n    is the same instinct applied to 256 real numbers. There is no package for\n    it and there does not need to be -- it is a Counter over a sliding window.\n\n    `canonical` merges each 4-mer with its reverse complement, which is the\n    right choice when the sequencing strand is arbitrary. Off by default,\n    because the original analysis being reproduced did not use it.\n    \"\"\"\n    seq = \"\".join(c for c in str(sequence).upper() if c in _BASES)\n    if len(seq) < 4:\n        return {\"refused\": True, \"reason\": \"Sequence has fewer than 4 usable bases.\"}\n\n    counts = Counter(seq[i:i + 4] for i in range(len(seq) - 3))\n    vec = np.zeros(256, dtype=float)\n    for kmer, n in counts.items():\n        idx = _KMER_INDEX.get(kmer)\n        if idx is not None:\n            vec[idx] = n\n\n    if canonical:\n        comp = str.maketrans(\"ACGT\", \"TGCA\")\n        merged = np.zeros(256)\n        for i, kmer in enumerate(KMERS):\n            rc = kmer.translate(comp)[::-1]\n            j = _KMER_INDEX[rc]\n            merged[min(i, j)] += vec[i]\n        vec = merged\n\n    total = vec.sum()\n    freq = vec / total if total > 0 else vec\n\n    top = sorted(zip(KMERS, freq), key=lambda kv: -kv[1])[:8]\n    gc = float(sum(seq.count(b) for b in \"GC\") / len(seq))\n\n    return {\n        \"name\": name, \"length\": len(seq), \"gc_content\": gc,\n        \"n_windows\": int(total),\n        \"counts\": [int(x) for x in vec],\n        \"frequencies\": [float(x) for x in freq],\n        \"kmers\": KMERS,\n        \"canonical\": bool(canonical),\n        \"top_kmers\": [{\"kmer\": k, \"frequency\": float(f)} for k, f in top],\n        \"expected_uniform\": 1 / 256,\n        \"most_enriched\": {\"kmer\": top[0][0],\n                          \"fold_over_uniform\": float(top[0][1] * 256)} if top else None,\n        \"teaches\": (\n            \"Every genome has a 4-letter-word habit. If all 256 words were equally likely each \"\n            \"would appear 0.39% of the time; they do not, and how they differ is a fingerprint \"\n            \"specific enough to tell two phage apart without aligning a single base.\"),\n        \"plain_language\": (\n            f\"{name} is {len(seq):,} bases long, {gc:.1%} G+C. Its commonest 4-letter word is \"\n            f\"{top[0][0]} at {top[0][1]:.2%} -- {top[0][1] * 256:.1f} times what you would get by \"\n            f\"chance. Those 256 numbers are this genome's fingerprint.\"),\n        \"p_value\": None,\n    }\n\n\ndef tnf_matrix(sequences: Dict[str, str], canonical: bool = False) -> Tuple[List[str], np.ndarray]:\n    \"\"\"Stack fingerprints into an (n_genomes x 256) matrix. Plain helper, no transcript.\"\"\"\n    names, rows = [], []\n    for name, seq in sequences.items():\n        r = tetranucleotide_vector.__wrapped__(seq, name=name, canonical=canonical)\n        if r.get(\"refused\"):\n            continue\n        names.append(name)\n        rows.append(r[\"frequencies\"])\n    return names, np.asarray(rows, dtype=float)\n\n\n@bound(\"cosine_distance_matrix\", data_args=(\"vectors\",))\ndef cosine_distance_matrix(vectors: Sequence[Sequence[float]],\n                           names: Optional[List[str]] = None) -> Dict[str, Any]:\n    \"\"\"Cosine distance between fingerprints -- the matrix the whole analysis rests on.\n\n    The spec's own verification note applies here: the file shipped as\n    `Phage_Adjacency_Matrix.csv` is this -- a dense *distance* matrix, not an\n    adjacency matrix. This function reproduces it to `atol=1e-9`.\n    \"\"\"\n    X = np.asarray(vectors, dtype=float)\n    if X.ndim != 2 or X.shape[0] < 2:\n        return {\"refused\": True, \"reason\": \"Need at least two vectors.\"}\n    norms = np.linalg.norm(X, axis=1, keepdims=True)\n    norms[norms == 0] = 1.0\n    U = X / norms\n    sim = np.clip(U @ U.T, -1.0, 1.0)\n    D = 1.0 - sim\n    np.fill_diagonal(D, 0.0)\n    D = np.maximum(D, 0.0)\n\n    off = D[~np.eye(D.shape[0], dtype=bool)]\n    return {\n        \"n\": int(X.shape[0]), \"names\": names,\n        \"matrix\": D.tolist(),\n        \"metric\": \"cosine distance (1 - cosine similarity)\",\n        \"scale\": {\"min\": float(off.min()), \"max\": float(off.max()),\n                  \"median\": float(np.median(off)), \"mean\": float(off.mean())},\n        \"note\": (\"These distances are tiny -- order 1e-3 is normal for tetranucleotide vectors, \"\n                 \"because every genome uses all 256 words and they differ only in proportion. \"\n                 \"Their SMALLNESS is exactly why using them as edge weights in a curvature \"\n                 \"calculation gives a different story from using the graph unweighted. See \"\n                 \"`ollivier_ricci`.\"),\n        \"p_value\": None,\n    }\n\n\n# --------------------------------------------------------------------------\n# Module 2: Islands (Grades 9-11) -- the k sweep and the plateau\n# --------------------------------------------------------------------------\n\ndef _knn_adjacency(D: np.ndarray, k: int, mutual: bool = False) -> sparse.csr_matrix:\n    n = D.shape[0]\n    k = int(min(max(1, k), n - 1))\n    order = np.argsort(D, axis=1)\n    rows, cols, vals = [], [], []\n    for i in range(n):\n        for j in order[i, 1:k + 1]:\n            rows.append(i); cols.append(int(j)); vals.append(float(D[i, j]))\n    A = sparse.csr_matrix((vals, (rows, cols)), shape=(n, n))\n    if mutual:\n        mask = A.multiply(A.T > 0)\n        return sparse.csr_matrix(mask)\n    # Symmetrise by union: i-j is an edge if either lists the other.\n    A = A.maximum(A.T)\n    return sparse.csr_matrix(A)\n\n\n@bound(\"knn_graph\", data_args=(\"distance_matrix\",))\ndef knn_graph(distance_matrix: Sequence[Sequence[float]], k: int = 20,\n              names: Optional[List[str]] = None, mutual: bool = False) -> Dict[str, Any]:\n    \"\"\"Build the k-nearest-neighbour graph at one value of k.\"\"\"\n    D = np.asarray(distance_matrix, dtype=float)\n    if D.ndim != 2 or D.shape[0] != D.shape[1] or D.shape[0] < 3:\n        return {\"refused\": True, \"reason\": \"Need a square distance matrix with at least 3 points.\"}\n    A = _knn_adjacency(D, k, mutual)\n    n_comp, labels = connected_components(A, directed=False)\n    sizes = np.bincount(labels).tolist()\n    coo = sparse.triu(A, k=1).tocoo()\n    edges = [{\"source\": int(i), \"target\": int(j), \"distance\": float(w)}\n             for i, j, w in zip(coo.row, coo.col, coo.data)]\n    return {\n        \"k\": int(k), \"n_nodes\": int(D.shape[0]), \"n_edges\": len(edges),\n        \"mutual\": bool(mutual),\n        \"edges\": edges,\n        \"component_labels\": labels.tolist(),\n        \"n_components\": int(n_comp),\n        \"component_sizes\": sorted(sizes, reverse=True),\n        \"names\": names,\n        \"components_named\": (\n            [sorted([names[i] for i in range(len(labels)) if labels[i] == c])\n             for c in range(n_comp)] if names else None),\n        \"plain_language\": (\n            f\"At k = {k}, every genome is joined to its {k} closest relatives. That makes \"\n            f\"{len(edges)} connections and leaves {n_comp} separate \"\n            f\"{'island' if n_comp == 1 else 'islands'} of sizes {sorted(sizes, reverse=True)}.\"),\n        \"p_value\": None,\n    }\n\n\n@bound(\"component_sweep\", data_args=(\"distance_matrix\",))\ndef component_sweep(distance_matrix: Sequence[Sequence[float]],\n                    k_min: int = 3, k_max: int = 40,\n                    names: Optional[List[str]] = None,\n                    mutual: bool = False) -> Dict[str, Any]:\n    \"\"\"Sweep k and find the stability plateau. This IS the Islands lesson.\n\n        \"The lesson is the plateau: a result that survives seventeen parameter\n        values is a result; a result that appears at one value is an artefact\n        of the setting.\"\n\n    Returns the component count at every k, the longest run of identical\n    partitions, and -- when the plateau splits the data in two -- the named\n    membership of each clade, so it can be checked against a reference list.\n    \"\"\"\n    D = np.asarray(distance_matrix, dtype=float)\n    n = D.shape[0]\n    if D.ndim != 2 or D.shape[0] != D.shape[1] or n < 4:\n        return {\"refused\": True, \"reason\": \"Need a square distance matrix with at least 4 points.\"}\n\n    k_max = int(min(k_max, n - 1))\n    ks = list(range(int(max(1, k_min)), k_max + 1))\n    rows, partitions = [], []\n    for k in ks:\n        A = _knn_adjacency(D, k, mutual)\n        nc, labels = connected_components(A, directed=False)\n        sizes = sorted(np.bincount(labels).tolist(), reverse=True)\n        # Canonical partition signature, independent of label numbering.\n        sig = tuple(sorted(tuple(sorted(np.nonzero(labels == c)[0].tolist()))\n                           for c in range(nc)))\n        rows.append({\"k\": k, \"n_components\": int(nc), \"sizes\": sizes,\n                     \"n_edges\": int(sparse.triu(A, k=1).nnz)})\n        partitions.append(sig)\n\n    # Longest run of an identical partition.\n    best_len, best_start, best_sig = 0, 0, None\n    i = 0\n    while i < len(partitions):\n        j = i\n        while j + 1 < len(partitions) and partitions[j + 1] == partitions[i]:\n            j += 1\n        if (j - i + 1) > best_len and len(partitions[i]) > 1:\n            best_len, best_start, best_sig = j - i + 1, i, partitions[i]\n        i = j + 1\n\n    plateau = None\n    if best_sig is not None and best_len >= 2:\n        members = [list(c) for c in best_sig]\n        plateau = {\n            \"k_from\": ks[best_start], \"k_to\": ks[best_start + best_len - 1],\n            \"length\": best_len,\n            \"n_components\": len(best_sig),\n            \"sizes\": sorted((len(c) for c in best_sig), reverse=True),\n            \"members\": members,\n            \"members_named\": ([sorted(names[i] for i in c) for c in members] if names else None),\n        }\n\n    merged_at = next((r[\"k\"] for r in rows if r[\"n_components\"] == 1), None)\n\n    if plateau is None:\n        verdict = (\"No partition survived more than one value of k. Whatever structure you see at \"\n                   \"any single k is a property of the setting, not of the genomes. That is a real \"\n                   \"and important negative result.\")\n        sev = \"warn\"\n    elif best_len >= 5:\n        verdict = (f\"The same split into {plateau['n_components']} groups of sizes \"\n                   f\"{plateau['sizes']} holds unchanged across {best_len} consecutive values of k \"\n                   f\"(k = {plateau['k_from']} to {plateau['k_to']}). A structure that survives \"\n                   f\"{best_len} different settings of the one arbitrary parameter is a property of \"\n                   f\"the data, not of the parameter.\")\n        sev = \"info\"\n    else:\n        verdict = (f\"The longest-surviving split lasts only {best_len} values of k \"\n                   f\"({plateau['k_from']}-{plateau['k_to']}). That is weak. Treat it as a \"\n                   f\"hypothesis, not a finding.\")\n        sev = \"warn\"\n\n    return {\n        \"k_values\": ks, \"rows\": rows,\n        \"component_counts\": [r[\"n_components\"] for r in rows],\n        \"plateau\": plateau,\n        \"merges_at_k\": merged_at,\n        \"n_nodes\": int(n), \"names\": names,\n        \"severity\": sev,\n        \"teaches\": (\n            \"k is a knob you chose, not something the genomes told you. So the honest question is \"\n            \"never 'what does the graph look like at k = 20?' but 'what survives every k?'\"),\n        \"plain_language\": verdict,\n        \"p_value\": None,\n    }\n\n\n# --------------------------------------------------------------------------\n# Module 3: Bridges (Grades 11-12) -- Ollivier-Ricci curvature\n# --------------------------------------------------------------------------\n\ndef _neighbour_measure(A: sparse.csr_matrix, node: int, alpha: float,\n                       weighted: bool) -> Tuple[np.ndarray, np.ndarray]:\n    \"\"\"The probability measure m_x: `alpha` stays put, the rest spreads to neighbours.\"\"\"\n    start, end = A.indptr[node], A.indptr[node + 1]\n    nbrs = A.indices[start:end]\n    if nbrs.size == 0:\n        return np.array([node]), np.array([1.0])\n    if weighted:\n        # Nearer neighbours receive more mass. Inverse-distance, which is the\n        # convention GraphRicciCurvature uses for its weighted variant.\n        w = 1.0 / np.maximum(A.data[start:end], 1e-12)\n    else:\n        w = np.ones(nbrs.size)\n    w = w / w.sum() * (1.0 - alpha)\n    return np.concatenate([[node], nbrs]), np.concatenate([[alpha], w])\n\n\ndef _w1_exact(supp_x, mass_x, supp_y, mass_y, ground: np.ndarray) -> float:\n    \"\"\"Exact 1-Wasserstein distance by linear programming.\n\n    This is the whole of Ollivier-Ricci curvature's machinery. The transport\n    problem over two neighbourhoods of at most k+1 points is a small LP that\n    HiGHS solves in well under a millisecond, which is why no C++ dependency is\n    needed for any graph a school will build.\n    \"\"\"\n    nx_, ny_ = len(supp_x), len(supp_y)\n    C = ground[np.ix_(supp_x, supp_y)].ravel()\n    # Equality constraints: each source ships its mass, each sink receives its mass.\n    rows, cols, vals = [], [], []\n    for i in range(nx_):\n        for j in range(ny_):\n            rows.append(i); cols.append(i * ny_ + j); vals.append(1.0)\n    for j in range(ny_):\n        for i in range(nx_):\n            rows.append(nx_ + j); cols.append(i * ny_ + j); vals.append(1.0)\n    A_eq = sparse.csr_matrix((vals, (rows, cols)), shape=(nx_ + ny_, nx_ * ny_))\n    b_eq = np.concatenate([mass_x, mass_y])\n    res = optimize.linprog(C, A_eq=A_eq, b_eq=b_eq, bounds=(0, None), method=\"highs\")\n    if not res.success:\n        return float(\"nan\")\n    return float(res.fun)\n\n\ndef _w1_sinkhorn(supp_x, mass_x, supp_y, mass_y, ground: np.ndarray,\n                 reg: float = 0.05, iters: int = 300) -> float:\n    \"\"\"Entropic (Sinkhorn) approximation to W1 -- pure numpy, no LP solve.\n\n    Used when a sweep would otherwise need thousands of LPs in a browser tab.\n    It is an APPROXIMATION and the result says so: entropic regularisation\n    biases W1 upward, which biases curvature downward, so a curvature computed\n    this way is a slight underestimate. The platform never silently swaps one\n    for the other -- `method` is recorded in the transcript.\n    \"\"\"\n    C = ground[np.ix_(supp_x, supp_y)]\n    scale = C.max() if C.max() > 0 else 1.0\n    K = np.exp(-C / (reg * scale))\n    u = np.ones(len(supp_x))\n    a, b = np.asarray(mass_x), np.asarray(mass_y)\n    for _ in range(iters):\n        v = b / np.maximum(K.T @ u, 1e-300)\n        u_new = a / np.maximum(K @ v, 1e-300)\n        if np.allclose(u_new, u, rtol=1e-9, atol=1e-12):\n            u = u_new\n            break\n        u = u_new\n    P = u[:, None] * K * v[None, :]\n    return float((P * C).sum())\n\n\n@bound(\"ollivier_ricci\", data_args=(\"distance_matrix\",))\ndef ollivier_ricci(distance_matrix: Sequence[Sequence[float]], k: int = 20,\n                   alpha: float = 0.5, weighted: bool = False,\n                   names: Optional[List[str]] = None,\n                   mutual: bool = False, method: str = \"exact\",\n                   denominator: str = \"graph\") -> Dict[str, Any]:\n    \"\"\"Ollivier-Ricci curvature on every edge of the k-NN graph.\n\n    For an edge (x, y):\n\n        kappa(x, y) = 1 - W1(m_x, m_y) / d(x, y)\n\n    where m_x spreads probability over x's neighbourhood and W1 is the optimal\n    transport cost under the graph's shortest-path metric. Negative curvature\n    means the two neighbourhoods are hard to move between -- the edge is a\n    bottleneck, the only way across. Those are the mosaic recombinants.\n\n    Three knobs decide the answer, and every one of them is recorded:\n\n    * `weighted`  -- are the raw cosine distances the ground metric, or is the\n      graph treated as unweighted (every edge one hop)?\n    * `denominator` -- is d(x, y) the graph shortest-path distance (\"graph\"),\n      or the raw edge weight (\"raw\")? With a consistent weighted metric these\n      coincide and the whole calculation is scale-invariant. Mixing them is\n      NOT scale-invariant, and on distances of order 1e-3 it is what produces\n      the huge negative curvatures reported in the literature note.\n    * `method`    -- \"exact\" linear programming, or \"sinkhorn\" approximation.\n\n    `bridge_analysis` runs several of these combinations side by side, because\n    they disagree and the disagreement is a teaching object, not an\n    embarrassment.\n    \"\"\"\n    D = np.asarray(distance_matrix, dtype=float)\n    n = D.shape[0]\n    if D.ndim != 2 or D.shape[0] != D.shape[1] or n < 4:\n        return {\"refused\": True, \"reason\": \"Need a square distance matrix with at least 4 points.\"}\n    if not (0.0 <= alpha < 1.0):\n        return {\"refused\": True, \"reason\": \"alpha must be in [0, 1).\"}\n\n    A = _knn_adjacency(D, k, mutual)\n    if weighted:\n        ground = dijkstra(A, directed=False)\n    else:\n        unit = A.copy()\n        unit.data = np.ones_like(unit.data)\n        ground = dijkstra(unit, directed=False, unweighted=True)\n    ground = np.nan_to_num(ground, posinf=float(np.nanmax(ground[np.isfinite(ground)])) * 10 + 1.0)\n\n    if method not in (\"exact\", \"sinkhorn\"):\n        return {\"refused\": True, \"reason\": \"method must be 'exact' or 'sinkhorn'.\"}\n    if denominator not in (\"graph\", \"raw\"):\n        return {\"refused\": True, \"reason\": \"denominator must be 'graph' or 'raw'.\"}\n    solver = _w1_exact if method == \"exact\" else _w1_sinkhorn\n\n    coo = sparse.triu(A, k=1).tocoo()\n    edges = []\n    for i, j, w in zip(coo.row, coo.col, coo.data):\n        i, j = int(i), int(j)\n        sx, mx = _neighbour_measure(A, i, alpha, weighted)\n        sy, my = _neighbour_measure(A, j, alpha, weighted)\n        d_xy = float(w) if denominator == \"raw\" else float(ground[i, j])\n        if d_xy <= 0:\n            continue\n        w1 = solver(sx, mx, sy, my, ground)\n        kappa = 1.0 - w1 / d_xy if np.isfinite(w1) else float(\"nan\")\n        edges.append({\"source\": i, \"target\": j,\n                      \"source_name\": names[i] if names else None,\n                      \"target_name\": names[j] if names else None,\n                      \"distance\": float(w), \"graph_distance\": d_xy,\n                      \"wasserstein\": float(w1), \"curvature\": float(kappa)})\n\n    kappas = np.array([e[\"curvature\"] for e in edges], dtype=float)\n    finite = kappas[np.isfinite(kappas)]\n\n    # Node curvature: the mean over its incident edges.\n    node_k: Dict[int, List[float]] = {i: [] for i in range(n)}\n    for e in edges:\n        if np.isfinite(e[\"curvature\"]):\n            node_k[e[\"source\"]].append(e[\"curvature\"])\n            node_k[e[\"target\"]].append(e[\"curvature\"])\n    node_curv = [float(np.mean(v)) if v else float(\"nan\") for i, v in sorted(node_k.items())]\n\n    return {\n        \"k\": int(k), \"alpha\": alpha, \"weighted\": bool(weighted),\n        \"method\": method, \"denominator\": denominator,\n        \"n_edges\": len(edges), \"edges\": edges,\n        \"node_curvature\": node_curv,\n        \"names\": names,\n        \"summary\": {\n            \"mean\": float(finite.mean()) if finite.size else float(\"nan\"),\n            \"min\": float(finite.min()) if finite.size else float(\"nan\"),\n            \"max\": float(finite.max()) if finite.size else float(\"nan\"),\n            \"median\": float(np.median(finite)) if finite.size else float(\"nan\"),\n            \"fraction_negative\": float((finite < 0).mean()) if finite.size else float(\"nan\"),\n        },\n        \"solver_note\": (\"Exact optimal transport by linear programming (HiGHS). No approximation, \"\n                        \"no external curvature library, no scipy version pin.\"\n                        if method == \"exact\" else\n                        \"Entropic (Sinkhorn) approximation. Faster, and it biases W1 upward, which \"\n                        \"biases curvature slightly downward. Use 'exact' for anything reported.\"),\n        \"weighting_warning\": (\n            f\"Curvature is highly sensitive to how the graph is weighted. This run used the \"\n            f\"{'raw distances' if weighted else 'unweighted graph'} as the ground metric with the \"\n            f\"{'raw edge weight' if denominator == 'raw' else 'graph shortest-path distance'} as \"\n            f\"d(x,y). Change either and the numbers change -- sometimes by orders of magnitude, on \"\n            f\"the same data with the same algorithm. `bridge_analysis` runs the combinations side \"\n            f\"by side so you can see it rather than take our word for it.\"),\n        \"plain_language\": (\n            f\"Computed curvature on all {len(edges)} edges at k = {k}\"\n            f\"{' (distance-weighted)' if weighted else ' (unweighted)'}\"\n            f\"{', raw denominator' if denominator == 'raw' else ''}. Mean curvature \"\n            f\"{finite.mean():.3f}, ranging {finite.min():.3f} to {finite.max():.3f}; \"\n            f\"{(finite < 0).mean():.0%} of edges are negatively curved. Negative means the edge is \"\n            f\"a bottleneck -- the only route between two otherwise separate neighbourhoods.\"\n            if finite.size else \"No edges could be evaluated.\"),\n        \"p_value\": None,\n    }\n\n\n@bound(\"bridge_analysis\", data_args=(\"distance_matrix\",))\ndef bridge_analysis(distance_matrix: Sequence[Sequence[float]],\n                    clade_labels: Optional[Sequence[int]] = None,\n                    k: Optional[int] = None, alpha: float = 0.5,\n                    names: Optional[List[str]] = None,\n                    k_min: int = 3, k_max: int = 40,\n                    method: str = \"exact\") -> Dict[str, Any]:\n    \"\"\"The complete Bridges lesson, end to end.\n\n    1. Sweep k and find the plateau (the two clades).\n    2. Find the first k at which they connect, and identify those edges.\n    3. Compute curvature and test bridge edges against interior edges.\n    4. Name the hub genomes that carry most of the bridge.\n    5. Run the whole thing weighted AND unweighted, and report both.\n\n    Step 5 is not optional. The spec's honest caveat is the single best\n    demonstration the platform has of why the transcript is the product:\n    same data, same algorithm, opposite-looking story.\n    \"\"\"\n    D = np.asarray(distance_matrix, dtype=float)\n    n = D.shape[0]\n    if D.ndim != 2 or D.shape[0] != D.shape[1] or n < 6:\n        return {\"refused\": True, \"reason\": \"Need a square distance matrix with at least 6 points.\"}\n\n    sweep = component_sweep.__wrapped__(D, k_min=k_min, k_max=min(k_max, n - 1), names=names)\n    plateau = sweep.get(\"plateau\")\n\n    # Decide which clade assignment to use: the caller's, or the plateau's.\n    if clade_labels is not None:\n        labels = np.asarray(clade_labels).astype(int)\n        source = \"provided by caller\"\n    elif plateau and plateau[\"n_components\"] == 2:\n        labels = np.zeros(n, dtype=int)\n        for ci, members in enumerate(plateau[\"members\"]):\n            labels[list(members)] = ci\n        source = f\"the stability plateau (k = {plateau['k_from']}-{plateau['k_to']})\"\n    else:\n        return {\"refused\": True,\n                \"reason\": (\"No two-clade structure was found, and none was supplied. There is \"\n                           \"nothing here for a bridge analysis to bridge -- which is itself the \"\n                           \"answer: this set of genomes does not split in two.\"),\n                \"sweep\": sweep}\n\n    # The first k at which the two clades touch.\n    bridge_k = k\n    if bridge_k is None:\n        bridge_k = min(k_max, n - 1)\n        for kk in range(max(2, k_min), min(k_max, n - 1) + 1):\n            A = _knn_adjacency(D, kk)\n            coo = sparse.triu(A, k=1).tocoo()\n            if any(labels[i] != labels[j] for i, j in zip(coo.row, coo.col)):\n                bridge_k = kk\n                break\n\n    # Both weightings, always, side by side. Whether they agree is itself the\n    # finding, and it is not known in advance: it depends on how uneven the\n    # edge weights are in THIS dataset. The caveat below is written from the\n    # numbers actually computed, never asserted ahead of them.\n    VARIANTS = {\n        \"unweighted\": dict(weighted=False, denominator=\"graph\"),\n        \"weighted\": dict(weighted=True, denominator=\"graph\"),\n    }\n    results = {}\n    for vname, opts in VARIANTS.items():\n        weighted = opts[\"weighted\"]\n        curv = ollivier_ricci.__wrapped__(D, k=bridge_k, alpha=alpha, names=names,\n                                          method=method, **opts)\n        edges = curv[\"edges\"]\n        cross = [e for e in edges if labels[e[\"source\"]] != labels[e[\"target\"]]\n                 and np.isfinite(e[\"curvature\"])]\n        within = [e for e in edges if labels[e[\"source\"]] == labels[e[\"target\"]]\n                  and np.isfinite(e[\"curvature\"])]\n        kc = np.array([e[\"curvature\"] for e in cross])\n        kw = np.array([e[\"curvature\"] for e in within])\n\n        test = None\n        if kc.size >= 2 and kw.size >= 2:\n            mw = mannwhitneyu(kc, kw, alternative=\"less\")\n            test = {\"test\": \"Mann-Whitney U (cross < within)\",\n                    \"statistic\": float(mw.statistic), \"p_value\": float(mw.pvalue),\n                    \"n_cross\": int(kc.size), \"n_within\": int(kw.size)}\n\n        hubs = Counter()\n        for e in cross:\n            hubs[e[\"source\"]] += 1\n            hubs[e[\"target\"]] += 1\n        top_hubs = [{\"index\": int(i), \"name\": names[i] if names else None, \"bridge_edges\": int(c)}\n                    for i, c in hubs.most_common(5)]\n\n        results[vname] = {\n            \"weighted\": weighted, \"denominator\": opts[\"denominator\"],\n            \"n_bridge_edges\": len(cross),\n            \"n_interior_edges\": len(within),\n            \"all_bridges_negative\": bool(kc.size > 0 and np.all(kc < 0)),\n            \"mean_curvature_bridge\": float(kc.mean()) if kc.size else float(\"nan\"),\n            \"mean_curvature_interior\": float(kw.mean()) if kw.size else float(\"nan\"),\n            \"min_curvature\": float(np.min(np.concatenate([kc, kw]))) if (kc.size or kw.size) else float(\"nan\"),\n            \"overall_mean_curvature\": curv[\"summary\"][\"mean\"],\n            \"test\": test,\n            \"p_value\": test[\"p_value\"] if test else None,\n            \"bridge_edges\": cross,\n            \"hubs\": top_hubs,\n            \"transcript_id\": curv.get(\"transcript_id\"),\n        }\n\n    u = results[\"unweighted\"]\n    w = results[\"weighted\"]\n\n    # How uneven are the edge weights? This is what decides whether weighting\n    # matters at all, so compute it rather than guessing.\n    A_dbg = _knn_adjacency(D, bridge_k)\n    wts = sparse.triu(A_dbg, k=1).tocoo().data\n    wts = wts[wts > 0]\n    spread_ratio = float(wts.max() / wts.min()) if wts.size else float(\"nan\")\n\n    um, wm = u[\"overall_mean_curvature\"], w[\"overall_mean_curvature\"]\n    gap = abs(um - wm)\n    if np.isfinite(um) and np.isfinite(wm) and gap > 0.5 * max(abs(um), abs(wm), 1e-12):\n        agreement = (f\"They DISAGREE: {um:+.3f} against {wm:+.3f}, a gap of {gap:.3f}. \"\n                     f\"Do not report either without saying which one it is.\")\n    else:\n        agreement = (f\"On THIS dataset they happen to agree closely ({um:+.3f} against \"\n                     f\"{wm:+.3f}). That is a fact about these particular genomes, not a general \"\n                     f\"guarantee. The edge weights here span a factor of {spread_ratio:.0f}. On a graph with very uneven distances the weighted \"\n                     f\"curvature can run orders of magnitude more negative, because an edge that \"\n                     f\"is much shorter than the routes around it gets divided by a very small \"\n                     f\"number.\")\n\n    caveat = (\n        f\"Curvature depends on how the graph is weighted, so both runs are shown. \"\n        f\"Unweighted (every edge one hop): mean {um:+.3f}, minimum {u['min_curvature']:.3f}. \"\n        f\"Distance-weighted: mean {wm:+.3f}, minimum {w['min_curvature']:.3f}. \"\n        f\"{agreement} \"\n        f\"The edge weights in this graph range from {wts.min():.3g} to {wts.max():.3g}. \"\n        f\"A curvature quoted without its weighting, its k, its alpha and its solver is not a \"\n        f\"result -- which is exactly why this platform hands you the transcript and not just \"\n        f\"the number.\")\n\n    primary = u\n    hub_txt = \"\"\n    if primary[\"hubs\"]:\n        named = \", \".join(\n            f\"{h['name'] if h['name'] else '#' + str(h['index'])} ({h['bridge_edges']} of them)\"\n            for h in primary[\"hubs\"][:3])\n        hub_txt = (f\" The bridge is carried by a handful of genomes: {named}. Those are the ones to \"\n                   f\"look up -- geometry is pointing at which genomes to examine, and biology has \"\n                   f\"to say why.\")\n\n    return {\n        \"clade_source\": source,\n        \"clade_sizes\": sorted(np.bincount(labels).tolist(), reverse=True),\n        \"clade_members\": ([sorted(names[i] for i in np.nonzero(labels == c)[0])\n                           for c in range(labels.max() + 1)] if names else None),\n        \"bridge_k\": int(bridge_k),\n        \"sweep\": sweep,\n        \"unweighted\": u, \"weighted\": w,\n        \"variants\": list(results),\n        \"edge_weight_spread\": spread_ratio,\n        \"weighting_caveat\": caveat,\n        \"p_value\": primary[\"p_value\"],\n        \"teaches\": (\n            \"Curvature did not tell you the biology. It told you WHERE to look. The genomes on the \"\n            \"negatively curved edges are the ones holding two worlds together; going and finding \"\n            \"out why is the actual research, and it is still open.\"),\n        \"plain_language\": (\n            f\"Using the clade split from {source}, the two groups first connect at k = {bridge_k} \"\n            f\"through {u['n_bridge_edges']} edges. \"\n            + (f\"Every one of them is negatively curved. \" if u[\"all_bridges_negative\"] else\n               f\"{sum(1 for e in u['bridge_edges'] if e['curvature'] < 0)} of them are negatively \"\n               f\"curved. \")\n            + (f\"Mean curvature on the bridge is {u['mean_curvature_bridge']:.3f} against \"\n               f\"{u['mean_curvature_interior']:+.3f} inside the clades\"\n               + (f\" (Mann-Whitney, cross < within, p = {u['test']['p_value']:.3g}).\"\n                  if u[\"test\"] else \".\")\n               if np.isfinite(u[\"mean_curvature_bridge\"]) else \"\")\n            + hub_txt),\n        \"notes\": [caveat],\n    }\n",
  "phagequest_engine/guards.py": "\"\"\"The honesty machinery (spec section 06).\n\n    \"An LLM asked 'is this significant?' will happily produce a fluent,\n    correctly formatted, entirely fabricated t(28) = 2.41, p = .023, d = 0.91.\n    It will look right. It will go into a student's report. And unlike a\n    hallucinated fact, a hallucinated p-value cannot be caught by a 15-year-old\n    or, usually, by their teacher.\"\n\nSix enforcement mechanisms, all in this module, all testable:\n\n  1. numeric_scan          -- every number in model prose must trace to a transcript\n  2. PreRegistration       -- a prediction must be logged before a test runs\n  3. SpecificationSearch   -- the \"try dropping that outlier\" loop is detected\n  4. claim_guard           -- sentences the method cannot support are blocked\n  5. sample_size_guard     -- ML below a threshold is refused, not caveated\n  6. NameCollisionGuard    -- the package-name traps, as code rather than prose\n\nNote what is NOT here: asking the model to be careful. Every one of these runs\nafter the model has spoken, on its output, deterministically.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\nimport time\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Any, Dict, Iterable, List, Optional, Sequence, Set, Tuple\n\nimport numpy as np\n\nfrom .transcript import TranscriptStore, get_store\n\n__all__ = [\n    \"numeric_scan\", \"ScanResult\", \"PreRegistration\", \"PreRegistrationLog\",\n    \"SpecificationSearchDetector\", \"claim_guard\", \"sample_size_guard\",\n    \"NAME_COLLISIONS\", \"check_package_names\", \"redact_pii\",\n]\n\n\n# ==========================================================================\n# 1. Post-generation numeric scan\n# ==========================================================================\n\n# Ordered: the most specific patterns first, so \"p = .023\" is captured as a\n# statistic rather than as a bare decimal.\n_STAT_PATTERNS = [\n    (r\"\\bp\\s*[=<>]\\s*\\.?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\", \"p_value\"),\n    (r\"\\b[tFrzFHUW]\\s*\\(\\s*[\\d.,\\s]+\\)\\s*=\\s*[-+]?\\d*\\.?\\d+\", \"test_statistic\"),\n    (r\"\\b(?:chi2|chi-squared|χ²|χ\\s*2)\\s*(?:\\([^)]*\\))?\\s*=\\s*[-+]?\\d*\\.?\\d+\", \"chi_square\"),\n    (r\"\\b(?:d|g|eta2|η²|r|rho|ρ|tau|τ|V)\\s*=\\s*[-+]?\\d*\\.?\\d+\", \"effect_size\"),\n    (r\"\\b(?:CI|confidence interval)\\s*[:=]?\\s*\\[?\\s*[-+]?\\d*\\.?\\d+\\s*(?:,|to|-)\\s*[-+]?\\d*\\.?\\d+\", \"interval\"),\n    (r\"[-+]?\\d+(?:,\\d{3})*(?:\\.\\d+)?\\s*%\", \"percentage\"),\n    (r\"[-+]?\\d+(?:,\\d{3})*\\.\\d+(?:[eE][-+]?\\d+)?\", \"decimal\"),\n    (r\"\\b\\d+(?:,\\d{3})*(?:[eE][-+]?\\d+)\\b\", \"scientific\"),\n    (r\"\\b\\d{2,}(?:,\\d{3})*\\b\", \"integer\"),\n]\n\n# Numbers that are never claims about data and must not trip the scanner.\n_SAFE_CONTEXT = re.compile(\n    r\"(?:grade|class|year|step|stage|tube|plate|day|week|page|figure|table|section|\"\n    r\"question|part|version|python|scipy|numpy|k\\s*=|n\\s*=|alpha\\s*=|level|row)\\s*:?\\s*$\",\n    re.IGNORECASE)\n\n\n@dataclass\nclass ScanResult:\n    passed: bool\n    numbers_found: List[Dict[str, Any]]\n    unmatched: List[Dict[str, Any]]\n    matched: List[Dict[str, Any]]\n    redacted_text: str\n    message: str\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\ndef _parse_number(token: str) -> Optional[float]:\n    m = re.findall(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\", token.replace(\",\", \"\"))\n    if not m:\n        return None\n    try:\n        return float(m[-1])\n    except ValueError:\n        return None\n\n\ndef _all_numbers_in(token: str) -> List[float]:\n    out = []\n    for m in re.findall(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\", token.replace(\",\", \"\")):\n        try:\n            out.append(float(m))\n        except ValueError:\n            continue\n    return out\n\n\ndef numeric_scan(text: str, store: Optional[TranscriptStore] = None,\n                 allowed: Optional[Iterable[float]] = None,\n                 tolerance: float = 1e-6,\n                 ignore_below: float = 10.0,\n                 mode: str = \"block\") -> ScanResult:\n    \"\"\"Cross-check every number in model prose against the turn's tool results.\n\n    Spec section 06, point 2:\n\n        \"Parse the model's prose for numeric patterns -- p =, p <, t(, F(, chi2,\n        bare decimals, percentages -- and cross-check each against the turn's\n        tool-result store. Unmatched number -> block and regenerate.\"\n\n    `ignore_below` exempts small bare integers (\"the four salt levels\", \"three\n    replicates\") which are prose, not claims. Statistical patterns -- anything\n    matching `p =`, `t(...)`, an effect size, an interval or a percentage -- are\n    NEVER exempted regardless of magnitude, because those are exactly the\n    fabrications that matter.\n\n    `mode=\"block\"` fails the whole turn. `mode=\"redact\"` replaces unmatched\n    numbers with [UNVERIFIED] so the sentence survives and the number does not.\n    \"\"\"\n    st = store or get_store()\n    pool = list(allowed) if allowed is not None else st.numbers()\n    pool_arr = np.asarray([p for p in pool if np.isfinite(p)], dtype=float)\n\n    def known(v: float, written: str) -> bool:\n        \"\"\"Is `v` a faithful rendering of some number the engine actually produced?\n\n        The tolerance is derived from HOW THE NUMBER WAS WRITTEN, not from a\n        fixed epsilon. \"p = .023\" was written to three decimals, so it matches a\n        stored value only within 0.0005 -- the rounding it claims. An earlier\n        version of this function allowed a generous tolerance at every decimal\n        place, which made 0.023 \"match\" a stored 0.0, and a fabricated p-value\n        sailed straight through. That bug is the exact failure this whole module\n        exists to prevent, so the rule is now strict: a written number must be\n        the correct rounding of a real one.\n        \"\"\"\n        if pool_arr.size == 0:\n            return False\n\n        m = re.search(r\"(\\d*)\\.(\\d+)\", written.replace(\",\", \"\"))\n        if m:\n            dp = len(m.group(2))\n        elif re.search(r\"[eE][-+]?\\d+\", written):\n            dp = 6\n        else:\n            dp = 0\n        half = 0.5 * (10.0 ** -dp)\n\n        # A written number may be the stored value itself, or its percentage\n        # form -- a model writing \"37%\" from a stored 0.3679 is reporting, not\n        # inventing. Both are checked at the written precision.\n        for cand, scale in ((v, 1.0), (v / 100.0, 0.01)):\n            if np.any(np.abs(pool_arr - cand) <= half * scale + tolerance):\n                return True\n        return False\n\n    found: List[Dict[str, Any]] = []\n    claimed_spans: List[Tuple[int, int]] = []\n\n    for pattern, kind in _STAT_PATTERNS:\n        for m in re.finditer(pattern, text):\n            span = m.span()\n            if any(s <= span[0] < e or s < span[1] <= e for s, e in claimed_spans):\n                continue\n            claimed_spans.append(span)\n            statistical = kind not in (\"integer\", \"decimal\", \"scientific\", \"percentage\")\n            for v in _all_numbers_in(m.group()):\n                found.append({\"token\": m.group().strip(), \"kind\": kind, \"value\": v,\n                              \"start\": span[0], \"end\": span[1],\n                              \"statistical\": statistical})\n\n    matched, unmatched = [], []\n    for f in found:\n        v = f[\"value\"]\n        exempt = (not f[\"statistical\"]\n                  and f[\"kind\"] == \"integer\"\n                  and abs(v) < ignore_below)\n        if not exempt and f[\"kind\"] in (\"integer\", \"decimal\"):\n            prefix = text[max(0, f[\"start\"] - 30):f[\"start\"]]\n            if _SAFE_CONTEXT.search(prefix):\n                exempt = True\n        if exempt:\n            f[\"exempt\"] = True\n            matched.append(f)\n        elif known(v, f[\"token\"]):\n            f[\"exempt\"] = False\n            matched.append(f)\n        else:\n            f[\"exempt\"] = False\n            unmatched.append(f)\n\n    redacted = text\n    for f in sorted(unmatched, key=lambda x: -x[\"start\"]):\n        redacted = redacted[:f[\"start\"]] + \"[UNVERIFIED]\" + redacted[f[\"end\"]:]\n\n    passed = not unmatched\n    if passed:\n        msg = (f\"All {len(matched)} number(s) in this response trace to a computed result.\"\n               if matched else \"No numeric claims in this response.\")\n    else:\n        worst = [f for f in unmatched if f[\"statistical\"]]\n        # Mask the digits. Repeating a fabricated statistic back to the user --\n        # even inside a warning -- puts it on screen where it can be copied, and\n        # a number in a warning still reads as a number.\n        def _mask(tok: str) -> str:\n            return re.sub(r\"\\d\", \"#\", tok)\n\n        msg = (f\"{len(unmatched)} number(s) could not be traced to any computed result: \"\n               + \", \".join(sorted({_mask(f['token']) for f in unmatched})[:6])\n               + (\". At least one is a statistical claim, which is the highest-severity case: \"\n                  \"a fabricated p-value or effect size cannot be caught by a student or their \"\n                  \"teacher.\" if worst else \".\")\n               + (\" The response was blocked.\" if mode == \"block\" else\n                  \" The numbers were replaced with [UNVERIFIED].\"))\n\n    return ScanResult(passed=passed, numbers_found=found, unmatched=unmatched,\n                      matched=matched, redacted_text=redacted, message=msg)\n\n\n# ==========================================================================\n# 2. Pre-registration (spec section 06, point 3)\n# ==========================================================================\n\n@dataclass\nclass PreRegistration:\n    \"\"\"A prediction, recorded before the data is looked at.\n\n        \"G7-L9 and G8-L9 both make students write a prediction before observing;\n        G9-L9 makes them write a claim before evidence. The platform simply\n        records it and holds them to it. This turns the p-hacking failure mode\n        into the lesson.\"\n    \"\"\"\n    dataset_id: str\n    question: str\n    prediction: str\n    direction: str = \"two-sided\"      # greater | less | two-sided\n    primary_outcome: str = \"\"\n    groups: List[str] = field(default_factory=list)\n    planned_test: str = \"\"\n    planned_n: Optional[int] = None\n    registered_at: float = field(default_factory=time.time)\n    author: str = \"\"\n    locked: bool = True\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\nclass PreRegistrationLog:\n    \"\"\"Holds pre-registrations and judges results against them.\n\n    The judgement is deliberately gentle about being WRONG and strict about\n    changing the prediction afterwards. A wrong prediction honestly reported is\n    a good piece of science; a prediction quietly rewritten to match the data is\n    the thing the platform exists to prevent.\n    \"\"\"\n\n    def __init__(self) -> None:\n        self._by_dataset: Dict[str, List[PreRegistration]] = {}\n\n    def register(self, prereg: PreRegistration) -> Dict[str, Any]:\n        existing = self._by_dataset.setdefault(prereg.dataset_id, [])\n        amended = bool(existing)\n        existing.append(prereg)\n        return {\n            \"registered\": True, \"amendment\": amended, \"version\": len(existing),\n            \"message\": (\"Prediction recorded. It is now locked -- you can add a new one, but the \"\n                        \"original stays in the record and your teacher sees both.\"\n                        if not amended else\n                        f\"Recorded as amendment #{len(existing)}. The original prediction is still \"\n                        f\"in the record and will be shown alongside this one. Amending after \"\n                        f\"seeing data is not forbidden here, but it is always visible.\"),\n        }\n\n    def current(self, dataset_id: str) -> Optional[PreRegistration]:\n        lst = self._by_dataset.get(dataset_id)\n        return lst[0] if lst else None\n\n    def all_for(self, dataset_id: str) -> List[PreRegistration]:\n        return list(self._by_dataset.get(dataset_id, []))\n\n    def gate(self, dataset_id: str) -> Dict[str, Any]:\n        \"\"\"Must a prediction be written before a test may run? Yes, once.\n\n        The assistant is told to withhold the test and ask the probing question\n        instead (spec section 06, pedagogy note). This is that rule as code.\n        \"\"\"\n        if self.current(dataset_id) is None:\n            return {\n                \"allowed\": False,\n                \"reason\": (\"Before running a test on this data, write down what you expect to \"\n                           \"happen and why. Not because it is a formality -- because a prediction \"\n                           \"made after seeing the answer is not a prediction, and the difference \"\n                           \"between those two is most of what makes something science.\"),\n                \"needs\": [\"question\", \"prediction\", \"direction\"],\n            }\n        return {\"allowed\": True, \"prereg\": self.current(dataset_id).to_dict()}\n\n    def judge(self, dataset_id: str, result: Dict[str, Any],\n              alpha: float = 0.05) -> Dict[str, Any]:\n        pre = self.current(dataset_id)\n        if pre is None:\n            return {\"judged\": False, \"message\": \"No prediction was registered for this dataset.\"}\n        p = result.get(\"p_value\")\n        es = result.get(\"effect_size\")\n        amendments = len(self.all_for(dataset_id)) - 1\n\n        if p is None:\n            outcome = \"not a test\"\n            verdict = \"This result is descriptive, so there is nothing to judge against a prediction yet.\"\n        else:\n            significant = p < alpha\n            direction_ok = True\n            if pre.direction in (\"greater\", \"less\") and es is not None and np.isfinite(es):\n                direction_ok = (es > 0) if pre.direction == \"greater\" else (es < 0)\n            if significant and direction_ok:\n                outcome = \"supported\"\n                verdict = (\"The data went the way you predicted. Note that this is the easiest case \"\n                           \"to over-read: say how big the effect was and how wide the interval, not \"\n                           \"just that you were right.\")\n            elif significant and not direction_ok:\n                outcome = \"reversed\"\n                verdict = (\"The effect is real but it went the OPPOSITE way to your prediction. \"\n                           \"This is the most interesting result you can get. Do not rewrite the \"\n                           \"prediction -- explain the surprise.\")\n            else:\n                outcome = \"not supported\"\n                verdict = (\"Your prediction was not borne out. That is a result, and reporting it \"\n                           \"is worth more than a significant finding you went looking for. Check \"\n                           \"the power analysis: was this experiment big enough to have detected \"\n                           \"the effect you expected?\")\n\n        return {\n            \"judged\": True, \"outcome\": outcome,\n            \"prediction\": pre.prediction, \"direction\": pre.direction,\n            \"registered_at\": pre.registered_at,\n            \"n_amendments\": amendments,\n            \"amendment_warning\": (\n                f\"This prediction was amended {amendments} time(s) after registration. Both \"\n                f\"versions are in the record.\" if amendments else None),\n            \"message\": verdict,\n        }\n\n\n# ==========================================================================\n# 3. Specification-search detection (spec section 06, point 6)\n# ==========================================================================\n\n_SPEC_SEARCH_PHRASES = [\n    r\"\\btry\\s+(?:a\\s+few\\s+)?(?:different|other|another)\\b\",\n    r\"\\b(?:drop|remove|exclude|delete|ignore|leave out|take out)\\s+(?:that|the|this|those|an?)?\\s*\"\n    r\"(?:outlier|point|value|row|reading|sample|measurement|tube|replicate)\",\n    r\"\\bwhat if we\\s+(?:exclude|drop|remove|ignore|leave out)\",\n    r\"\\buntil it\\s+(?:works|is significant|becomes significant)\",\n    r\"\\b(?:without|minus)\\s+(?:the\\s+)?(?:outlier|weird|odd|bad)\\s*(?:one|point|value)?\",\n    r\"\\bregroup|\\bregroup(?:ed|ing)?\\b|\\bdifferent\\s+group(?:ing|s)\\b\",\n    r\"\\bmake it significant\\b|\\bget(?:ting)? it (?:below|under) ?\\.?0?5\\b\",\n    r\"\\bp[- ]?hack\",\n    r\"\\breport(?:ing)? uncertainty across specifications\\b\",\n    r\"\\brobustness across (?:all )?(?:model )?specifications\\b\",\n]\n_SPEC_SEARCH_RE = [re.compile(p, re.IGNORECASE) for p in _SPEC_SEARCH_PHRASES]\n\n\nclass SpecificationSearchDetector:\n    \"\"\"Detects the \"keep trying until it works\" loop, by phrasing AND by behaviour.\n\n    The spec's finding is that framing, not intent, is what slipped past frontier\n    models' guardrails:\n\n        \"under a reframing that recast specification search as 'reporting\n        uncertainty across specifications,' both bypassed their guardrails\n        entirely... The guardrails were sensitive to framing, not to intent.\"\n\n    Which is why phrase-matching alone is not enough and is not what this class\n    relies on. The behavioural signal -- repeated tests on the same dataset with\n    shrinking n -- is framing-independent, and it is the one that fires on the\n    polite version of the request.\n    \"\"\"\n\n    def __init__(self, store: Optional[TranscriptStore] = None) -> None:\n        self.store = store or get_store()\n        self._exclusion_log: List[Dict[str, Any]] = []\n\n    def check_message(self, text: str) -> Dict[str, Any]:\n        hits = [p.pattern for p in _SPEC_SEARCH_RE if p.search(text)]\n        if not hits:\n            return {\"detected\": False}\n        return {\n            \"detected\": True, \"patterns\": hits, \"signal\": \"phrasing\",\n            \"response\": (\n                \"Excluding a data point changes your answer, so the reason has to be recorded \"\n                \"before it happens -- and it has to be a reason about the MEASUREMENT, not about \"\n                \"the result. 'The tube cracked', 'the probe was not in the liquid', 'we read it a \"\n                \"day late' are all fine. 'It is making the p-value too big' is not a reason, it is \"\n                \"the thing we are trying to avoid. Which was it?\"),\n            \"requires\": [\"written_justification\"],\n        }\n\n    def check_behaviour(self, data_id: Optional[str], current_n: Optional[int] = None,\n                        threshold: int = 3) -> Dict[str, Any]:\n        \"\"\"The framing-independent signal: many tests on one dataset, n shrinking.\"\"\"\n        tests = self.store.inferential_on(data_id)\n        n = len(tests)\n        if n < threshold:\n            return {\"detected\": False, \"tests_on_this_data\": n}\n\n        ns: List[int] = []\n        for t in tests:\n            per = t.result.get(\"n_per_group\")\n            if isinstance(per, dict) and per:\n                vals = [v for v in per.values() if isinstance(v, (int, float))]\n                if vals:\n                    ns.append(int(sum(vals)))\n            elif isinstance(t.result.get(\"n\"), (int, float)):\n                ns.append(int(t.result[\"n\"]))\n        shrinking = bool(len(ns) >= 2 and ns[-1] < ns[0])\n        best_p = min((t.result.get(\"p_value\", 1.0) for t in tests), default=1.0)\n        first_p = tests[0].result.get(\"p_value\")\n\n        severity = \"warn\"\n        if shrinking and n >= threshold + 1:\n            severity = \"block\"\n        elif n >= 6:\n            severity = \"block\"\n\n        return {\n            \"detected\": True, \"signal\": \"behaviour\", \"severity\": severity,\n            \"tests_on_this_data\": n,\n            \"sample_sizes\": ns,\n            \"sample_size_shrinking\": shrinking,\n            \"first_p\": first_p, \"best_p\": best_p,\n            \"response\": (\n                f\"{n} tests have now been run on this dataset\"\n                + (f\", and the sample size has fallen from {ns[0]} to {ns[-1]} along the way\"\n                   if shrinking else \"\")\n                + f\". The best p-value found is {best_p:.4g}\"\n                + (f\", against {first_p:.4g} on the first test.\" if first_p is not None else \".\")\n                + \" Searching for the analysis that gives the answer you want is the single \"\n                  \"commonest way honest people produce false results, and it does not feel \"\n                  \"dishonest while you are doing it. The multiple-comparison ledger now applies \"\n                  \"to every result from this dataset, and the count is shown to your teacher.\"),\n        }\n\n    def log_exclusion(self, data_id: str, description: str, justification: str,\n                      author: str = \"\") -> Dict[str, Any]:\n        about_measurement = not bool(\n            re.search(r\"\\b(p[- ]?value|significan|result|outcome|too (?:big|small|high|low)|\"\n                      r\"doesn'?t work|not working|ruin|spoil)\\b\", justification, re.IGNORECASE))\n        entry = {\n            \"data_id\": data_id, \"description\": description, \"justification\": justification,\n            \"author\": author, \"at\": time.time(),\n            \"about_the_measurement\": about_measurement,\n        }\n        self._exclusion_log.append(entry)\n        return {\n            \"logged\": True, \"entry\": entry,\n            \"accepted\": about_measurement,\n            \"message\": (\"Recorded. This exclusion and its reason appear in your report and in your \"\n                        \"teacher's review queue, and the analysis will be shown both with and \"\n                        \"without the excluded point.\"\n                        if about_measurement else\n                        \"Recorded, but flagged: this reason is about the RESULT, not about the \"\n                        \"measurement. That is the definition of the practice this platform exists \"\n                        \"to make visible. The exclusion is logged, the analysis will be shown both \"\n                        \"ways, and your teacher will see this note.\"),\n        }\n\n    @property\n    def exclusions(self) -> List[Dict[str, Any]]:\n        return list(self._exclusion_log)\n\n\n# ==========================================================================\n# 4. Claim guard (spec section 03.4, \"two hard guardrails to encode\")\n# ==========================================================================\n\n_BLOCKED_CLAIMS = [\n    {\n        \"id\": \"umap_distance\",\n        \"pattern\": re.compile(\n            r\"(umap|t-?sne|pacmap)[^.]{0,120}?\\b(far|close|distan|nearer|further|apart|\"\n            r\"tightly|loosely)\\b|\\b(far|close|distan|apart)\\b[^.]{0,120}?(umap|t-?sne|pacmap)\",\n            re.IGNORECASE),\n        \"message\": (\n            \"UMAP and t-SNE distances are not distances. Those methods preserve which points are \"\n            \"neighbours, not how far apart anything is: the gap between two clusters on a UMAP \"\n            \"plot carries no information, and neither does the size of a cluster. Saying two \"\n            \"groups are 'far apart, therefore different' from such a plot asserts something the \"\n            \"method cannot support. Say which points are neighbours, or use a method whose \"\n            \"distances mean something -- PCoA on a real distance matrix does.\"),\n    },\n    {\n        \"id\": \"causation\",\n        \"pattern\": re.compile(\n            r\"\\b(?:correlat\\w+|associat\\w+|r\\s*=\\s*[-+]?\\d*\\.?\\d+)[^.]{0,100}?\\b\"\n            r\"(?:therefore|so it|which means|proves?|causes?|caused|causing)\\b\",\n            re.IGNORECASE),\n        \"message\": (\n            \"A correlation cannot establish that one thing causes the other, however strong it is. \"\n            \"What settles causation is the design: did you CHANGE the thing and hold everything \"\n            \"else the same? If you did, say so and the claim is fine. If you measured both as you \"\n            \"found them, it is not.\"),\n    },\n    {\n        \"id\": \"accepting_null\",\n        \"pattern\": re.compile(\n            # NOT [^.] -- a p-value contains a decimal point, so excluding periods\n            # meant this rule could never fire on the sentence it exists to catch.\n            r\"\\b(?:p\\s*[=>]\\s*\\.?\\d|not significant|no significant)[^!?;]{0,80}?\\b\"\n            r\"(?:proves?|shows? that there is no|means there is no|no difference exists|\"\n            r\"are (?:the same|identical|equal))\\b\",\n            re.IGNORECASE),\n        \"message\": (\n            \"A non-significant result does not show that there is no difference. It shows that \"\n            \"this experiment did not find one, which is a different statement -- and with a class-\"\n            \"sized sample it is usually the expected outcome even when a real difference exists. \"\n            \"Report the interval: 'the difference is somewhere between -2 and +5' says what you \"\n            \"actually know. If you want to claim the groups ARE the same, that needs an \"\n            \"equivalence test and a threshold you set beforehand.\"),\n    },\n    {\n        \"id\": \"cluster_reification\",\n        \"pattern\": re.compile(\n            r\"\\b(?:k-?means|cluster\\w*)[^.]{0,100}?\\b(?:proves?|confirms?|shows? that there are \"\n            r\"(?:exactly )?\\d+ (?:real )?(?:types|kinds|species|groups))\\b\", re.IGNORECASE),\n        \"message\": (\n            \"Clustering algorithms return clusters whether or not any exist -- ask k-means for \"\n            \"four groups and it will give you four, from random noise included. The number of \"\n            \"clusters is something you chose. Before claiming the groups are real, show that they \"\n            \"survive changing that choice (the k sweep in the geometry module does exactly this).\"),\n    },\n]\n\n\ndef claim_guard(text: str) -> Dict[str, Any]:\n    \"\"\"Block sentences the method cannot support, at the model layer.\n\n    Spec section 03.4: *\"Block that sentence at the model layer.\"* Not document\n    it, not warn about it in a system prompt -- block it after generation, where\n    it can be tested.\n    \"\"\"\n    hits = []\n    for rule in _BLOCKED_CLAIMS:\n        m = rule[\"pattern\"].search(text)\n        if m:\n            hits.append({\"id\": rule[\"id\"], \"matched\": m.group()[:160],\n                         \"message\": rule[\"message\"]})\n    return {\n        \"passed\": not hits, \"violations\": hits,\n        \"message\": (\"No unsupported claims detected.\"\n                    if not hits else\n                    f\"{len(hits)} claim(s) go beyond what the method can support and were blocked.\"),\n    }\n\n\n# ==========================================================================\n# 5. Sample-size guard (spec section 03.4, second guardrail)\n# ==========================================================================\n\ndef sample_size_guard(n: int, task: str = \"machine_learning\",\n                      n_features: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"Refuse machine learning on a class dataset.\n\n        \"AutoML on n=30 produces a beautiful, meaningless model. The assistant\n        must refuse or heavily caveat machine learning below a sample-size\n        threshold and steer back to descriptive and inferential statistics --\n        where the answer actually is.\"\n\n    A refusal, not a caveat, below the floor. A caveat is read as permission.\n    \"\"\"\n    floors = {\n        \"machine_learning\": 100, \"supervised\": 100, \"clustering\": 50,\n        \"dimensionality_reduction\": 30, \"umap\": 50, \"correlation\": 8,\n        \"inference\": 3, \"descriptive\": 1,\n    }\n    floor = floors.get(task, 100)\n    ratio_problem = bool(n_features and n_features >= n)\n\n    if n >= floor and not ratio_problem:\n        return {\"allowed\": True, \"n\": n, \"floor\": floor, \"task\": task,\n                \"message\": f\"n = {n} is adequate for {task.replace('_', ' ')}.\"}\n\n    if ratio_problem:\n        reason = (f\"You have {n_features} measurements per sample and only {n} samples. With more \"\n                  f\"columns than rows, a model can fit your data perfectly and predict nothing -- \"\n                  f\"there is always a line through 2 points, a plane through 3, and so on. This is \"\n                  f\"not a tuning problem; there is no fix that does not involve more samples or \"\n                  f\"fewer measurements.\")\n    else:\n        reason = (f\"n = {n} is below the floor of {floor} for {task.replace('_', ' ')}. A model \"\n                  f\"trained on this many points will report a high accuracy and mean nothing by \"\n                  f\"it: with {n} points, cross-validation is itself too noisy to tell you whether \"\n                  f\"the model is real.\")\n\n    return {\n        \"allowed\": False, \"n\": n, \"floor\": floor, \"task\": task,\n        \"n_features\": n_features,\n        \"message\": reason,\n        \"instead\": [\n            \"Describe the data: group means with intervals, and a plot.\",\n            \"Compare the groups you actually care about, with an effect size and a stability check.\",\n            \"Work out how many samples you WOULD need (the power module), and say so in your \"\n            \"report -- 'this question needs n=64 per group and we had 6' is a genuine finding \"\n            \"about your experiment.\",\n        ],\n        \"steer_to\": [\"describe\", \"compare_groups\", \"n_for_ttest\", \"bootstrap_ci\"],\n    }\n\n\n# ==========================================================================\n# 6. The name-collision guard list (spec section 06)\n# ==========================================================================\n\nNAME_COLLISIONS: Dict[str, Dict[str, str]] = {\n    \"drc\": {\"installs\": \"A Django/React comment module from 2015\",\n            \"correct\": \"No Python port exists. Use `lmfit`, or this engine's `fit_curve` with an \"\n                       \"explicit four-parameter logistic (`model='four_pl'`).\"},\n    \"jellyfish\": {\"installs\": \"A string-distance library\",\n                  \"correct\": \"The k-mer counter is `bioconda::kmer-jellyfish`.\"},\n    \"wish\": {\"installs\": \"An unrelated library\",\n             \"correct\": \"The phage host-prediction tool WIsH is source/conda only.\"},\n    \"basico\": {\"installs\": \"An unrelated 2019 package\",\n               \"correct\": \"COPASI's Python API is `copasi-basico`.\"},\n    \"graph-tool\": {\"installs\": \"A stale 2.11 placeholder\",\n                   \"correct\": \"conda/apt only, and LGPL-3 with a heavy Boost/C++ build. Skip it -- \"\n                              \"`scikit-network` is BSD.\"},\n    \"community\": {\"installs\": \"An unrelated package of that exact name\",\n                  \"correct\": \"Louvain lives in `python-louvain` (imported as `community`) -- or \"\n                             \"better, `networkx.algorithms.community.louvain_communities`.\"},\n    \"ete3\": {\"installs\": \"End-of-life\", \"correct\": \"Use `ete4`.\"},\n    \"dspy-ai\": {\"installs\": \"Legacy alias\", \"correct\": \"Use `dspy`.\"},\n    \"python-igraph\": {\"installs\": \"Legacy alias\",\n                      \"correct\": \"Use `igraph` -- though it is GPL-2; prefer `scikit-network`.\"},\n    \"tetranucleotide\": {\"installs\": \"Does not exist -- a classic hallucination site\",\n                        \"correct\": \"Compute it: `Counter` over a sliding window, or \"\n                                   \"`CountVectorizer(analyzer='char', ngram_range=(4,4))`. This \"\n                                   \"engine's `geometry.tetranucleotide_vector` does it.\"},\n    \"tnf\": {\"installs\": \"Does not exist\",\n            \"correct\": \"See `geometry.tetranucleotide_vector`.\"},\n    \"phage-dynamics\": {\"installs\": \"Does not exist\",\n                       \"correct\": \"There is no maintained general-purpose phage-dynamics package. \"\n                                  \"Use `simulation.simulate`, which is scipy's solve_ivp.\"},\n}\n\n# Licences that cannot sit in the platform core (spec section 09).\nCOPYLEFT = {\n    \"pingouin\": \"GPL-3\", \"leidenalg\": \"GPL-3\", \"amiga\": \"GPL-3\",\n    \"igraph\": \"GPL-2\", \"python-igraph\": \"GPL-2\", \"phate\": \"GPL-2\",\n    \"vegan\": \"GPL-2\", \"growthcurver\": \"GPL-2\",\n    \"giotto-tda\": \"AGPL-3\", \"phyloseq\": \"AGPL-3\", \"jamovi\": \"AGPL-3\", \"jasp\": \"AGPL-3\",\n    \"graph-tool\": \"LGPL-3\",\n}\n\n_INSTALL_RE = re.compile(\n    r\"(?:pip|pip3|uv pip|conda|mamba|micromamba)\\s+(?:install|add)\\s+((?:[-\\w.\\[\\]=<>!,]+\\s*)+)\",\n    re.IGNORECASE)\n_IMPORT_RE = re.compile(r\"^\\s*(?:import|from)\\s+([\\w.]+)\", re.MULTILINE)\n\n\ndef check_package_names(text: str) -> Dict[str, Any]:\n    \"\"\"CI-testable guard over any installation or import instruction.\n\n        \"An LLM writing installation code will get these wrong. They belong in\n        the system prompt as hard constraints and in CI as tests.\"\n\n    This is the CI test. It runs over generated code, over chatbot output, and\n    over the repository's own dependency files.\n    \"\"\"\n    collisions, licences = [], []\n    seen: Set[str] = set()\n\n    for m in _INSTALL_RE.finditer(text):\n        for tok in m.group(1).split():\n            name = re.split(r\"[=<>!\\[]\", tok)[0].strip().lower()\n            if not name or name.startswith(\"-\"):\n                continue\n            seen.add(name)\n    for m in _IMPORT_RE.finditer(text):\n        seen.add(m.group(1).split(\".\")[0].lower())\n\n    for name in sorted(seen):\n        if name in NAME_COLLISIONS:\n            collisions.append({\"package\": name, **NAME_COLLISIONS[name]})\n        if name in COPYLEFT:\n            licences.append({\n                \"package\": name, \"licence\": COPYLEFT[name],\n                \"consequence\": (\n                    \"AGPL-3: network use triggers source disclosure to your users. Fatal for a \"\n                    \"hosted commercial product.\"\n                    if COPYLEFT[name] == \"AGPL-3\" else\n                    f\"{COPYLEFT[name]}: linking it into a proprietary core is a copyleft \"\n                    f\"obligation. Run it in a separate sandboxed process behind a JSON boundary, \"\n                    f\"or substitute.\"),\n            })\n\n    return {\n        \"passed\": not collisions and not licences,\n        \"packages_seen\": sorted(seen),\n        \"collisions\": collisions,\n        \"licence_issues\": licences,\n        \"message\": (\n            \"No package-name collisions or licence problems.\"\n            if not collisions and not licences else\n            \"; \".join([f\"{c['package']} actually installs: {c['installs']}\" for c in collisions]\n                      + [f\"{l['package']} is {l['licence']}\" for l in licences])),\n    }\n\n\n# ==========================================================================\n# 7. PII redaction before any cross-border LLM call (spec section 09)\n# ==========================================================================\n\n_PII_PATTERNS = [\n    (re.compile(r\"\\b[\\w.+-]+@[\\w-]+\\.[\\w.]+\\b\"), \"[EMAIL]\"),\n    (re.compile(r\"\\b(?:\\+91[\\s-]?)?[6-9]\\d{9}\\b\"), \"[PHONE]\"),\n    (re.compile(r\"\\b\\d{4}\\s?\\d{4}\\s?\\d{4}\\b\"), \"[ID]\"),          # Aadhaar-shaped\n    (re.compile(r\"\\b\\d{1,3}\\.\\d{4,},\\s*\\d{1,3}\\.\\d{4,}\\b\"), \"[COORDS]\"),\n]\n\n\ndef redact_pii(text: str, student_names: Optional[Sequence[str]] = None) -> Dict[str, Any]:\n    \"\"\"Strip identifiers before a prompt leaves the country.\n\n        \"Student prompts to a third-party model API is a cross-border transfer\n        of children's personal data to a sub-processor. Needs zero-retention\n        terms, a DPA, PII redaction before the call...\"\n\n    This is the redaction half. Precise GPS coordinates are included because a\n    sampling site (G8-L10, G9-L11) recorded to five decimal places locates a\n    child's school or home to within a metre.\n    \"\"\"\n    out = text\n    found: List[str] = []\n    for pattern, tag in _PII_PATTERNS:\n        if pattern.search(out):\n            found.append(tag)\n            out = pattern.sub(tag, out)\n    for name in (student_names or []):\n        if name and len(name) > 2:\n            pat = re.compile(rf\"\\b{re.escape(name)}\\b\", re.IGNORECASE)\n            if pat.search(out):\n                found.append(\"[NAME]\")\n                out = pat.sub(\"[STUDENT]\", out)\n    return {\n        \"text\": out, \"redacted\": sorted(set(found)), \"changed\": bool(found),\n        \"note\": (\"Site coordinates are truncated as well as names: a sampling point recorded to \"\n                 \"five decimal places locates a child to within a metre, and under DPDP Section 9 \"\n                 \"that is exactly the kind of data that must not leave the platform.\"),\n    }\n",
  "phagequest_engine/inference.py": "\"\"\"The statistical core (spec section 04).\n\nOrganised by the question a student asks, not by what a textbook contains.\n\nDesign rules encoded here rather than documented:\n\n  * The test is *chosen by the assumption checks*, and the reason is reported.\n  * An effect size with an interval is always returned; it is never optional.\n  * A stability check runs automatically on every inferential result.\n  * The multiple-comparison ledger is consulted and returned with the result.\n  * Below `min_n` per group the engine refuses to infer and describes instead.\n  * Permutation is the default route for tiny samples, because shuffling is\n    both more defensible and more teachable than a t-distribution (Grade 7).\n\nBSD/MIT only: scipy + numpy. No pingouin (GPL-3, spec section 09).\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nfrom scipy import stats\n\nfrom . import effects\nfrom .assumptions import assumption_panel, check_cell_counts\nfrom .ledger import ledger_for\nfrom .stability import stability_check\nfrom .transcript import bound, data_fingerprint\n\n__all__ = [\"compare_groups\", \"correlate\", \"contingency\", \"trend_test\", \"describe\", \"one_sample\"]\n\nALPHA = 0.05\nMIN_N = 3\n\n\ndef _prep(groups: Dict[str, Sequence[float]]) -> Tuple[List[str], List[np.ndarray]]:\n    labels, arrs = [], []\n    for k, v in groups.items():\n        a = np.asarray(v, dtype=float).ravel()\n        a = a[np.isfinite(a)]\n        labels.append(str(k))\n        arrs.append(a)\n    return labels, arrs\n\n\ndef _describe_one(a: np.ndarray) -> Dict[str, float]:\n    if a.size == 0:\n        return {\"n\": 0}\n    return {\n        \"n\": int(a.size),\n        \"mean\": float(a.mean()),\n        \"sd\": float(a.std(ddof=1)) if a.size > 1 else 0.0,\n        \"se\": float(a.std(ddof=1) / np.sqrt(a.size)) if a.size > 1 else 0.0,\n        \"median\": float(np.median(a)),\n        \"q1\": float(np.percentile(a, 25)),\n        \"q3\": float(np.percentile(a, 75)),\n        \"min\": float(a.min()),\n        \"max\": float(a.max()),\n    }\n\n\n@bound(\"describe\", data_args=(\"groups\",))\ndef describe(groups: Dict[str, Sequence[float]]) -> Dict[str, Any]:\n    \"\"\"Group summaries with bootstrap CIs on the mean.\n\n    This is the Grade 5-6 surface: no p-value anywhere, but the interval is\n    already there, so \"three groups did the same experiment and got three\n    answers -- why?\" has somewhere to go.\n    \"\"\"\n    labels, arrs = _prep(groups)\n    rng = np.random.default_rng(20260901)\n    out = {}\n    for lab, a in zip(labels, arrs):\n        d = _describe_one(a)\n        if a.size >= 3:\n            boots = np.array([rng.choice(a, a.size, replace=True).mean() for _ in range(2000)])\n            d[\"mean_ci\"] = [float(np.percentile(boots, 2.5)), float(np.percentile(boots, 97.5))]\n        else:\n            d[\"mean_ci\"] = [float(\"nan\"), float(\"nan\")]\n        out[lab] = d\n    notes = []\n    ns = [d[\"n\"] for d in out.values()]\n    if ns and min(ns) < 3:\n        notes.append(\"At least one group has fewer than 3 observations. The engine will not run an \"\n                     \"inferential test on this data; it can only describe what was measured.\")\n    return {\"groups\": out, \"notes\": notes, \"p_value\": None}\n\n\n@bound(\"one_sample\", data_args=(\"values\",))\ndef one_sample(values: Sequence[float], mu: float = 0.0, alpha: float = ALPHA) -> Dict[str, Any]:\n    \"\"\"One-sample test against a reference value, with a bootstrap interval.\n\n    Serves G9-L9 (is the fuel-cell voltage above the threshold?) and the\n    \"is our count different from the expected count\" shape in G8-L10.\n    \"\"\"\n    a = np.asarray(values, dtype=float).ravel()\n    a = a[np.isfinite(a)]\n    if a.size < MIN_N:\n        return {\"refused\": True, \"reason\": f\"n={a.size} is below the engine's floor of {MIN_N}.\",\n                \"p_value\": None}\n    res = stats.wilcoxon(a - mu) if a.size < 10 else stats.ttest_1samp(a, mu)\n    test = \"Wilcoxon signed-rank (n < 10)\" if a.size < 10 else \"one-sample t-test\"\n    rng = np.random.default_rng(20260901)\n    boots = np.array([rng.choice(a, a.size, replace=True).mean() for _ in range(4999)])\n    return {\n        \"test_used\": test,\n        \"statistic\": float(res.statistic),\n        \"p_value\": float(res.pvalue),\n        \"mean\": float(a.mean()),\n        \"mean_ci\": [float(np.percentile(boots, 2.5)), float(np.percentile(boots, 97.5))],\n        \"reference\": float(mu),\n        \"n\": int(a.size),\n        \"effect_size\": float((a.mean() - mu) / a.std(ddof=1)) if a.std(ddof=1) > 0 else 0.0,\n        \"effect_size_type\": \"cohens_d_one_sample\",\n    }\n\n\ndef _route(labels: List[str], arrs: List[np.ndarray], design: str, panel, prefer_robust: bool\n           ) -> Tuple[str, str]:\n    \"\"\"Pick the test from the assumption checks. Returns (test_key, why).\"\"\"\n    k = len(arrs)\n    smallest = min(a.size for a in arrs)\n    normal = next(a for a in panel if a.name == \"normality\").passed\n    equal_var = next(a for a in panel if a.name == \"equal_variance\").passed\n\n    if design == \"paired\":\n        if smallest < 10 or not normal:\n            return \"wilcoxon\", (f\"Paired design with n={smallest} per pair\"\n                                f\"{' and evidence of non-normality' if not normal else ''}; \"\n                                f\"the signed-rank test makes no distributional assumption.\")\n        return \"ttest_rel\", \"Paired design, samples large enough and no evidence against normality.\"\n\n    if k == 2:\n        if prefer_robust or smallest < 10 or not normal:\n            return \"permutation\", (\n                f\"Two independent groups with n={smallest} in the smallest group\"\n                f\"{' and evidence of non-normality' if not normal else ''}. A permutation test \"\n                f\"shuffles the group labels many times and counts how often chance beats the \"\n                f\"observed difference -- it assumes nothing about the shape of the data, and it is \"\n                f\"what a student can actually verify by hand.\")\n        if not equal_var:\n            return \"welch\", \"Two groups, unequal variances; Welch's t-test does not pool them.\"\n        return \"ttest_ind\", \"Two independent groups, no evidence against normality or equal variance.\"\n\n    if prefer_robust or smallest < 10 or not normal:\n        return \"kruskal\", (\n            f\"{k} independent groups with n={smallest} in the smallest\"\n            f\"{' and evidence of non-normality' if not normal else ''}; Kruskal-Wallis compares \"\n            f\"ranks and does not assume a bell curve.\")\n    if not equal_var:\n        return \"alexandergovern\", (\n            f\"{k} groups with unequal variances; Alexander-Govern is the heteroscedastic \"\n            f\"alternative to one-way ANOVA (Welch's ANOVA family).\")\n    return \"anova\", f\"{k} independent groups, assumptions of one-way ANOVA are not contradicted.\"\n\n\ndef _run(key: str, arrs: List[np.ndarray], alternative: str, seed: int) -> Tuple[float, float, str]:\n    \"\"\"Execute the chosen test. Returns (statistic, p_value, stat_label).\"\"\"\n    if key == \"ttest_ind\":\n        r = stats.ttest_ind(arrs[0], arrs[1], equal_var=True, alternative=alternative)\n        return float(r.statistic), float(r.pvalue), f\"t({len(arrs[0]) + len(arrs[1]) - 2})\"\n    if key == \"welch\":\n        r = stats.ttest_ind(arrs[0], arrs[1], equal_var=False, alternative=alternative)\n        return float(r.statistic), float(r.pvalue), f\"t({float(r.df):.1f})\"\n    if key == \"ttest_rel\":\n        n = min(len(arrs[0]), len(arrs[1]))\n        r = stats.ttest_rel(arrs[0][:n], arrs[1][:n], alternative=alternative)\n        return float(r.statistic), float(r.pvalue), f\"t({n - 1})\"\n    if key == \"wilcoxon\":\n        n = min(len(arrs[0]), len(arrs[1]))\n        r = stats.wilcoxon(arrs[0][:n], arrs[1][:n], alternative=alternative)\n        return float(r.statistic), float(r.pvalue), \"W\"\n    if key == \"mannwhitney\":\n        r = stats.mannwhitneyu(arrs[0], arrs[1], alternative=alternative)\n        return float(r.statistic), float(r.pvalue), \"U\"\n    if key == \"permutation\":\n        def statfn(x, y):\n            return np.mean(x) - np.mean(y)\n        r = stats.permutation_test(\n            (arrs[0], arrs[1]), statfn, permutation_type=\"independent\",\n            alternative=alternative, n_resamples=9999,\n            random_state=np.random.default_rng(seed), vectorized=False)\n        return float(r.statistic), float(r.pvalue), \"mean difference\"\n    if key == \"anova\":\n        r = stats.f_oneway(*arrs)\n        dfb = len(arrs) - 1\n        dfw = sum(len(a) for a in arrs) - len(arrs)\n        return float(r.statistic), float(r.pvalue), f\"F({dfb},{dfw})\"\n    if key == \"alexandergovern\":\n        r = stats.alexandergovern(*arrs)\n        return float(r.statistic), float(r.pvalue), \"A\"\n    if key == \"kruskal\":\n        r = stats.kruskal(*arrs)\n        return float(r.statistic), float(r.pvalue), f\"H({len(arrs) - 1})\"\n    raise ValueError(f\"unknown test key {key!r}\")\n\n\ndef _posthoc(labels: List[str], arrs: List[np.ndarray], parametric: bool) -> List[Dict[str, Any]]:\n    \"\"\"Pairwise follow-up with Holm correction.\n\n    scikit-posthocs (MIT) is the Tier-1 choice; this is the dependency-free\n    Tier-0 equivalent so the browser path is not weaker than the server path.\n    \"\"\"\n    from .ledger import holm_bonferroni\n\n    pairs, praw = [], []\n    for i in range(len(arrs)):\n        for j in range(i + 1, len(arrs)):\n            if parametric:\n                r = stats.ttest_ind(arrs[i], arrs[j], equal_var=False)\n            else:\n                r = stats.mannwhitneyu(arrs[i], arrs[j], alternative=\"two-sided\")\n            pairs.append((i, j, float(r.statistic)))\n            praw.append(float(r.pvalue))\n    padj = holm_bonferroni(praw)\n    out = []\n    for (i, j, s), pr, pa in zip(pairs, praw, padj):\n        g = effects.hedges_g(arrs[i], arrs[j])\n        out.append({\n            \"a\": labels[i], \"b\": labels[j], \"statistic\": s,\n            \"p_raw\": pr, \"p_adjusted\": pa, \"significant\": bool(pa < ALPHA),\n            \"effect_size\": g, \"effect_size_type\": \"hedges_g\",\n            \"cles\": effects.cles(arrs[i], arrs[j]),\n        })\n    return out\n\n\n@bound(\"compare_groups\", data_args=(\"groups\",))\ndef compare_groups(\n    groups: Dict[str, Sequence[float]],\n    design: str = \"independent\",\n    alternative: str = \"two-sided\",\n    justification: str = \"\",\n    alpha: float = ALPHA,\n    prefer_robust: bool = False,\n    posthoc: bool = True,\n    seed: int = 20260901,\n) -> Dict[str, Any]:\n    \"\"\"*\"Is this one really bigger, or did we get lucky?\"*\n\n    The engine picks the test, reports why, returns an effect size with an\n    interval, runs a stability check, and consults the multiple-comparison\n    ledger. `justification` is required by the tool schema, logged, and shown\n    to the teacher (spec section 06).\n\n    Serves G6-L9 (three temperatures), G7-L9 (four salt levels), G8-L9 (four pH\n    levels), G7-L7 (control vs Bacillus).\n    \"\"\"\n    labels, arrs = _prep(groups)\n    if len(arrs) < 2:\n        return {\"refused\": True, \"reason\": \"Need at least two groups to compare.\", \"p_value\": None}\n\n    ns = {lab: int(a.size) for lab, a in zip(labels, arrs)}\n    if min(ns.values()) < MIN_N:\n        return {\n            \"refused\": True,\n            \"reason\": (f\"The smallest group has {min(ns.values())} observation(s). Below {MIN_N} the \"\n                       f\"engine will not run a significance test, because any p-value it produced \"\n                       f\"would be meaningless. Here is what you measured instead.\"),\n            \"n_per_group\": ns,\n            \"descriptives\": {lab: _describe_one(a) for lab, a in zip(labels, arrs)},\n            \"suggestion\": \"Collect at least 5 replicates per group, then ask again.\",\n            \"p_value\": None,\n        }\n\n    panel = assumption_panel(arrs, alpha)\n    key, why = _route(labels, arrs, design, panel, prefer_robust)\n    statistic, p_value, stat_label = _run(key, arrs, alternative, seed)\n\n    k = len(arrs)\n    if k == 2:\n        if key in (\"permutation\", \"wilcoxon\", \"mannwhitney\", \"kruskal\"):\n            es_type = \"rank_biserial\"\n            es = effects.rank_biserial(arrs[0], arrs[1])\n            ci = effects.effsize_ci(arrs[0], arrs[1], \"rank_biserial\", seed=seed)\n        else:\n            es_type = \"hedges_g\"\n            es = effects.hedges_g(arrs[0], arrs[1], paired=(design == \"paired\"))\n            ci = effects.effsize_ci(arrs[0], arrs[1], \"hedges_g\", seed=seed)\n        cl = effects.cles(arrs[0], arrs[1])\n    else:\n        if key == \"kruskal\":\n            es_type, es = \"epsilon_squared\", effects.epsilon_squared(arrs)\n        else:\n            es_type, es = \"eta_squared\", effects.eta_squared(arrs)\n        ci = (float(\"nan\"), float(\"nan\"))\n        cl = float(\"nan\")\n\n    def _test_for_stability(trial: List[np.ndarray]) -> Tuple[float, float]:\n        # Permutation is too slow to run 400+ times; use its rank-based twin for\n        # the stability sweep and say so, rather than silently using a different\n        # alpha level. Everything else re-runs the actual chosen test.\n        kk = \"mannwhitney\" if key == \"permutation\" else key\n        try:\n            _, p, _ = _run(kk, trial, alternative, seed)\n        except Exception:\n            return float(\"nan\"), float(\"nan\")\n        if len(trial) == 2:\n            e = effects.rank_biserial(trial[0], trial[1]) if es_type == \"rank_biserial\" \\\n                else effects.hedges_g(trial[0], trial[1], paired=(design == \"paired\"))\n        else:\n            e = effects.epsilon_squared(trial) if es_type == \"epsilon_squared\" \\\n                else effects.eta_squared(trial)\n        return float(p), float(e)\n\n    stab = stability_check(arrs, _test_for_stability, alpha=alpha, seed=seed)\n    if key == \"permutation\":\n        stab.verdict += (\" (Stability was assessed with the Mann-Whitney twin of the permutation \"\n                         \"test, which is far cheaper to re-run 400 times and agrees with it closely.)\")\n\n    data_id = data_fingerprint(*arrs)\n    led = ledger_for(data_id, alpha=alpha)\n\n    ph = []\n    if posthoc and k > 2 and p_value < alpha:\n        ph = _posthoc(labels, arrs, parametric=(key in (\"anova\", \"alexandergovern\")))\n\n    plain = _plain_language(labels, arrs, key, p_value, es, es_type, ci, cl, alpha, stab)\n\n    return {\n        \"test_used\": key,\n        \"test_label\": {\n            \"ttest_ind\": \"independent-samples t-test\", \"welch\": \"Welch's t-test\",\n            \"ttest_rel\": \"paired t-test\", \"wilcoxon\": \"Wilcoxon signed-rank test\",\n            \"mannwhitney\": \"Mann-Whitney U test\", \"permutation\": \"permutation test (label shuffling)\",\n            \"anova\": \"one-way ANOVA\", \"alexandergovern\": \"Alexander-Govern test\",\n            \"kruskal\": \"Kruskal-Wallis test\",\n        }[key],\n        \"why_this_test\": why,\n        \"statistic\": statistic,\n        \"statistic_label\": stat_label,\n        \"p_value\": p_value,\n        \"alternative\": alternative,\n        \"effect_size\": es,\n        \"effect_size_type\": es_type,\n        \"ci\": [float(ci[0]), float(ci[1])],\n        \"effect_interpretation\": effects.interpret(es, es_type, ci),\n        \"cles\": cl,\n        \"n_per_group\": ns,\n        \"descriptives\": {lab: _describe_one(a) for lab, a in zip(labels, arrs)},\n        \"assumption_checks\": [a.to_dict() for a in panel],\n        \"stability\": stab.to_dict(),\n        \"tests_run_so_far\": led.tests_run_so_far + 1,\n        \"correction_applied\": led.correction_applied,\n        \"ledger\": led.to_dict(),\n        \"posthoc\": ph,\n        \"justification\": justification,\n        \"plain_language\": plain,\n        \"notes\": [a.detail for a in panel if a.severity in (\"warn\", \"block\")],\n    }\n\n\ndef _plain_language(labels, arrs, key, p, es, es_type, ci, cl, alpha, stab) -> str:\n    \"\"\"A sentence a teacher who is not a statistician can read and trust.\n\n    Spec section 02, constraint 4. This string is generated from the computed\n    numbers -- it is never written by the language model.\n    \"\"\"\n    best = labels[int(np.argmax([a.mean() for a in arrs]))]\n    sig = p < alpha\n    lead = (f\"The groups differ by more than chance comfortably explains (p = {p:.4g}); \"\n            f\"{best} had the highest average.\"\n            if sig else\n            f\"The differences between these groups are within what chance alone produces \"\n            f\"(p = {p:.4g}), so this experiment does not show a real difference. \"\n            f\"That is a result, not a failure.\")\n    size = f\" The size of the difference is {effects.interpret(es, es_type, ci)}\"\n    if np.isfinite(ci[0]):\n        size += f\" ({es_type.replace('_', ' ')} = {es:.2f}, 95% CI {ci[0]:.2f} to {ci[1]:.2f}).\"\n    else:\n        size += f\" ({es_type.replace('_', ' ')} = {es:.2f}).\"\n    cles_bit = \"\"\n    if np.isfinite(cl) and len(arrs) == 2:\n        cles_bit = (f\" Put another way: pick one measurement from each group at random and \"\n                    f\"{labels[0]} is higher about {cl * 100:.0f} times out of 100.\")\n    return lead + size + cles_bit + \" \" + stab.verdict\n\n\n@bound(\"correlate\", data_args=(\"x\", \"y\"))\ndef correlate(x: Sequence[float], y: Sequence[float], method: str = \"auto\",\n              alpha: float = ALPHA, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"*\"Do these two things move together?\"*\n\n    Spearman by default for class data. Also returns the Theil-Sen robust slope,\n    because one mis-pipetted tube should not set the line (spec section 04,\n    row 4: robust regression).\n    \"\"\"\n    a = np.asarray(x, dtype=float).ravel()\n    b = np.asarray(y, dtype=float).ravel()\n    m = np.isfinite(a) & np.isfinite(b)\n    a, b = a[m], b[m]\n    n = a.size\n    if n < MIN_N + 1:\n        return {\"refused\": True, \"reason\": f\"Only {n} paired points; need at least {MIN_N + 1}.\",\n                \"p_value\": None}\n\n    if method == \"auto\":\n        sp = stats.shapiro(a).pvalue if n >= 3 else 0.0\n        sq = stats.shapiro(b).pvalue if n >= 3 else 0.0\n        method = \"pearson\" if (n >= 15 and sp > 0.05 and sq > 0.05) else \"spearman\"\n        why = (f\"n={n} with no evidence against normality in either variable.\"\n               if method == \"pearson\" else\n               f\"n={n}; Spearman ranks the values first, so one extreme point cannot drag the \"\n               f\"correlation, and it detects any consistently increasing relationship, not just a \"\n               f\"straight line.\")\n    else:\n        why = f\"Requested explicitly: {method}.\"\n\n    r = stats.pearsonr(a, b) if method == \"pearson\" else stats.spearmanr(a, b)\n    rho = float(r.statistic if hasattr(r, \"statistic\") else r[0])\n    pv = float(r.pvalue)\n\n    rng = np.random.default_rng(seed)\n    boots = []\n    for _ in range(2000):\n        idx = rng.integers(0, n, n)\n        aa, bb = a[idx], b[idx]\n        if np.allclose(aa, aa[0]) or np.allclose(bb, bb[0]):\n            continue\n        rr = stats.pearsonr(aa, bb) if method == \"pearson\" else stats.spearmanr(aa, bb)\n        boots.append(float(rr.statistic if hasattr(rr, \"statistic\") else rr[0]))\n    ci = ([float(np.percentile(boots, 2.5)), float(np.percentile(boots, 97.5))]\n          if boots else [float(\"nan\")] * 2)\n\n    ts = stats.theilslopes(b, a, 0.95)\n    ols = stats.linregress(a, b)\n\n    return {\n        \"method\": method, \"why_this_test\": why,\n        \"statistic\": rho, \"statistic_label\": \"r\" if method == \"pearson\" else \"rho\",\n        \"p_value\": pv, \"ci\": ci, \"n\": int(n),\n        \"effect_size\": rho, \"effect_size_type\": method,\n        \"r_squared\": float(rho ** 2),\n        \"theil_sen\": {\"slope\": float(ts[0]), \"intercept\": float(ts[1]),\n                      \"slope_ci\": [float(ts[2]), float(ts[3])]},\n        \"least_squares\": {\"slope\": float(ols.slope), \"intercept\": float(ols.intercept),\n                          \"stderr\": float(ols.stderr)},\n        \"plain_language\": (\n            f\"{'They do move together' if pv < alpha else 'There is no clear relationship'} \"\n            f\"({'r' if method == 'pearson' else 'rho'} = {rho:.2f}, 95% CI {ci[0]:.2f} to {ci[1]:.2f}, \"\n            f\"p = {pv:.4g}, n = {n}). \"\n            f\"About {rho ** 2 * 100:.0f}% of the variation in one is tracked by the other. \"\n            f\"Moving together is not the same as one causing the other -- your experimental design \"\n            f\"decides that, not this number.\"),\n        \"notes\": ([\"The robust (Theil-Sen) slope and the least-squares slope disagree noticeably, \"\n                   \"which means at least one point is pulling the line. Plot it before believing it.\"]\n                  if abs(ts[0] - ols.slope) > 0.25 * max(1e-12, abs(ols.slope)) else []),\n    }\n\n\n@bound(\"contingency\", data_args=(\"table\",))\ndef contingency(table: Sequence[Sequence[int]], row_labels: Optional[List[str]] = None,\n                col_labels: Optional[List[str]] = None, alpha: float = ALPHA) -> Dict[str, Any]:\n    \"\"\"*\"Are these counts related?\"* Chi-square, or Fisher when cells are thin.\n\n    Serves G5-L9 (water-quality strip categories) and G8-L10 (plaque / no plaque\n    across sample sites).\n    \"\"\"\n    t = np.asarray(table, dtype=float)\n    if t.ndim != 2 or t.size == 0:\n        return {\"refused\": True, \"reason\": \"Need a 2-D table of counts.\", \"p_value\": None}\n    cells = check_cell_counts(t)\n    if not cells.passed and t.shape == (2, 2):\n        r = stats.fisher_exact(t.astype(int))\n        stat, pv, used = float(r.statistic), float(r.pvalue), \"fisher_exact\"\n        why = \"Expected counts are too small for chi-square; Fisher's exact test is valid at any size.\"\n    else:\n        r = stats.chi2_contingency(t)\n        stat, pv, used = float(r.statistic), float(r.pvalue), \"chi2_contingency\"\n        why = (\"Expected counts are large enough for the chi-square approximation.\"\n               if cells.passed else\n               \"Expected counts are small and the table is larger than 2x2; chi-square is reported \"\n               \"but treat the p-value as approximate.\")\n    v = effects.cramers_v(t)\n    return {\n        \"test_used\": used, \"why_this_test\": why,\n        \"statistic\": stat, \"p_value\": pv,\n        \"effect_size\": v, \"effect_size_type\": \"cramers_v\",\n        \"effect_interpretation\": effects.interpret(v, \"cramers_v\"),\n        \"expected\": (np.outer(t.sum(1), t.sum(0)) / t.sum()).tolist(),\n        \"observed\": t.tolist(),\n        \"row_labels\": row_labels, \"col_labels\": col_labels,\n        \"assumption_checks\": [cells.to_dict()],\n        \"notes\": [] if cells.passed else [cells.detail],\n        \"plain_language\": (\n            f\"{'The categories are related' if pv < alpha else 'These categories look independent'} \"\n            f\"(p = {pv:.4g}, Cramer's V = {v:.2f}, {effects.interpret(v, 'cramers_v')}).\"),\n    }\n\n\n@bound(\"trend_test\", data_args=(\"values\", \"times\"))\ndef trend_test(values: Sequence[float], times: Optional[Sequence[float]] = None,\n               alpha: float = ALPHA) -> Dict[str, Any]:\n    \"\"\"*\"Is it going up over time?\"* Mann-Kendall plus a Theil-Sen slope.\n\n    Serves G7-L7 (daily compost temperature) and G9-L9 (daily fuel-cell voltage\n    feeding the Claim-Evidence-Reasoning write-up). Rank-based, so it survives\n    the missed reading on a Sunday and the one bad probe contact.\n    \"\"\"\n    v = np.asarray(values, dtype=float).ravel()\n    t = np.arange(v.size, dtype=float) if times is None else np.asarray(times, dtype=float).ravel()\n    m = np.isfinite(v) & np.isfinite(t)\n    v, t = v[m], t[m]\n    n = v.size\n    if n < 4:\n        return {\"refused\": True, \"reason\": f\"Only {n} readings; need at least 4 for a trend.\",\n                \"p_value\": None}\n\n    # Mann-Kendall S\n    s = 0\n    for i in range(n - 1):\n        s += int(np.sum(np.sign(v[i + 1:] - v[i])))\n    vals, counts = np.unique(v, return_counts=True)\n    tie = np.sum(counts * (counts - 1) * (2 * counts + 5))\n    var_s = (n * (n - 1) * (2 * n + 5) - tie) / 18.0\n    if var_s <= 0:\n        z = 0.0\n    elif s > 0:\n        z = (s - 1) / np.sqrt(var_s)\n    elif s < 0:\n        z = (s + 1) / np.sqrt(var_s)\n    else:\n        z = 0.0\n    pv = float(2 * (1 - stats.norm.cdf(abs(z))))\n\n    ts = stats.theilslopes(v, t, 0.95)\n    tau = stats.kendalltau(t, v)\n\n    direction = \"increasing\" if s > 0 else (\"decreasing\" if s < 0 else \"flat\")\n    return {\n        \"test_used\": \"mann_kendall\",\n        \"why_this_test\": (\"Mann-Kendall only looks at whether later readings are higher or lower than \"\n                          \"earlier ones, so it does not assume a straight line, a bell curve, or \"\n                          \"evenly spaced readings -- all three of which a daily class log breaks.\"),\n        \"statistic\": float(s), \"z\": float(z), \"p_value\": pv,\n        \"effect_size\": float(tau.statistic), \"effect_size_type\": \"kendall_tau\",\n        \"direction\": direction,\n        \"sen_slope\": float(ts[0]), \"sen_slope_ci\": [float(ts[2]), float(ts[3])],\n        \"n\": int(n),\n        \"first\": float(v[0]), \"last\": float(v[-1]),\n        \"plain_language\": (\n            f\"The readings are {direction}\"\n            + (f\" at about {ts[0]:.4g} units per step (95% CI {ts[2]:.4g} to {ts[3]:.4g}), \"\n               f\"and that trend is stronger than chance would produce (p = {pv:.4g}).\"\n               if pv < alpha else\n               f\", but not by more than day-to-day noise would produce anyway (p = {pv:.4g}). \"\n               f\"A longer run of readings would settle it.\")),\n        \"notes\": ([\"The slope interval includes zero, so the direction of the trend is not settled \"\n                   \"even though the test is significant. Report the interval.\"]\n                  if ts[2] * ts[3] <= 0 and pv < alpha else []),\n    }\n",
  "phagequest_engine/ledger.py": "\"\"\"The visible multiple-comparison ledger (spec section 06, point 4).\n\n    \"Run a fifth test on the same data and the platform says so and applies\n    correction, in the interface, where the student and teacher can see it.\"\n\nThe ledger is keyed on `data_id` (the fingerprint of the student's table), so it\nsurvives page reloads, follows the dataset rather than the session, and cannot\nbe evaded by reopening the notebook. It is also the detector for the\nspecification-search loop the spec asks the assistant to refuse.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, asdict\nfrom typing import Dict, List, Optional\n\nimport numpy as np\n\nfrom .transcript import Transcript, TranscriptStore, get_store\n\n__all__ = [\"LedgerEntry\", \"LedgerReport\", \"ledger_for\", \"holm_bonferroni\", \"benjamini_hochberg\"]\n\n\n@dataclass\nclass LedgerEntry:\n    transcript_id: str\n    tool: str\n    call: str\n    p_raw: float\n    p_adjusted: float\n    still_significant: bool\n\n    def to_dict(self) -> Dict:\n        return asdict(self)\n\n\n@dataclass\nclass LedgerReport:\n    data_id: Optional[str]\n    tests_run_so_far: int\n    correction_applied: Optional[str]\n    alpha: float\n    entries: List[Dict]\n    message: str\n    severity: str = \"info\"\n\n    def to_dict(self) -> Dict:\n        return asdict(self)\n\n\ndef holm_bonferroni(pvals: List[float], alpha: float = 0.05) -> List[float]:\n    \"\"\"Holm-Bonferroni step-down. Controls familywise error, uniformly more\n    powerful than plain Bonferroni, and simple enough to explain to a Grade 8:\n    sort the p-values, multiply the smallest by how many tests you ran.\"\"\"\n    p = np.asarray(pvals, dtype=float)\n    m = len(p)\n    if m == 0:\n        return []\n    order = np.argsort(p)\n    adj = np.empty(m)\n    running = 0.0\n    for rank, idx in enumerate(order):\n        val = (m - rank) * p[idx]\n        running = max(running, val)\n        adj[idx] = min(1.0, running)\n    return [float(x) for x in adj]\n\n\ndef benjamini_hochberg(pvals: List[float]) -> List[float]:\n    \"\"\"FDR control -- the right correction for an exploratory sweep (e.g. the\n    Grade 8 four-parameter enzyme sweep) where the cost of a miss exceeds the\n    cost of a false alarm.\"\"\"\n    p = np.asarray(pvals, dtype=float)\n    m = len(p)\n    if m == 0:\n        return []\n    order = np.argsort(p)[::-1]\n    adj = np.empty(m)\n    running = 1.0\n    for rank, idx in enumerate(order):\n        val = p[idx] * m / (m - rank)\n        running = min(running, val)\n        adj[idx] = min(1.0, running)\n    return [float(x) for x in adj]\n\n\ndef ledger_for(\n    data_id: Optional[str],\n    alpha: float = 0.05,\n    method: str = \"holm\",\n    store: Optional[TranscriptStore] = None,\n    threshold: int = 3,\n) -> LedgerReport:\n    \"\"\"Build the ledger for every inferential test run so far on this dataset.\n\n    Correction kicks in at `threshold` tests. Below that we still show the count,\n    because the point is that the student watches the number climb -- the\n    counter is the teaching object, not the correction.\n    \"\"\"\n    st = store or get_store()\n    tests: List[Transcript] = st.inferential_on(data_id)\n    n = len(tests)\n\n    if n == 0:\n        return LedgerReport(data_id, 0, None, alpha, [],\n                            \"No inferential tests have been run on this dataset yet.\", \"info\")\n\n    praw = [float(t.result.get(\"p_value\")) for t in tests]\n    if n >= threshold:\n        padj = holm_bonferroni(praw, alpha) if method == \"holm\" else benjamini_hochberg(praw)\n        applied = \"holm-bonferroni\" if method == \"holm\" else \"benjamini-hochberg\"\n    else:\n        padj = list(praw)\n        applied = None\n\n    entries = [\n        LedgerEntry(t.transcript_id, t.tool, t.call, pr, pa, bool(pa < alpha)).to_dict()\n        for t, pr, pa in zip(tests, praw, padj)\n    ]\n\n    lost = [e for e in entries if e[\"p_raw\"] < alpha <= e[\"p_adjusted\"]]\n    if applied is None:\n        msg = (f\"{n} inferential test{'s' if n != 1 else ''} run on this dataset. \"\n               f\"At {threshold} the platform starts correcting for multiple comparisons.\")\n        sev = \"info\"\n    elif lost:\n        msg = (f\"{n} tests have now been run on this dataset. After {applied} correction, \"\n               f\"{len(lost)} result{'s' if len(lost) != 1 else ''} that looked significant no longer \"\n               f\"{'are' if len(lost) != 1 else 'is'}. That is what running many tests does: \"\n               f\"with {n} tests at alpha {alpha}, you expect about {n * alpha:.1f} false alarms by chance alone.\")\n        sev = \"warn\"\n    else:\n        msg = (f\"{n} tests run on this dataset; {applied} correction applied and every previously \"\n               f\"significant result survives it.\")\n        sev = \"info\"\n\n    return LedgerReport(data_id, n, applied, alpha, entries, msg, sev)\n",
  "phagequest_engine/power.py": "\"\"\"Power and sample size (spec section 04, row 3).\n\n    \"The most-skipped and most valuable module in the whole platform. Making\n    students compute required n before running G7-L7's control-vs-test\n    decomposition -- and showing achieved power afterwards -- does more for\n    scientific literacy than any amount of machine learning.\"\n\nstatsmodels has these and is Tier-1 only. scipy's noncentral t and F\ndistributions give exact answers in Tier-0, so the browser path is not the\nweaker one. Implemented over `scipy.stats.nct` / `ncf` with a bisection solve.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Dict, Optional\n\nimport numpy as np\nfrom scipy import stats\n\nfrom .transcript import bound\n\n__all__ = [\"power_ttest\", \"n_for_ttest\", \"power_anova\", \"n_for_anova\", \"achieved_power\"]\n\n\ndef _safe(value: float, nc: float) -> float:\n    \"\"\"scipy's noncentral t/F return NaN for large noncentrality.\n\n    That region is numerically awkward and pedagogically uninteresting: a\n    noncentrality that large means the design is overwhelmingly powered. Rather\n    than propagate a NaN into a student's answer, saturate it -- and only in the\n    direction the mathematics guarantees.\n    \"\"\"\n    if np.isfinite(value):\n        return float(value)\n    return 1.0 if nc > 10 else float(\"nan\")\n\n\ndef _power_ttest(n_per_group: float, d: float, alpha: float = 0.05,\n                 alternative: str = \"two-sided\") -> float:\n    if n_per_group < 2 or d == 0:\n        return alpha if d == 0 else 0.0\n    df = 2 * n_per_group - 2\n    nc = abs(d) * np.sqrt(n_per_group / 2.0)\n    with np.errstate(all=\"ignore\"):\n        if alternative == \"two-sided\":\n            crit = stats.t.ppf(1 - alpha / 2, df)\n            v = stats.nct.sf(crit, df, nc) + stats.nct.cdf(-crit, df, nc)\n        else:\n            crit = stats.t.ppf(1 - alpha, df)\n            v = stats.nct.sf(crit, df, nc)\n    return _safe(v, nc)\n\n\ndef _solve_n(power_fn, target: float, lo: float = 2.001, hi: float = 1e6) -> float:\n    \"\"\"NaN-safe bisection for the smallest n reaching `target` power.\n\n    `brentq` walks straight into the NaN region above n~1000 for large effects.\n    Bisection with a monotonicity assumption (power increases with n, which is\n    true for every design here) is both safer and easier to reason about.\n    \"\"\"\n    if power_fn(lo) >= target:\n        return lo\n    if not (power_fn(hi) >= target):\n        return hi\n    for _ in range(200):\n        mid = 0.5 * (lo + hi)\n        p = power_fn(mid)\n        if not np.isfinite(p):\n            hi = mid          # NaN only occurs where power is effectively 1\n            continue\n        if p >= target:\n            hi = mid\n        else:\n            lo = mid\n        if hi - lo < 1e-4:\n            break\n    return hi\n\n\ndef _power_anova(n_per_group: float, f: float, k_groups: int, alpha: float = 0.05) -> float:\n    if n_per_group < 2 or f == 0:\n        return alpha if f == 0 else 0.0\n    df1 = k_groups - 1\n    df2 = k_groups * (n_per_group - 1)\n    if df2 < 1:\n        return 0.0\n    nc = f ** 2 * n_per_group * k_groups\n    with np.errstate(all=\"ignore\"):\n        crit = stats.f.ppf(1 - alpha, df1, df2)\n        v = stats.ncf.sf(crit, df1, df2, nc)\n    return _safe(v, nc)\n\n\n@bound(\"power_ttest\")\ndef power_ttest(n_per_group: int, effect_size: float, alpha: float = 0.05,\n                alternative: str = \"two-sided\") -> Dict[str, Any]:\n    \"\"\"Power of a two-group comparison at a given n and effect size.\"\"\"\n    p = _power_ttest(float(n_per_group), float(effect_size), alpha, alternative)\n    return {\n        \"power\": p, \"n_per_group\": int(n_per_group), \"effect_size\": float(effect_size),\n        \"effect_size_type\": \"cohens_d\", \"alpha\": alpha, \"alternative\": alternative,\n        \"plain_language\": (\n            f\"With {n_per_group} per group, if the real difference is d = {effect_size:g}, this \"\n            f\"experiment finds it about {p * 100:.0f} times out of 100. \"\n            + (\"That is a well-powered experiment.\" if p >= 0.8 else\n               f\"That means it MISSES a real difference about {(1 - p) * 100:.0f} times out of 100 -- \"\n               f\"so a non-significant result here would tell you almost nothing.\")),\n        \"adequate\": bool(p >= 0.8),\n    }\n\n\n@bound(\"n_for_ttest\")\ndef n_for_ttest(effect_size: float, power: float = 0.8, alpha: float = 0.05,\n                alternative: str = \"two-sided\") -> Dict[str, Any]:\n    \"\"\"*\"How many samples do we need?\"* -- asked BEFORE the experiment.\n\n    This is the function the platform puts in front of a student at the design\n    stage of G7-L7 and G7-L9, before a single tube is filled.\n    \"\"\"\n    d = abs(float(effect_size))\n    if d <= 0:\n        return {\"refused\": True, \"reason\": \"An effect size of zero needs infinitely many samples. \"\n                                           \"Decide how big a difference would actually matter first.\"}\n    n = _solve_n(lambda x: _power_ttest(x, d, alpha, alternative), power)\n    n_ceil = int(np.ceil(n))\n    return {\n        \"n_per_group\": n_ceil, \"n_total\": 2 * n_ceil,\n        \"effect_size\": d, \"effect_size_type\": \"cohens_d\",\n        \"power\": power, \"alpha\": alpha, \"alternative\": alternative,\n        \"feasible\": bool(n_ceil <= 30),\n        \"plain_language\": (\n            f\"To have a {power * 100:.0f}% chance of detecting a difference of d = {d:g}, you need \"\n            f\"{n_ceil} in EACH group ({2 * n_ceil} total). \"\n            + (f\"That is achievable in a class experiment.\" if n_ceil <= 30 else\n               f\"That is more than a class can realistically produce. Either pool data across \"\n               f\"classes, or accept that this experiment can only detect a larger difference -- \"\n               f\"and say so in your report rather than pretending otherwise.\")),\n    }\n\n\n@bound(\"power_anova\")\ndef power_anova(n_per_group: int, effect_size_f: float, k_groups: int,\n                alpha: float = 0.05) -> Dict[str, Any]:\n    \"\"\"Power for a one-way design. `effect_size_f` is Cohen's f (f^2 = eta^2/(1-eta^2)).\"\"\"\n    p = _power_anova(float(n_per_group), float(effect_size_f), int(k_groups), alpha)\n    eta2 = effect_size_f ** 2 / (1 + effect_size_f ** 2)\n    return {\n        \"power\": p, \"n_per_group\": int(n_per_group), \"k_groups\": int(k_groups),\n        \"effect_size\": float(effect_size_f), \"effect_size_type\": \"cohens_f\",\n        \"equivalent_eta_squared\": float(eta2), \"alpha\": alpha,\n        \"adequate\": bool(p >= 0.8),\n        \"plain_language\": (\n            f\"{k_groups} groups of {n_per_group}: this design detects an effect of f = \"\n            f\"{effect_size_f:g} (eta-squared {eta2:.2f}) about {p * 100:.0f} times out of 100.\"),\n    }\n\n\n@bound(\"n_for_anova\")\ndef n_for_anova(effect_size_f: float, k_groups: int, power: float = 0.8,\n                alpha: float = 0.05) -> Dict[str, Any]:\n    \"\"\"Required n per group for a one-way design.\n\n    G7-L9 uses four salt levels, G8-L9 four pH levels, G6-L9 three temperatures.\n    This is the number that tells a class whether three tubes per level is a\n    real experiment or a decorative one.\n    \"\"\"\n    f = abs(float(effect_size_f))\n    if f <= 0:\n        return {\"refused\": True, \"reason\": \"Effect size must be greater than zero.\"}\n    n = _solve_n(lambda x: _power_anova(x, f, int(k_groups), alpha), power)\n    n_ceil = int(np.ceil(n))\n    return {\n        \"n_per_group\": n_ceil, \"n_total\": n_ceil * int(k_groups),\n        \"k_groups\": int(k_groups), \"effect_size\": f, \"effect_size_type\": \"cohens_f\",\n        \"power\": power, \"alpha\": alpha, \"feasible\": bool(n_ceil <= 30),\n        \"plain_language\": (\n            f\"With {k_groups} levels and a target of {power * 100:.0f}% power, you need {n_ceil} \"\n            f\"replicates at EACH level -- {n_ceil * k_groups} tubes in total.\"),\n    }\n\n\n@bound(\"achieved_power\", data_args=(\"observed_effect\",))\ndef achieved_power(observed_effect: float, n_per_group: int, k_groups: int = 2,\n                   alpha: float = 0.05, effect_size_type: str = \"hedges_g\") -> Dict[str, Any]:\n    \"\"\"Power the experiment actually had, reported after the fact.\n\n    Deliberately framed as \"what this experiment COULD have detected\", not as\n    \"post-hoc power\", because post-hoc power computed from the observed effect\n    is a well-known statistical fallacy -- it is a deterministic function of the\n    p-value and adds no information. The honest use is the *detectable* effect:\n    what is the smallest difference this design had a fair chance of finding?\n    \"\"\"\n    d = abs(float(observed_effect))\n    if effect_size_type in (\"eta_squared\", \"epsilon_squared\"):\n        f = np.sqrt(max(0.0, d) / max(1e-12, 1 - d))\n        p = _power_anova(float(n_per_group), f, k_groups, alpha)\n        mde = _solve_n(lambda x: _power_anova(float(n_per_group), x, k_groups, alpha), 0.8,\n                       lo=1e-4, hi=50.0)\n        mde_type = \"cohens_f\"\n    else:\n        p = _power_ttest(float(n_per_group), d, alpha)\n        mde = _solve_n(lambda x: _power_ttest(float(n_per_group), x, alpha), 0.8,\n                       lo=1e-4, hi=50.0)\n        mde_type = \"cohens_d\"\n    return {\n        \"power_at_observed_effect\": p,\n        \"minimum_detectable_effect\": float(mde),\n        \"minimum_detectable_effect_type\": mde_type,\n        \"n_per_group\": int(n_per_group), \"alpha\": alpha,\n        \"caution\": (\"Power computed from the effect you observed is not evidence about your result -- \"\n                    \"it is just the p-value in a different costume. Use the minimum detectable effect \"\n                    \"instead: it describes the experiment, not the outcome.\"),\n        \"plain_language\": (\n            f\"With {n_per_group} per group, the smallest effect this design had a fair (80%) chance \"\n            f\"of detecting was about {mde_type.replace('_', ' ')} = {mde:.2f}. \"\n            f\"Your observed effect was {d:.2f}. \"\n            + (\"So the experiment was big enough to see an effect this size.\"\n               if d >= mde else\n               \"So an effect this size was below what this experiment could reliably detect -- \"\n               \"which is why the result is uncertain, and it is a design problem, not a data problem.\")),\n    }\n",
  "phagequest_engine/registry.py": "\"\"\"The typed tool registry (spec section 06, point 1).\n\n    \"Statistics are typed tools, not 'write some Python.' The model chooses the\n    test and explains the output; it never computes.\"\n\nEvery tool here has a JSON schema, a declared grade band, and a declared\ncurriculum origin. The schema is what makes the choice auditable: a teacher can\nread `compare_groups(design=\"independent\", justification=\"...\")` and see what\nwas asked, independently of what the model said about it.\n\n`justification` is required on every inferential tool. It is logged, shown to\nthe teacher, and it is the thing the specification-search detector reads.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Any, Callable, Dict, List, Optional\n\nfrom . import curves, diversity, geometry, inference, power, resampling, sequence, validation\nfrom .simulation import labmath, ode, plaque, stochastic\n\n__all__ = [\"Tool\", \"TOOLS\", \"tool_schemas\", \"call_tool\", \"tools_for_grade\"]\n\n\n@dataclass\nclass Tool:\n    name: str\n    fn: Callable\n    summary: str\n    parameters: Dict[str, Any]        # JSON schema\n    grades: str                       # e.g. \"5-12\"\n    curriculum: str = \"\"\n    inferential: bool = False\n    category: str = \"statistics\"\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\"name\": self.name, \"description\": self.summary,\n                \"input_schema\": self.parameters, \"grades\": self.grades,\n                \"curriculum\": self.curriculum, \"category\": self.category,\n                \"inferential\": self.inferential}\n\n\ndef _p(**props) -> Dict[str, Any]:\n    required = [k for k, v in props.items() if v.pop(\"_required\", False)]\n    return {\"type\": \"object\", \"properties\": props, \"required\": required,\n            \"additionalProperties\": False}\n\n\n_NUM_ARRAY = {\"type\": \"array\", \"items\": {\"type\": \"number\"}}\n_JUSTIFY = {\"type\": \"string\", \"_required\": True,\n            \"description\": \"Why this test, on this data, right now. Logged and shown to the \"\n                           \"teacher. One sentence about the DESIGN, not about the desired result.\"}\n_GROUPS = {\"type\": \"object\", \"_required\": True,\n           \"additionalProperties\": _NUM_ARRAY,\n           \"description\": \"Group label -> its measurements. One entry per condition.\"}\n\n\nTOOLS: Dict[str, Tool] = {}\n\n\ndef _register(t: Tool) -> Tool:\n    TOOLS[t.name] = t\n    return t\n\n\n# ---------------------------------------------------------------- statistics\n_register(Tool(\n    \"describe\", inference.describe,\n    \"Summarise each group: n, mean, spread and a bootstrap interval on the mean. \"\n    \"No p-values. This is the Grade 5-6 surface and the safe first call for any dataset.\",\n    _p(groups=_GROUPS), grades=\"5-12\", curriculum=\"G5-L9, G6-L9\", category=\"statistics\"))\n\n_register(Tool(\n    \"compare_groups\", inference.compare_groups,\n    \"Is one group really different, or did we get lucky? Chooses the test from assumption \"\n    \"checks, always returns an effect size with an interval, runs an automatic stability check, \"\n    \"and applies the multiple-comparison ledger. Never computes on fewer than 3 per group.\",\n    _p(groups=_GROUPS,\n       design={\"type\": \"string\", \"enum\": [\"independent\", \"paired\"], \"default\": \"independent\"},\n       alternative={\"type\": \"string\", \"enum\": [\"two-sided\", \"less\", \"greater\"],\n                    \"default\": \"two-sided\"},\n       prefer_robust={\"type\": \"boolean\", \"default\": False,\n                      \"description\": \"Force a rank/permutation route regardless of assumptions.\"},\n       justification=_JUSTIFY),\n    grades=\"7-12\", curriculum=\"G6-L9, G7-L7, G7-L9, G8-L9\", inferential=True))\n\n_register(Tool(\n    \"shuffle_test\", resampling.shuffle_test,\n    \"The Grade 7 test: mix the two groups together, split them at random many times, and count \"\n    \"how often chance beats the real difference. Returns the null distribution so it can be \"\n    \"drawn. Assumes nothing about the shape of the data.\",\n    _p(group_a=dict(_NUM_ARRAY, _required=True), group_b=dict(_NUM_ARRAY, _required=True),\n       statistic={\"type\": \"string\", \"enum\": [\"mean_difference\", \"median_difference\",\n                                             \"ratio_of_means\"], \"default\": \"mean_difference\"},\n       alternative={\"type\": \"string\", \"enum\": [\"two-sided\", \"less\", \"greater\"],\n                    \"default\": \"two-sided\"},\n       justification=_JUSTIFY),\n    grades=\"7-12\", curriculum=\"G7-L4, G7-L9\", inferential=True))\n\n_register(Tool(\n    \"correlate\", inference.correlate,\n    \"Do two measurements move together? Picks Spearman or Pearson from the data, returns a \"\n    \"bootstrap interval, and reports the robust Theil-Sen slope alongside least squares.\",\n    _p(x=dict(_NUM_ARRAY, _required=True), y=dict(_NUM_ARRAY, _required=True),\n       method={\"type\": \"string\", \"enum\": [\"auto\", \"pearson\", \"spearman\"], \"default\": \"auto\"},\n       justification=_JUSTIFY),\n    grades=\"8-12\", curriculum=\"G8-L12\", inferential=True))\n\n_register(Tool(\n    \"contingency\", inference.contingency,\n    \"Are two categorical things related? Chi-square, or Fisher's exact test when the expected \"\n    \"counts are too small for it.\",\n    _p(table={\"type\": \"array\", \"_required\": True,\n              \"items\": {\"type\": \"array\", \"items\": {\"type\": \"integer\"}}},\n       row_labels={\"type\": \"array\", \"items\": {\"type\": \"string\"}},\n       col_labels={\"type\": \"array\", \"items\": {\"type\": \"string\"}},\n       justification=_JUSTIFY),\n    grades=\"8-12\", curriculum=\"G5-L9, G8-L10\", inferential=True))\n\n_register(Tool(\n    \"trend_test\", inference.trend_test,\n    \"Is a series of daily readings going up or down? Mann-Kendall plus a Theil-Sen slope with an \"\n    \"interval. Survives missed days and one bad probe contact.\",\n    _p(values=dict(_NUM_ARRAY, _required=True), times=_NUM_ARRAY, justification=_JUSTIFY),\n    grades=\"9-12\", curriculum=\"G7-L7, G9-L9\", inferential=True))\n\n_register(Tool(\n    \"bootstrap_ci\", resampling.bootstrap_ci,\n    \"How uncertain is this number? Bias-corrected bootstrap interval on a mean, median, SD or IQR.\",\n    _p(values=dict(_NUM_ARRAY, _required=True),\n       statistic={\"type\": \"string\", \"enum\": [\"mean\", \"median\", \"sd\", \"max\", \"min\", \"iqr\"],\n                  \"default\": \"mean\"},\n       confidence={\"type\": \"number\", \"default\": 0.95, \"minimum\": 0.5, \"maximum\": 0.999}),\n    grades=\"6-12\", curriculum=\"all measurement lessons\"))\n\n_register(Tool(\n    \"jackknife\", resampling.jackknife,\n    \"Which single measurement is carrying the result? Leave-one-out influence.\",\n    _p(values=dict(_NUM_ARRAY, _required=True),\n       statistic={\"type\": \"string\", \"enum\": [\"mean\", \"median\", \"sd\", \"iqr\"], \"default\": \"mean\"}),\n    grades=\"8-12\", curriculum=\"G8-L10 error analysis\"))\n\n# ---------------------------------------------------------------- power\n_register(Tool(\n    \"n_for_ttest\", power.n_for_ttest,\n    \"How many samples do we need? Ask BEFORE the experiment. Returns required n per group for a \"\n    \"two-group comparison at a target power.\",\n    _p(effect_size={\"type\": \"number\", \"_required\": True,\n                    \"description\": \"Cohen's d -- how big a difference would actually matter to you.\"},\n       power={\"type\": \"number\", \"default\": 0.8}, alpha={\"type\": \"number\", \"default\": 0.05}),\n    grades=\"8-12\", curriculum=\"G7-L7, G7-L9 (design stage)\"))\n\n_register(Tool(\n    \"n_for_anova\", power.n_for_anova,\n    \"Required replicates per level for a multi-level experiment (three temperatures, four pH \"\n    \"levels, four salt levels).\",\n    _p(effect_size_f={\"type\": \"number\", \"_required\": True},\n       k_groups={\"type\": \"integer\", \"_required\": True, \"minimum\": 2},\n       power={\"type\": \"number\", \"default\": 0.8}),\n    grades=\"8-12\", curriculum=\"G6-L9, G7-L9, G8-L9 (design stage)\"))\n\n_register(Tool(\n    \"achieved_power\", power.achieved_power,\n    \"After the experiment: what is the smallest effect this design could reliably have detected? \"\n    \"Reports the minimum detectable effect, not post-hoc power, and says why.\",\n    _p(observed_effect={\"type\": \"number\", \"_required\": True},\n       n_per_group={\"type\": \"integer\", \"_required\": True},\n       k_groups={\"type\": \"integer\", \"default\": 2},\n       effect_size_type={\"type\": \"string\", \"default\": \"hedges_g\"}),\n    grades=\"9-12\", curriculum=\"reporting stage\"))\n\n# ---------------------------------------------------------------- curves\n_register(Tool(\n    \"fit_curve\", curves.fit_curve,\n    \"Fit a named model to x-y data and report every parameter with a bootstrap interval. \"\n    \"Refuses to fit a model with more parameters than the data can support.\",\n    _p(x=dict(_NUM_ARRAY, _required=True), y=dict(_NUM_ARRAY, _required=True),\n       model={\"type\": \"string\", \"_required\": True, \"enum\": sorted(curves.MODELS)},\n       justification=_JUSTIFY),\n    grades=\"8-12\", curriculum=\"G8-L12\"))\n\n_register(Tool(\n    \"compare_models\", curves.compare_models,\n    \"Fit several curves to the same data and rank by AICc. Always includes a straight line, \"\n    \"because the honest question is whether the curve beats the line by enough to justify itself.\",\n    _p(x=dict(_NUM_ARRAY, _required=True), y=dict(_NUM_ARRAY, _required=True),\n       models={\"type\": \"array\", \"items\": {\"type\": \"string\", \"enum\": sorted(curves.MODELS)}}),\n    grades=\"9-12\", curriculum=\"G8-L12\"))\n\n_register(Tool(\n    \"fit_growth_curve\", curves.fit_growth_curve,\n    \"Growth-curve analysis: lag, maximum growth rate, carrying capacity -- and, if the culture \"\n    \"crashed, the timing and depth of the lysis, which is the interesting half.\",\n    _p(time=dict(_NUM_ARRAY, _required=True), density=dict(_NUM_ARRAY, _required=True),\n       model={\"type\": \"string\", \"enum\": [\"gompertz\", \"logistic_growth\"], \"default\": \"gompertz\"}),\n    grades=\"9-12\", curriculum=\"G6-L9, G7-L9, G8-L9\"))\n\n# ---------------------------------------------------------------- diversity\n_register(Tool(\n    \"alpha_diversity\", diversity.alpha_diversity,\n    \"Richness, Shannon, Simpson, Chao1 and evenness per sample, with a sequencing-depth warning.\",\n    _p(samples={\"type\": \"object\", \"_required\": True,\n                \"additionalProperties\": {\"type\": \"object\",\n                                         \"additionalProperties\": {\"type\": \"number\"}},\n                \"description\": \"sample name -> {taxon: count}\"}),\n    grades=\"9-12\", curriculum=\"G9-L12\", category=\"diversity\"))\n\n_register(Tool(\n    \"compare_composition\", diversity.compare_composition,\n    \"Are these communities different? The SAFE front door: refuses to hand proportions to a \"\n    \"t-test, runs CLR + PERMANOVA instead, and explains why. Use this, never compare_groups, on \"\n    \"abundance data.\",\n    _p(samples={\"type\": \"object\", \"_required\": True,\n                \"additionalProperties\": {\"type\": \"object\",\n                                         \"additionalProperties\": {\"type\": \"number\"}}},\n       groups={\"type\": \"object\", \"_required\": True,\n               \"additionalProperties\": {\"type\": \"string\"},\n               \"description\": \"sample name -> group label\"},\n       metric={\"type\": \"string\", \"enum\": [\"aitchison\", \"braycurtis\", \"jaccard\"],\n               \"default\": \"aitchison\"}),\n    grades=\"9-12\", curriculum=\"G9-L12, G8-L10\", inferential=True, category=\"diversity\"))\n\n_register(Tool(\n    \"rarefaction_curve\", diversity.rarefaction_curve,\n    \"Did we look hard enough? Richness against counting effort, with intervals.\",\n    _p(counts=dict(_NUM_ARRAY, _required=True)),\n    grades=\"9-12\", curriculum=\"G9-L12\", category=\"diversity\"))\n\n# ---------------------------------------------------------------- lab maths\n_register(Tool(\n    \"dilution_series\", labmath.dilution_series,\n    \"The 1:10 chain with the powers of ten made explicit, and which tube to plate.\",\n    _p(start_concentration={\"type\": \"number\", \"default\": 1e9},\n       fold={\"type\": \"number\", \"default\": 10}, steps={\"type\": \"integer\", \"default\": 8},\n       volume_transferred={\"type\": \"number\", \"default\": 0.1},\n       volume_diluent={\"type\": \"number\", \"default\": 0.9}),\n    grades=\"5-12\", curriculum=\"G5-L6\", category=\"lab\"))\n\n_register(Tool(\n    \"pfu_per_ml\", labmath.pfu_per_ml,\n    \"Titre from one plate WITH its Poisson counting interval, and whether the count was in the \"\n    \"usable 30-300 range.\",\n    _p(plaque_count={\"type\": \"integer\", \"_required\": True, \"minimum\": 0},\n       dilution_factor={\"type\": \"number\", \"_required\": True, \"minimum\": 1},\n       volume_plated_mL={\"type\": \"number\", \"default\": 0.1}),\n    grades=\"8-12\", curriculum=\"G8-L10\", category=\"lab\"))\n\n_register(Tool(\n    \"titre_from_plates\", labmath.titre_from_plates,\n    \"Pool several plates into one titre correctly (not by averaging), and test whether the \"\n    \"plates agree with each other better than chance.\",\n    _p(plaque_counts={\"type\": \"array\", \"items\": {\"type\": \"integer\"}, \"_required\": True},\n       dilution_factors=dict(_NUM_ARRAY, _required=True),\n       volume_plated_mL={\"type\": \"number\", \"default\": 0.1}),\n    grades=\"9-12\", curriculum=\"G8-L10\", inferential=True, category=\"lab\"))\n\n_register(Tool(\n    \"moi\", labmath.moi,\n    \"Multiplicity of infection, plus what Poisson says actually happens at it -- including that \"\n    \"37% of cells are untouched at MOI 1.\",\n    _p(phage_pfu_per_mL={\"type\": \"number\", \"_required\": True},\n       bacteria_cfu_per_mL={\"type\": \"number\", \"_required\": True},\n       volume_mL={\"type\": \"number\", \"default\": 1.0}),\n    grades=\"8-12\", curriculum=\"G8-L10\", category=\"lab\"))\n\n# ---------------------------------------------------------------- simulation\n_register(Tool(\n    \"simulate\", ode.simulate,\n    \"Run a host-phage population simulation: lytic, lysogenic, evolving resistance, or a \"\n    \"resource-explicit chemostat. Erlang latent-period chain, LSODA solver.\",\n    _p(model={\"type\": \"string\", \"enum\": sorted(ode.MODELS), \"default\": \"lytic\"},\n       params={\"type\": \"object\", \"additionalProperties\": {\"type\": \"number\"}},\n       S0={\"type\": \"number\", \"default\": 1e6}, P0={\"type\": \"number\", \"default\": 1e4},\n       hours={\"type\": \"number\", \"default\": 24}),\n    grades=\"8-12\", curriculum=\"G8-L12, G8-L10, G6-L8\", category=\"simulation\"))\n\n_register(Tool(\n    \"parameter_sweep\", ode.parameter_sweep,\n    \"Sweep one parameter across a range and tabulate the outcome. Output feeds straight into \"\n    \"fit_curve. This is G8-L12's four-parameter-sweep pedagogy with a phage in the flask.\",\n    _p(model={\"type\": \"string\", \"enum\": sorted(ode.MODELS), \"default\": \"lytic\"},\n       parameter={\"type\": \"string\", \"_required\": True},\n       values=_NUM_ARRAY, n_values={\"type\": \"integer\", \"default\": 9},\n       base_params={\"type\": \"object\", \"additionalProperties\": {\"type\": \"number\"}}),\n    grades=\"8-12\", curriculum=\"G8-L12\", category=\"simulation\"))\n\n_register(Tool(\n    \"one_step_growth\", ode.one_step_growth,\n    \"The one-step growth curve, run at 1, 3 and n latent-period stages side by side, so the \"\n    \"latent period becomes visible as stages rather than a hidden delay.\",\n    _p(latent={\"type\": \"number\", \"default\": 0.5}, burst={\"type\": \"number\", \"default\": 100},\n       n_stages={\"type\": \"integer\", \"default\": 20, \"minimum\": 1, \"maximum\": 40}),\n    grades=\"9-12\", curriculum=\"G8-L10\", category=\"simulation\"))\n\n_register(Tool(\n    \"gillespie_lytic\", stochastic.gillespie_lytic,\n    \"Exact stochastic simulation, repeated many times with identical settings, to show that they \"\n    \"do not come out the same. The answer to 'why did my plate have no plaques?'.\",\n    _p(S0={\"type\": \"integer\", \"default\": 200}, P0={\"type\": \"integer\", \"default\": 5},\n       adsorption={\"type\": \"number\", \"default\": 1e-3}, burst={\"type\": \"integer\", \"default\": 50},\n       n_runs={\"type\": \"integer\", \"default\": 30, \"minimum\": 2, \"maximum\": 200}),\n    grades=\"9-12\", curriculum=\"G8-L10\", category=\"simulation\"))\n\n_register(Tool(\n    \"poisson_plaques\", stochastic.poisson_plaques,\n    \"Why an empty plate is not proof of no phage: the Poisson probability of zero, and a \"\n    \"simulated set of plates to look at.\",\n    _p(expected_plaques={\"type\": \"number\", \"default\": 3.0},\n       n_plates={\"type\": \"integer\", \"default\": 20}),\n    grades=\"8-12\", curriculum=\"G8-L10\", category=\"simulation\"))\n\n_register(Tool(\n    \"plaque_growth\", plaque.plaque_growth,\n    \"Grow plaques on a simulated lawn and measure radius, area and edge roughness over time.\",\n    _p(size={\"type\": \"integer\", \"default\": 151, \"minimum\": 21, \"maximum\": 401},\n       steps={\"type\": \"integer\", \"default\": 120},\n       latent_steps={\"type\": \"integer\", \"default\": 4},\n       spread_probability={\"type\": \"number\", \"default\": 0.45, \"minimum\": 0, \"maximum\": 1},\n       resistant_fraction={\"type\": \"number\", \"default\": 0.0, \"minimum\": 0, \"maximum\": 1}),\n    grades=\"8-12\", curriculum=\"G8-L10\", category=\"simulation\"))\n\n# ---------------------------------------------------------------- sequence\n_register(Tool(\n    \"translate\", sequence.translate,\n    \"Translate DNA to protein codon by codon, showing the working, so a student can check their \"\n    \"codon-wheel answer and see WHERE they went wrong.\",\n    _p(sequence={\"type\": \"string\", \"_required\": True},\n       frame={\"type\": \"integer\", \"default\": 1, \"enum\": [1, 2, 3, -1, -2, -3]}),\n    grades=\"9-12\", curriculum=\"G9-L7\", category=\"sequence\"))\n\n_register(Tool(\n    \"gc_content\", sequence.gc_content,\n    \"GC content, melting temperature estimate, and an optional sliding window along the genome.\",\n    _p(sequence={\"type\": \"string\", \"_required\": True},\n       window={\"type\": \"integer\", \"default\": 0}),\n    grades=\"6-12\", curriculum=\"G6-L10, G8-L11\", category=\"sequence\"))\n\n_register(Tool(\n    \"find_orfs\", sequence.find_orfs,\n    \"The simplest possible gene caller, with its limitations stated. Exists so a student can see \"\n    \"what a naive caller does and where it fails -- the setup for comparing PHANOTATE to Prodigal.\",\n    _p(sequence={\"type\": \"string\", \"_required\": True},\n       min_length_aa={\"type\": \"integer\", \"default\": 30},\n       all_frames={\"type\": \"boolean\", \"default\": True}),\n    grades=\"9-12\", curriculum=\"G5-L11, G9-L7\", category=\"sequence\"))\n\n_register(Tool(\n    \"codon_usage\", sequence.codon_usage,\n    \"Codon usage bias (RSCU) -- which spelling of each amino acid this genome prefers.\",\n    _p(sequence={\"type\": \"string\", \"_required\": True}, frame={\"type\": \"integer\", \"default\": 1}),\n    grades=\"11-12\", curriculum=\"G9-L7\", category=\"sequence\"))\n\n# ---------------------------------------------------------------- geometry\n_register(Tool(\n    \"tetranucleotide_vector\", geometry.tetranucleotide_vector,\n    \"The Fingerprint module: a genome's 256-dimensional 4-mer profile. G5-L11's barcode matching, \"\n    \"grown up.\",\n    _p(sequence={\"type\": \"string\", \"_required\": True}, name={\"type\": \"string\", \"default\": \"sequence\"},\n       canonical={\"type\": \"boolean\", \"default\": False}),\n    grades=\"7-12\", curriculum=\"G5-L11\", category=\"geometry\"))\n\n_register(Tool(\n    \"component_sweep\", geometry.component_sweep,\n    \"The Islands module: build the k-NN graph at every k and find the stability plateau. A \"\n    \"structure that survives many values of k is real; one that appears at a single k is an \"\n    \"artefact of the setting.\",\n    _p(distance_matrix={\"type\": \"array\", \"_required\": True,\n                        \"items\": {\"type\": \"array\", \"items\": {\"type\": \"number\"}}},\n       k_min={\"type\": \"integer\", \"default\": 3}, k_max={\"type\": \"integer\", \"default\": 40},\n       names={\"type\": \"array\", \"items\": {\"type\": \"string\"}}),\n    grades=\"9-12\", curriculum=\"capstone\", category=\"geometry\"))\n\n_register(Tool(\n    \"bridge_analysis\", geometry.bridge_analysis,\n    \"The Bridges module: Ollivier-Ricci curvature, the negatively curved edges holding two clades \"\n    \"together, and the hub genomes carrying them. Runs weighted AND unweighted and reports both.\",\n    _p(distance_matrix={\"type\": \"array\", \"_required\": True,\n                        \"items\": {\"type\": \"array\", \"items\": {\"type\": \"number\"}}},\n       clade_labels={\"type\": \"array\", \"items\": {\"type\": \"integer\"}},\n       k={\"type\": \"integer\"}, alpha={\"type\": \"number\", \"default\": 0.5},\n       names={\"type\": \"array\", \"items\": {\"type\": \"string\"}},\n       method={\"type\": \"string\", \"enum\": [\"exact\", \"sinkhorn\"], \"default\": \"exact\"}),\n    grades=\"11-12\", curriculum=\"capstone / WP2\", inferential=True, category=\"geometry\"))\n\n# ---------------------------------------------------------------- data\n_register(Tool(\n    \"validate_table\", validation.validate_table,\n    \"Check an uploaded table before any statistics touch it. Every problem names the spreadsheet \"\n    \"row, the column, the value, and what to do about it.\",\n    _p(rows={\"type\": \"array\", \"_required\": True, \"items\": {\"type\": \"object\"}},\n       template={\"type\": \"string\", \"enum\": sorted(validation.TEMPLATES)}),\n    grades=\"5-12\", curriculum=\"every data-collecting lesson\", category=\"data\"))\n\n_register(Tool(\n    \"infer_schema\", validation.infer_schema,\n    \"Work out what an unfamiliar upload contains and suggest the closest curriculum template.\",\n    _p(rows={\"type\": \"array\", \"_required\": True, \"items\": {\"type\": \"object\"}}),\n    grades=\"5-12\", category=\"data\"))\n\n\n# ==========================================================================\ndef tool_schemas(grade: Optional[int] = None,\n                 categories: Optional[List[str]] = None) -> List[Dict[str, Any]]:\n    \"\"\"Schemas for the tools a given grade is allowed to reach.\n\n    The grade ladder (spec section 05) is enforced here rather than in the UI,\n    so the model cannot be talked into a Grade 12 tool by a Grade 5 student.\n    \"\"\"\n    out = []\n    for t in TOOLS.values():\n        if categories and t.category not in categories:\n            continue\n        if grade is not None:\n            lo, _, hi = t.grades.partition(\"-\")\n            try:\n                if not (int(lo) <= grade <= int(hi or lo)):\n                    continue\n            except ValueError:\n                pass\n        out.append(t.to_dict())\n    return sorted(out, key=lambda d: (d[\"category\"], d[\"name\"]))\n\n\ndef tools_for_grade(grade: int) -> List[str]:\n    return [d[\"name\"] for d in tool_schemas(grade=grade)]\n\n\ndef call_tool(name: str, arguments: Dict[str, Any],\n              grade: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"Invoke a registered tool. The only path by which a number may be produced.\n\n    Returns the tool's bound result, which always carries a `transcript_id`.\n    Anything that reaches a user without one is, by the platform's invariant,\n    not renderable.\n    \"\"\"\n    tool = TOOLS.get(name)\n    if tool is None:\n        return {\"error\": \"unknown_tool\", \"message\": f\"No tool named {name!r}.\",\n                \"available\": sorted(TOOLS)}\n\n    if grade is not None and name not in tools_for_grade(grade):\n        return {\"error\": \"grade_restricted\",\n                \"message\": (f\"'{name}' is a Grade {tool.grades} tool and this workspace is Grade \"\n                            f\"{grade}. That is not a permissions problem to route around -- the \"\n                            f\"tool would produce an answer this student has not yet been given the \"\n                            f\"ideas to check.\"),\n                \"available\": tools_for_grade(grade)}\n\n    schema = tool.parameters\n\n    # Checked first: \"you did not say why\" is a more useful error than\n    # \"missing required: ['justification']\", and it is the one a student sees most.\n    if tool.inferential and not str(arguments.get(\"justification\", \"\")).strip():\n        return {\"error\": \"justification_required\",\n                \"message\": (\"Every inferential test needs a written reason, which is logged and \"\n                            \"shown to the teacher. Say why THIS test on THIS data.\")}\n\n    missing = [k for k in schema.get(\"required\", []) if k not in arguments]\n    if missing:\n        return {\"error\": \"missing_arguments\", \"message\": f\"Missing required: {missing}.\",\n                \"schema\": schema}\n\n    known = set(schema.get(\"properties\", {}))\n    extra = [k for k in arguments if k not in known]\n    if extra:\n        return {\"error\": \"unknown_arguments\",\n                \"message\": f\"Not parameters of {name}: {extra}.\", \"schema\": schema}\n\n    try:\n        result = tool.fn(**arguments)\n    except Exception as exc:\n        return {\"error\": \"execution_failed\", \"message\": f\"{type(exc).__name__}: {exc}\",\n                \"tool\": name}\n\n    result[\"tool\"] = name\n    result[\"tool_category\"] = tool.category\n    result[\"curriculum\"] = tool.curriculum\n    return result\n",
  "phagequest_engine/resampling.py": "\"\"\"Resampling: the platform's default route for small, weird data.\n\nSpec section 04, row 4:\n\n    \"Class datasets are n=4 to n=30 and routinely non-normal. Resampling is\n    *also* more teachable than a t-distribution: shuffle the labels ten thousand\n    times and see how often chance beats you. A Grade 8 student can understand\n    that. They cannot understand a t-table.\"\n\nSo these are not the advanced menu. `shuffle_test` is what a Grade 7 sees when\nthey press \"test it\", and it returns the null distribution itself so the\nfrontend can draw the histogram with the observed value marked on it. The\npicture is the explanation.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Callable, Dict, List, Optional, Sequence\n\nimport numpy as np\nfrom scipy import stats\n\nfrom .transcript import bound\n\n__all__ = [\"bootstrap_ci\", \"shuffle_test\", \"monte_carlo_p\", \"jackknife\"]\n\n_STATS: Dict[str, Callable[[np.ndarray], float]] = {\n    \"mean\": np.mean,\n    \"median\": np.median,\n    \"sd\": lambda a: float(np.std(a, ddof=1)),\n    \"max\": np.max,\n    \"min\": np.min,\n    \"iqr\": lambda a: float(np.percentile(a, 75) - np.percentile(a, 25)),\n}\n\n\n@bound(\"bootstrap_ci\", data_args=(\"values\",))\ndef bootstrap_ci(values: Sequence[float], statistic: str = \"mean\", confidence: float = 0.95,\n                 n_resamples: int = 9999, method: str = \"BCa\",\n                 seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"Bias-corrected accelerated bootstrap interval on any simple statistic.\n\n    BCa rather than percentile: at n=8 the percentile interval is visibly\n    off-centre for a skewed statistic, and a class dataset is usually skewed.\n    \"\"\"\n    a = np.asarray(values, dtype=float).ravel()\n    a = a[np.isfinite(a)]\n    if a.size < 3:\n        return {\"refused\": True, \"reason\": f\"n={a.size}; need at least 3 values to resample.\"}\n    fn = _STATS.get(statistic)\n    if fn is None:\n        return {\"refused\": True, \"reason\": f\"Unknown statistic {statistic!r}. \"\n                                           f\"Choose from {sorted(_STATS)}.\"}\n    rng = np.random.default_rng(seed)\n    res = stats.bootstrap((a,), fn, confidence_level=confidence, n_resamples=n_resamples,\n                          method=method if a.size > 3 else \"percentile\",\n                          random_state=rng, vectorized=False)\n    point = float(fn(a))\n    lo, hi = float(res.confidence_interval.low), float(res.confidence_interval.high)\n    return {\n        \"statistic\": statistic, \"point_estimate\": point,\n        \"ci\": [lo, hi], \"confidence\": confidence,\n        \"standard_error\": float(res.standard_error),\n        \"method\": method if a.size > 3 else \"percentile\",\n        \"n\": int(a.size), \"n_resamples\": int(n_resamples),\n        \"distribution_sample\": [float(x) for x in\n                                rng.choice(res.bootstrap_distribution.ravel(),\n                                           size=min(2000, res.bootstrap_distribution.size),\n                                           replace=False)],\n        \"plain_language\": (\n            f\"The {statistic} of your {a.size} measurements is {point:.4g}. If you repeated the \"\n            f\"whole experiment many times, the {statistic} would land between {lo:.4g} and {hi:.4g} \"\n            f\"about {confidence * 100:.0f}% of the time. That width IS your uncertainty -- report it \"\n            f\"instead of the single number.\"),\n    }\n\n\n@bound(\"shuffle_test\", data_args=(\"group_a\", \"group_b\"))\ndef shuffle_test(group_a: Sequence[float], group_b: Sequence[float],\n                 statistic: str = \"mean_difference\", alternative: str = \"two-sided\",\n                 n_shuffles: int = 9999, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"The Grade 7 test: shuffle the labels and see how often chance wins.\n\n    Returns the null distribution so the frontend can draw it. The p-value is\n    \"how many of the shuffled worlds beat the real one\", which is a sentence a\n    12-year-old can check by counting dots on the histogram.\n    \"\"\"\n    a = np.asarray(group_a, dtype=float).ravel()\n    b = np.asarray(group_b, dtype=float).ravel()\n    a, b = a[np.isfinite(a)], b[np.isfinite(b)]\n    if a.size < 2 or b.size < 2:\n        return {\"refused\": True, \"reason\": \"Need at least 2 measurements in each group.\"}\n\n    fns = {\n        \"mean_difference\": lambda x, y: float(np.mean(x) - np.mean(y)),\n        \"median_difference\": lambda x, y: float(np.median(x) - np.median(y)),\n        \"ratio_of_means\": lambda x, y: float(np.mean(x) / np.mean(y)) if np.mean(y) else np.nan,\n    }\n    fn = fns.get(statistic)\n    if fn is None:\n        return {\"refused\": True, \"reason\": f\"Unknown statistic {statistic!r}.\"}\n\n    observed = fn(a, b)\n    pooled = np.concatenate([a, b])\n    n_a = a.size\n    rng = np.random.default_rng(seed)\n    null = np.empty(n_shuffles)\n    for i in range(n_shuffles):\n        perm = rng.permutation(pooled)\n        null[i] = fn(perm[:n_a], perm[n_a:])\n\n    if alternative == \"greater\":\n        count = int(np.sum(null >= observed))\n    elif alternative == \"less\":\n        count = int(np.sum(null <= observed))\n    else:\n        centre = 1.0 if statistic == \"ratio_of_means\" else 0.0\n        count = int(np.sum(np.abs(null - centre) >= abs(observed - centre)))\n    # +1 smoothing: a p-value of exactly 0 is a lie about resolution.\n    p = (count + 1) / (n_shuffles + 1)\n\n    return {\n        \"statistic_name\": statistic, \"observed\": observed,\n        \"p_value\": float(p), \"n_shuffles\": int(n_shuffles),\n        \"n_at_least_as_extreme\": count, \"alternative\": alternative,\n        \"null_mean\": float(null.mean()), \"null_sd\": float(null.std(ddof=1)),\n        \"null_distribution\": [float(x) for x in\n                              rng.choice(null, size=min(2000, n_shuffles), replace=False)],\n        \"null_quantiles\": {q: float(np.percentile(null, q)) for q in (2.5, 25, 50, 75, 97.5)},\n        \"effect_size\": float(2 * np.mean((a[:, None] - b[None, :]) > 0) - 1),\n        \"effect_size_type\": \"rank_biserial\",\n        \"n_per_group\": {\"a\": int(n_a), \"b\": int(b.size)},\n        \"plain_language\": (\n            f\"Your two groups differ by {observed:.4g}. We then mixed all {pooled.size} measurements \"\n            f\"together and split them into two random groups {n_shuffles:,} times. \"\n            f\"{count:,} of those random splits produced a difference at least as big as yours. \"\n            f\"That is p = {p:.4g}. \"\n            + (\"Chance rarely does this well, so the difference is probably real.\"\n               if p < 0.05 else\n               \"Chance does this often enough that your result is not surprising.\")),\n        \"resolution_note\": (f\"The smallest p-value {n_shuffles:,} shuffles can produce is \"\n                            f\"{1 / (n_shuffles + 1):.5f}. A p of exactly 0 is never reported.\"),\n    }\n\n\n@bound(\"monte_carlo_p\", data_args=(\"values\",))\ndef monte_carlo_p(values: Sequence[float], null_distribution: str = \"normal\",\n                  n_resamples: int = 9999, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"Monte Carlo goodness-of-fit against a named null.\"\"\"\n    a = np.asarray(values, dtype=float).ravel()\n    a = a[np.isfinite(a)]\n    if a.size < 5:\n        return {\"refused\": True, \"reason\": f\"n={a.size}; need at least 5.\"}\n    rvs = {\"normal\": lambda size: stats.norm.rvs(loc=a.mean(), scale=a.std(ddof=1), size=size,\n                                                 random_state=np.random.default_rng(seed)),\n           \"poisson\": lambda size: stats.poisson.rvs(mu=max(1e-9, a.mean()), size=size,\n                                                     random_state=np.random.default_rng(seed)),\n           \"uniform\": lambda size: stats.uniform.rvs(loc=a.min(), scale=float(np.ptp(a)), size=size,\n                                                     random_state=np.random.default_rng(seed))}\n    if null_distribution not in rvs:\n        return {\"refused\": True, \"reason\": f\"Unknown null {null_distribution!r}.\"}\n    res = stats.monte_carlo_test(a, rvs[null_distribution], stats.skew,\n                                 n_resamples=n_resamples, alternative=\"two-sided\")\n    return {\n        \"null_distribution\": null_distribution, \"statistic\": float(res.statistic),\n        \"p_value\": float(res.pvalue), \"n\": int(a.size),\n        \"plain_language\": (\n            f\"Compared with {n_resamples:,} datasets simulated from a {null_distribution} \"\n            f\"distribution, your data's shape is \"\n            f\"{'unusual' if res.pvalue < 0.05 else 'unremarkable'} (p = {float(res.pvalue):.4g}).\"),\n    }\n\n\n@bound(\"jackknife\", data_args=(\"values\",))\ndef jackknife(values: Sequence[float], statistic: str = \"mean\") -> Dict[str, Any]:\n    \"\"\"Leave-one-out influence. Names the observation that is carrying the result.\n\n    Used directly by the stability check, and exposed on its own because\n    \"which measurement is doing all the work?\" is a question a Grade 8 can\n    answer from a bar chart.\n    \"\"\"\n    a = np.asarray(values, dtype=float).ravel()\n    a = a[np.isfinite(a)]\n    fn = _STATS.get(statistic)\n    if fn is None or a.size < 3:\n        return {\"refused\": True, \"reason\": \"Need at least 3 values and a known statistic.\"}\n    full = float(fn(a))\n    loo = np.array([float(fn(np.delete(a, i))) for i in range(a.size)])\n    infl = loo - full\n    worst = int(np.argmax(np.abs(infl)))\n    return {\n        \"full_sample\": full, \"leave_one_out\": [float(x) for x in loo],\n        \"influence\": [float(x) for x in infl],\n        \"most_influential_index\": worst,\n        \"most_influential_value\": float(a[worst]),\n        \"influence_of_worst\": float(infl[worst]),\n        \"n\": int(a.size),\n        \"plain_language\": (\n            f\"Removing the measurement {a[worst]:.4g} moves the {statistic} from {full:.4g} to \"\n            f\"{loo[worst]:.4g}. \"\n            + (\"That one point is carrying a large share of the result -- check whether it is a \"\n               \"real measurement or a mistake, and say which in your report.\"\n               if abs(infl[worst]) > 0.2 * max(1e-12, abs(full)) else\n               \"No single measurement dominates, which is a good sign.\")),\n    }\n",
  "phagequest_engine/sequence.py": "\"\"\"Sequence handling, Tier-0 (spec section 03.2).\n\n    \"Biopython is *in Pyodide* -- a student can read a FASTA, translate it and\n    check their codon-wheel answer from G9-L7 entirely client-side.\"\n\nTrue, and this module still does not import it. Biopython in Pyodide is a\nmulti-megabyte download on a metered Indian school line (spec section 02,\nconstraint 2) for four functions a school actually needs. FASTA parsing,\ntranslation, ORF finding and GC content are eighty lines of standard library,\nso the first lesson loads in seconds instead of minutes. Biopython stays\navailable in Tier 1 for the things that genuinely need it.\n\nThe translation table is the full NCBI table 11 (bacterial/phage), because\nphage genomes really do use GTG and TTG starts and a student who annotates one\nby hand will meet them.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\nfrom typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple\n\nfrom .transcript import bound\n\n__all__ = [\"parse_fasta\", \"translate\", \"find_orfs\", \"gc_content\", \"reverse_complement\",\n           \"codon_usage\", \"CODON_TABLE\"]\n\n_BASES = set(\"ACGTU\")\n_COMPLEMENT = str.maketrans(\"ACGTUNacgtun\", \"TGCAANtgcaan\")\n\nCODON_TABLE: Dict[str, str] = {}\n_B = \"TCAG\"\n_AA = (\"FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG\")\nfor _i, _a in enumerate(_AA):\n    CODON_TABLE[\"\".join((_B[_i // 16], _B[(_i // 4) % 4], _B[_i % 4]))] = _a\n\n# NCBI table 11: bacterial, archaeal and plant plastid code. Alternative starts.\nSTART_CODONS = {\"ATG\", \"GTG\", \"TTG\", \"ATT\", \"CTG\"}\nSTOP_CODONS = {\"TAA\", \"TAG\", \"TGA\"}\n\nAA_NAMES = {\n    \"A\": \"Alanine\", \"R\": \"Arginine\", \"N\": \"Asparagine\", \"D\": \"Aspartate\", \"C\": \"Cysteine\",\n    \"Q\": \"Glutamine\", \"E\": \"Glutamate\", \"G\": \"Glycine\", \"H\": \"Histidine\", \"I\": \"Isoleucine\",\n    \"L\": \"Leucine\", \"K\": \"Lysine\", \"M\": \"Methionine\", \"F\": \"Phenylalanine\", \"P\": \"Proline\",\n    \"S\": \"Serine\", \"T\": \"Threonine\", \"W\": \"Tryptophan\", \"Y\": \"Tyrosine\", \"V\": \"Valine\",\n    \"*\": \"STOP\",\n}\n\n\ndef _clean(seq: str) -> str:\n    return \"\".join(c for c in str(seq).upper() if c in _BASES).replace(\"U\", \"T\")\n\n\n@bound(\"parse_fasta\", data_args=(\"text\",))\ndef parse_fasta(text: str, max_records: int = 500) -> Dict[str, Any]:\n    \"\"\"Read a FASTA file. Reports what it skipped rather than silently dropping it.\"\"\"\n    records: List[Dict[str, Any]] = []\n    name, parts = None, []\n    skipped = 0\n\n    def flush():\n        nonlocal name, parts, skipped\n        if name is None:\n            return\n        raw = \"\".join(parts)\n        seq = _clean(raw)\n        bad = len(re.sub(r\"\\s\", \"\", raw)) - len(seq)\n        records.append({\n            \"id\": name.split()[0], \"description\": name,\n            \"sequence\": seq, \"length\": len(seq),\n            \"non_standard_bases\": bad,\n        })\n        name, parts = None, []\n\n    for line in str(text).splitlines():\n        line = line.strip()\n        if not line:\n            continue\n        if line.startswith(\">\"):\n            flush()\n            if len(records) >= max_records:\n                skipped += 1\n                name = None\n                continue\n            name = line[1:].strip() or f\"record_{len(records) + 1}\"\n        elif name is not None:\n            parts.append(line)\n    flush()\n\n    if not records:\n        return {\"refused\": True,\n                \"reason\": (\"No FASTA records found. A FASTA file has a '>' line naming each \"\n                           \"sequence, then the sequence itself on the lines below it.\")}\n\n    total = sum(r[\"length\"] for r in records)\n    odd = [r for r in records if r[\"non_standard_bases\"] > 0]\n    return {\n        \"records\": records, \"n_records\": len(records), \"total_length\": total,\n        \"skipped_over_limit\": skipped,\n        \"notes\": ([f\"{len(odd)} record(s) contained characters that are not A, C, G, T or U \"\n                   f\"(often N for 'unknown base'). Those characters were left out of the \"\n                   f\"sequence, and the lengths above reflect that.\"] if odd else []),\n        \"plain_language\": (\n            f\"Read {len(records)} sequence{'s' if len(records) != 1 else ''}, \"\n            f\"{total:,} bases in total\"\n            + (f\". Longest: {max(records, key=lambda r: r['length'])['id']} at \"\n               f\"{max(r['length'] for r in records):,} bases.\" if records else \".\")),\n        \"p_value\": None,\n    }\n\n\n@bound(\"reverse_complement\", data_args=(\"sequence\",))\ndef reverse_complement(sequence: str) -> Dict[str, Any]:\n    seq = _clean(sequence)\n    return {\"sequence\": seq.translate(_COMPLEMENT)[::-1], \"length\": len(seq), \"p_value\": None}\n\n\n@bound(\"gc_content\", data_args=(\"sequence\",))\ndef gc_content(sequence: str, window: int = 0) -> Dict[str, Any]:\n    \"\"\"GC content, optionally as a sliding window.\n\n    G8-L11 is about DNA stability: G-C pairs have three hydrogen bonds, A-T have\n    two, so a GC-rich genome holds together at a higher temperature. The sliding\n    window makes that visible along a real genome.\n    \"\"\"\n    seq = _clean(sequence)\n    if not seq:\n        return {\"refused\": True, \"reason\": \"No usable bases in the sequence.\"}\n    gc = sum(seq.count(b) for b in \"GC\")\n    out: Dict[str, Any] = {\n        \"gc_content\": gc / len(seq), \"length\": len(seq),\n        \"counts\": {b: seq.count(b) for b in \"ACGT\"},\n        \"melting_temperature_estimate_C\": (\n            float(64.9 + 41 * (gc - 16.4) / len(seq)) if len(seq) > 13 else\n            float(2 * (seq.count(\"A\") + seq.count(\"T\")) + 4 * gc)),\n        \"teaches\": (\"G pairs with C using three hydrogen bonds; A pairs with T using two. More GC \"\n                    \"means a stiffer, more heat-stable molecule -- which is why the melting \"\n                    \"temperature above moves with GC and not with length alone.\"),\n        \"p_value\": None,\n    }\n    if window and window >= 10:\n        w = int(min(window, len(seq)))\n        step = max(1, w // 4)\n        xs, ys = [], []\n        for i in range(0, len(seq) - w + 1, step):\n            sub = seq[i:i + w]\n            xs.append(i + w // 2)\n            ys.append(sum(sub.count(b) for b in \"GC\") / w)\n        out[\"window\"] = {\"size\": w, \"step\": step, \"positions\": xs, \"gc\": ys}\n        if ys:\n            out[\"window\"][\"most_gc_rich_position\"] = int(xs[int(max(range(len(ys)), key=ys.__getitem__))])\n    tail = \".\"\n    win = out.get(\"window\")\n    if win and win[\"gc\"]:\n        tail = (f\", ranging {min(win['gc']):.1%} to {max(win['gc']):.1%} across the genome in \"\n                f\"{win['size']}-base windows.\")\n    out[\"plain_language\"] = f\"{len(seq):,} bases, {out['gc_content']:.1%} G+C{tail}\"\n    return out\n\n\n@bound(\"translate\", data_args=(\"sequence\",))\ndef translate(sequence: str, frame: int = 1, to_stop: bool = False) -> Dict[str, Any]:\n    \"\"\"Translate DNA to protein, and show the working.\n\n    G9-L7 has students do exactly this by hand with a codon wheel. The point of\n    this function is not to replace that -- it is to let them CHECK it, codon by\n    codon, so a mismatch tells them where they went wrong rather than just that\n    they did.\n    \"\"\"\n    seq = _clean(sequence)\n    if frame < 0:\n        seq = seq.translate(_COMPLEMENT)[::-1]\n        offset = -frame - 1\n    else:\n        offset = frame - 1\n    if offset < 0 or offset > 2:\n        return {\"refused\": True, \"reason\": \"Frame must be 1, 2, 3, -1, -2 or -3.\"}\n    seq = seq[offset:]\n    codons = [seq[i:i + 3] for i in range(0, len(seq) - len(seq) % 3, 3)]\n\n    protein, detail = [], []\n    for i, c in enumerate(codons):\n        aa = CODON_TABLE.get(c, \"X\")\n        if to_stop and aa == \"*\":\n            detail.append({\"position\": i + 1, \"codon\": c, \"amino_acid\": aa,\n                           \"name\": AA_NAMES.get(aa, \"unknown\")})\n            break\n        protein.append(aa)\n        if len(detail) < 200:\n            detail.append({\"position\": i + 1, \"codon\": c, \"amino_acid\": aa,\n                           \"name\": AA_NAMES.get(aa, \"unknown\")})\n\n    p = \"\".join(protein)\n    return {\n        \"protein\": p, \"length\": len(p), \"frame\": frame,\n        \"n_codons\": len(codons),\n        \"codon_detail\": detail,\n        \"trailing_bases\": len(seq) % 3,\n        \"stops\": p.count(\"*\"),\n        \"starts_with_start_codon\": bool(codons and codons[0] in START_CODONS),\n        \"note\": (\"Bacteria and their phage use NCBI translation table 11, which allows GTG and TTG \"\n                 \"as start codons as well as ATG. All three are read as Methionine when they start \"\n                 \"a gene, which is why a real phage gene can begin with a codon that means Valine \"\n                 \"in the middle of one.\"),\n        \"plain_language\": (\n            f\"Frame {frame}: {len(codons)} codons give a {len(p)}-residue protein with \"\n            f\"{p.count('*')} stop{'s' if p.count('*') != 1 else ''}. \"\n            + (f\"The first {min(6, len(codons))} codons are \"\n               + \", \".join(f\"{d['codon']}->{d['amino_acid']}\" for d in detail[:6]) + \".\"\n               if detail else \"\")\n            + (f\" {len(seq) % 3} base(s) left over at the end -- a reading frame needs a multiple \"\n               f\"of three, so those cannot be read.\" if len(seq) % 3 else \"\")),\n        \"p_value\": None,\n    }\n\n\n@bound(\"find_orfs\", data_args=(\"sequence\",))\ndef find_orfs(sequence: str, min_length_aa: int = 30, all_frames: bool = True,\n              require_start: bool = True) -> Dict[str, Any]:\n    \"\"\"Find open reading frames -- a gene caller a student can read in full.\n\n    Pharokka wraps PHANOTATE and Prodigal-gv and is Tier 2 (spec section 07),\n    and it should be: real gene calling is far more than this. But the spec's\n    pedagogy is that *where two callers disagree is where a student learns\n    annotation is a judgement, not a lookup*. To have that conversation a\n    student first needs to see what the simplest possible caller does, and\n    where it obviously fails.\n\n    So this is the naive longest-ORF caller, and it says so: it over-calls in\n    GC-rich genomes, misses short genes, and cannot see overlapping genes.\n    \"\"\"\n    seq = _clean(sequence)\n    if len(seq) < 60:\n        return {\"refused\": True, \"reason\": \"Sequence is too short to contain a gene.\"}\n\n    frames = [1, 2, 3, -1, -2, -3] if all_frames else [1, 2, 3]\n    orfs = []\n    for fr in frames:\n        s = seq.translate(_COMPLEMENT)[::-1] if fr < 0 else seq\n        off = abs(fr) - 1\n        body = s[off:]\n        n_cod = len(body) // 3\n        codons = [body[i * 3:i * 3 + 3] for i in range(n_cod)]\n\n        start_idx = None\n        for i, c in enumerate(codons):\n            if start_idx is None and (c in START_CODONS if require_start else True):\n                start_idx = i\n            elif c in STOP_CODONS and start_idx is not None:\n                aa_len = i - start_idx\n                if aa_len >= min_length_aa:\n                    nt_start = off + start_idx * 3\n                    nt_end = off + (i + 1) * 3\n                    orfs.append({\n                        \"frame\": fr,\n                        \"start\": (nt_start if fr > 0 else len(seq) - nt_end) + 1,\n                        \"end\": (nt_end if fr > 0 else len(seq) - nt_start),\n                        \"strand\": \"+\" if fr > 0 else \"-\",\n                        \"length_nt\": nt_end - nt_start,\n                        \"length_aa\": aa_len,\n                        \"start_codon\": codons[start_idx],\n                        \"stop_codon\": c,\n                        \"protein\": \"\".join(CODON_TABLE.get(x, \"X\")\n                                           for x in codons[start_idx:i]),\n                    })\n                start_idx = None\n\n    orfs.sort(key=lambda o: -o[\"length_aa\"])\n    # Coding density is the fraction of the genome COVERED by at least one ORF,\n    # not the sum of ORF lengths: six reading frames overlap heavily, and summing\n    # them gives nonsense like 160% of a genome being coding.\n    covered = bytearray(len(seq))\n    for o in orfs:\n        covered[max(0, o[\"start\"] - 1):min(len(seq), o[\"end\"])] = b\"\\x01\" * (\n            min(len(seq), o[\"end\"]) - max(0, o[\"start\"] - 1))\n    density = sum(covered) / len(seq)\n\n    return {\n        \"orfs\": orfs[:300], \"n_orfs\": len(orfs),\n        \"genome_length\": len(seq),\n        \"coding_density_estimate\": float(density),\n        \"longest\": orfs[0] if orfs else None,\n        \"parameters\": {\"min_length_aa\": int(min_length_aa), \"all_frames\": all_frames,\n                       \"require_start\": require_start},\n        \"limitations\": [\n            \"This is the simplest possible gene caller: longest open stretch between a start and a \"\n            \"stop. Real callers (PHANOTATE, Prodigal) also use codon statistics, ribosome binding \"\n            \"sites and gene-length priors.\",\n            \"It over-calls in GC-rich sequence, where stop codons are rarer by chance alone, so \"\n            \"long open stretches appear without any gene being there.\",\n            \"It cannot find overlapping genes, which phage use constantly to pack a genome.\",\n            \"Change min_length_aa and the answer changes. Try it: that sensitivity is the point.\",\n        ],\n        \"teaches\": (\n            \"Compare this caller's answer to a real one and they will disagree, most often about \"\n            \"exactly where a gene STARTS -- the stop is unambiguous, the start is a judgement. \"\n            \"Those disagreements are where annotation actually happens.\"),\n        \"plain_language\": (\n            f\"Found {len(orfs)} open reading frames of at least {min_length_aa} amino acids in \"\n            f\"{len(seq):,} bases, covering {density:.0%} of the genome. \"\n            + (f\"The longest is {orfs[0]['length_aa']} amino acids on the {orfs[0]['strand']} \"\n               f\"strand at position {orfs[0]['start']:,}. \" if orfs else \"\")\n            + (f\"A coding density of {density:.0%} is low even for this crude caller -- real phage \"\n               f\"genomes are usually over 85% coding, so genes are being missed.\"\n               if density < 0.6 else\n               f\"Do not read {density:.0%} as confirmation that this genome is gene-dense: \"\n               f\"searching six frames for any stretch without a stop codon reaches 80-90% \"\n               f\"coverage on RANDOM sequence too. Coding density only means something once a \"\n               f\"caller that uses codon statistics -- Prodigal or PHANOTATE -- has had a look.\")),\n        \"p_value\": None,\n    }\n\n\n@bound(\"codon_usage\", data_args=(\"sequence\",))\ndef codon_usage(sequence: str, frame: int = 1) -> Dict[str, Any]:\n    \"\"\"Codon usage bias -- which synonym this genome prefers.\n\n    The bridge between G9-L7's codon wheel and the Grade 11 question of why a\n    phage's codon usage looks like its host's.\n    \"\"\"\n    seq = _clean(sequence)\n    if frame < 0:\n        seq = seq.translate(_COMPLEMENT)[::-1]\n    off = abs(frame) - 1\n    body = seq[off:]\n    codons = [body[i:i + 3] for i in range(0, len(body) - len(body) % 3, 3)]\n    if not codons:\n        return {\"refused\": True, \"reason\": \"No complete codons.\"}\n\n    counts: Dict[str, int] = {}\n    for c in codons:\n        if c in CODON_TABLE:\n            counts[c] = counts.get(c, 0) + 1\n\n    by_aa: Dict[str, Dict[str, int]] = {}\n    for c, n in counts.items():\n        by_aa.setdefault(CODON_TABLE[c], {})[c] = n\n\n    rscu: Dict[str, float] = {}\n    for aa, group in by_aa.items():\n        total = sum(group.values())\n        k = len(group)\n        for c, n in group.items():\n            rscu[c] = float(n * k / total) if total else 0.0\n\n    biased = sorted(rscu.items(), key=lambda kv: -kv[1])[:5]\n    return {\n        \"counts\": counts, \"total_codons\": len(codons),\n        \"by_amino_acid\": {aa: {\"codons\": g, \"total\": sum(g.values()),\n                               \"n_synonyms\": len(g)} for aa, g in by_aa.items()},\n        \"rscu\": rscu,\n        \"most_preferred\": [{\"codon\": c, \"amino_acid\": CODON_TABLE[c], \"rscu\": v} for c, v in biased],\n        \"note\": (\"RSCU (relative synonymous codon usage) is the observed count divided by what you \"\n                 \"would expect if every synonym for that amino acid were used equally. 1.0 means no \"\n                 \"preference; above 1 means this genome favours that spelling.\"),\n        \"plain_language\": (\n            f\"{len(codons):,} codons. The strongest preference is {biased[0][0]} for \"\n            f\"{AA_NAMES.get(CODON_TABLE[biased[0][0]], '?')} (RSCU {biased[0][1]:.2f}, where 1.00 \"\n            f\"would mean no preference). A phage often shares its host's preferences, because it \"\n            f\"uses the host's machinery to translate.\"\n            if biased else \"No codon preference could be computed.\"),\n        \"p_value\": None,\n    }\n",
  "phagequest_engine/simulation/__init__.py": "\"\"\"Host-phage interaction simulation (spec section 03.3).\n\nThe spec's key finding: there is no maintained, general-purpose phage-dynamics\npackage anywhere, so this block is ours to define. Everything here runs in\nPyodide, which means the simulation block costs nothing per student.\n\"\"\"\nfrom .ode import MODELS, PARAM_META, simulate, parameter_sweep, one_step_growth\nfrom .stochastic import gillespie_lytic, extinction_probability, poisson_plaques\nfrom .plaque import plaque_growth, STATES\nfrom .labmath import dilution_series, pfu_per_ml, titre_from_plates, moi\n\n__all__ = [\n    \"MODELS\", \"PARAM_META\", \"simulate\", \"parameter_sweep\", \"one_step_growth\",\n    \"gillespie_lytic\", \"extinction_probability\", \"poisson_plaques\",\n    \"plaque_growth\", \"STATES\",\n    \"dilution_series\", \"pfu_per_ml\", \"titre_from_plates\", \"moi\",\n]\n",
  "phagequest_engine/simulation/labmath.py": "\"\"\"Wet-lab arithmetic (spec section 03.3, last row).\n\n    \"Five lines of our own code, bound directly to G5-L6's 1:10 dilution chain\n    so the student sees the same maths they did with coloured water, now\n    counting plaques.\"\n\nIt is more than five lines because the honest version carries the counting\nuncertainty with it. A titre from a single plate with 7 plaques is not\n\"7 x 10^6 PFU/mL\"; it is a number with a 95% interval running from about\n3 x 10^6 to 14 x 10^6, and that interval is the lesson.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Dict, List, Optional, Sequence\n\nimport numpy as np\nfrom scipy import stats\n\nfrom ..transcript import bound\n\n__all__ = [\"dilution_series\", \"pfu_per_ml\", \"moi\", \"titre_from_plates\"]\n\n\n@bound(\"dilution_series\")\ndef dilution_series(start_concentration: float = 1e9, fold: float = 10.0,\n                    steps: int = 8, volume_transferred: float = 0.1,\n                    volume_diluent: float = 0.9) -> Dict[str, Any]:\n    \"\"\"The 1:10 chain from G5-L6, with the powers of ten made explicit.\n\n    A Grade 5 sees the coloured-water version of exactly this table. The same\n    function, unchanged, is what a Grade 9 uses to work out which tube to plate.\n    \"\"\"\n    if fold <= 1:\n        return {\"refused\": True, \"reason\": \"The dilution fold must be greater than 1.\"}\n    actual_fold = (volume_transferred + volume_diluent) / max(volume_transferred, 1e-12)\n    rows = []\n    c = float(start_concentration)\n    for i in range(int(steps) + 1):\n        rows.append({\n            \"tube\": i,\n            \"dilution_factor\": float(actual_fold ** i),\n            \"dilution_label\": f\"10^-{i}\" if abs(actual_fold - 10) < 1e-9 else f\"1:{actual_fold ** i:.0f}\",\n            \"concentration\": c,\n            \"log10_concentration\": float(np.log10(c)) if c > 0 else float(\"-inf\"),\n            \"expected_plaques_from_100uL\": float(c * 0.1),\n            \"countable\": bool(30 <= c * 0.1 <= 300),\n        })\n        c /= actual_fold\n\n    countable = [r for r in rows if r[\"countable\"]]\n    return {\n        \"rows\": rows,\n        \"requested_fold\": float(fold), \"actual_fold\": float(actual_fold),\n        \"volumes\": {\"transferred_mL\": volume_transferred, \"diluent_mL\": volume_diluent},\n        \"countable_tubes\": [r[\"tube\"] for r in countable],\n        \"fold_mismatch\": (\n            f\"You asked for a 1:{fold:g} dilution but transferring {volume_transferred} mL into \"\n            f\"{volume_diluent} mL gives 1:{actual_fold:.3g}. The total volume is what divides, not \"\n            f\"the diluent. This is the single most common dilution mistake.\"\n            if abs(actual_fold - fold) > 1e-6 else None),\n        \"plain_language\": (\n            f\"Each step divides by {actual_fold:g}, so tube {steps} is {actual_fold ** steps:.3g} \"\n            f\"times weaker than tube 0. \"\n            + (f\"Plate 100 uL from tube {countable[0]['tube']}\"\n               + (f\" or {countable[-1]['tube']}\" if len(countable) > 1 else \"\")\n               + \" to land in the countable 30-300 plaque range.\"\n               if countable else\n               \"None of these tubes lands in the countable 30-300 range -- extend the series.\")),\n        \"p_value\": None,\n    }\n\n\n@bound(\"pfu_per_ml\")\ndef pfu_per_ml(plaque_count: int, dilution_factor: float, volume_plated_mL: float = 0.1\n               ) -> Dict[str, Any]:\n    \"\"\"Titre from one plate, with its Poisson counting interval.\n\n    The interval is the point. A plate with 7 plaques and a plate with 70 give\n    titres differing by a factor of ten, but the 7-plaque titre is uncertain by\n    a factor of two and the 70-plaque one by about 25%. That is why the\n    countable range exists, and a student who has seen this table never asks\n    \"why can't I just use the plate I have?\" again.\n    \"\"\"\n    n = int(plaque_count)\n    if n < 0 or dilution_factor <= 0 or volume_plated_mL <= 0:\n        return {\"refused\": True, \"reason\": \"Counts must be >= 0, and factors and volumes > 0.\"}\n\n    titre = n * dilution_factor / volume_plated_mL\n    # Exact Poisson interval on the count (Garwood), then propagated.\n    lo_n = 0.0 if n == 0 else float(stats.chi2.ppf(0.025, 2 * n) / 2)\n    hi_n = float(stats.chi2.ppf(0.975, 2 * (n + 1)) / 2)\n    lo = lo_n * dilution_factor / volume_plated_mL\n    hi = hi_n * dilution_factor / volume_plated_mL\n\n    if n == 0:\n        reliability = (\"A count of zero does not give a titre. It gives an upper limit: the true \"\n                       \"concentration is below the top of this interval. Report it that way.\")\n        grade = \"upper limit only\"\n    elif n < 30:\n        reliability = (f\"{n} plaques is below the countable range of 30-300. The interval is \"\n                       f\"{hi / max(lo, 1e-12):.1f}-fold wide -- plate a less dilute tube.\")\n        grade = \"too few\"\n    elif n > 300:\n        reliability = (f\"{n} plaques is above 300; plaques overlap at that density and you have \"\n                       f\"almost certainly undercounted. Plate a more dilute tube.\")\n        grade = \"too many\"\n    else:\n        reliability = (f\"{n} plaques is in the countable range, and the interval is only \"\n                       f\"{hi / max(lo, 1e-12):.2f}-fold wide. This is a usable titre.\")\n        grade = \"good\"\n\n    return {\n        \"plaque_count\": n, \"dilution_factor\": float(dilution_factor),\n        \"volume_plated_mL\": float(volume_plated_mL),\n        \"titre_pfu_per_mL\": float(titre),\n        \"ci\": [float(lo), float(hi)],\n        \"log10_titre\": float(np.log10(titre)) if titre > 0 else None,\n        \"relative_uncertainty\": float(1 / np.sqrt(n)) if n > 0 else None,\n        \"count_quality\": grade, \"reliability_note\": reliability,\n        \"formula\": \"titre = plaques x dilution factor / volume plated (mL)\",\n        \"plain_language\": (\n            f\"{n} plaques from {volume_plated_mL} mL of a 1:{dilution_factor:g} dilution gives \"\n            f\"{titre:.3g} PFU/mL (95% CI {lo:.3g} to {hi:.3g}). \" + reliability),\n        \"p_value\": None,\n    }\n\n\n@bound(\"titre_from_plates\", data_args=(\"plaque_counts\",))\ndef titre_from_plates(plaque_counts: Sequence[int], dilution_factors: Sequence[float],\n                      volume_plated_mL: float = 0.1) -> Dict[str, Any]:\n    \"\"\"Pool several plates into one titre -- the right way to do it.\n\n    Averaging the per-plate titres is wrong: it weights a 5-plaque plate the\n    same as a 200-plaque one. The correct estimate pools the counts against the\n    total volume-equivalent plated, which is maximum likelihood for a Poisson.\n    \"\"\"\n    counts = np.asarray(plaque_counts, dtype=float).ravel()\n    dils = np.asarray(dilution_factors, dtype=float).ravel()\n    if counts.size != dils.size or counts.size == 0:\n        return {\"refused\": True, \"reason\": \"Give one dilution factor per plate.\"}\n    if np.any(counts < 0) or np.any(dils <= 0):\n        return {\"refused\": True, \"reason\": \"Counts must be >= 0 and dilutions > 0.\"}\n\n    # Effective undiluted volume each plate represents.\n    veq = volume_plated_mL / dils\n    total_count = float(counts.sum())\n    total_veq = float(veq.sum())\n    titre = total_count / total_veq if total_veq > 0 else float(\"nan\")\n\n    lo_n = 0.0 if total_count == 0 else float(stats.chi2.ppf(0.025, 2 * total_count) / 2)\n    hi_n = float(stats.chi2.ppf(0.975, 2 * (total_count + 1)) / 2)\n    lo, hi = lo_n / total_veq, hi_n / total_veq\n\n    per_plate = [float(c * d / volume_plated_mL) for c, d in zip(counts, dils)]\n    naive_mean = float(np.mean(per_plate))\n\n    # Overdispersion: if the plates disagree by more than Poisson allows, the\n    # dilutions or the pipetting are the problem, not chance.\n    expected = titre * veq\n    chi2 = float(np.sum((counts - expected) ** 2 / np.maximum(expected, 1e-12)))\n    df = max(1, counts.size - 1)\n    p_consistency = float(stats.chi2.sf(chi2, df))\n\n    return {\n        \"n_plates\": int(counts.size),\n        \"plaque_counts\": counts.astype(int).tolist(),\n        \"dilution_factors\": dils.tolist(),\n        \"pooled_titre_pfu_per_mL\": float(titre),\n        \"ci\": [float(lo), float(hi)],\n        \"per_plate_titres\": per_plate,\n        \"naive_mean_of_titres\": naive_mean,\n        \"consistency_chi2\": chi2, \"consistency_df\": df, \"p_value\": p_consistency,\n        \"plates_consistent\": bool(p_consistency >= 0.05),\n        \"method_note\": (\n            \"Counts are pooled against total volume-equivalent, not averaged. Averaging per-plate \"\n            \"titres gives a 5-plaque plate the same weight as a 200-plaque one, which throws away \"\n            \"most of your information.\"),\n        \"plain_language\": (\n            f\"Pooling {counts.size} plates gives {titre:.3g} PFU/mL (95% CI {lo:.3g} to {hi:.3g}). \"\n            f\"Averaging the individual titres would have given {naive_mean:.3g} -- \"\n            + (\"close, but the pooled figure is the defensible one. \"\n               if abs(naive_mean - titre) < 0.2 * titre else \"noticeably different. \")\n            + (f\"The plates agree with each other about as well as chance allows \"\n               f\"(p = {p_consistency:.3g}).\"\n               if p_consistency >= 0.05 else\n               f\"The plates disagree more than Poisson counting explains (p = {p_consistency:.3g}). \"\n               f\"Check the dilution series and the pipetting before trusting this titre.\")),\n    }\n\n\n@bound(\"moi\")\ndef moi(phage_pfu_per_mL: float, bacteria_cfu_per_mL: float,\n        volume_mL: float = 1.0) -> Dict[str, Any]:\n    \"\"\"Multiplicity of infection, plus what Poisson says actually happens at it.\n\n    At MOI 1 a student expects every cell to be infected. Poisson says 37% of\n    them are not touched at all. That gap between the intuition and the\n    arithmetic is the whole lesson (G8-L10).\n    \"\"\"\n    if bacteria_cfu_per_mL <= 0:\n        return {\"refused\": True, \"reason\": \"Bacterial count must be greater than zero.\"}\n    m = float(phage_pfu_per_mL) / float(bacteria_cfu_per_mL)\n    p0 = float(np.exp(-m))\n    p1 = float(m * np.exp(-m))\n    p2plus = float(1 - p0 - p1)\n    return {\n        \"moi\": m,\n        \"phage_total\": float(phage_pfu_per_mL * volume_mL),\n        \"bacteria_total\": float(bacteria_cfu_per_mL * volume_mL),\n        \"fraction_uninfected\": p0,\n        \"fraction_singly_infected\": p1,\n        \"fraction_multiply_infected\": p2plus,\n        \"distribution\": {int(k): float(stats.poisson.pmf(k, m)) for k in range(0, 8)},\n        \"regime\": (\"low MOI -- most cells escape, and the phage must go through several rounds \"\n                   \"to clear the culture\" if m < 0.1 else\n                   \"high MOI -- almost every cell is hit at once, so you see one round of lysis \"\n                   \"and then nothing\" if m > 5 else\n                   \"moderate MOI\"),\n        \"plain_language\": (\n            f\"MOI {m:.3g}: {phage_pfu_per_mL:.3g} phage per mL against {bacteria_cfu_per_mL:.3g} \"\n            f\"cells per mL. Phage do not queue up politely -- they land at random, so Poisson says \"\n            f\"{p0:.1%} of cells get no phage at all, {p1:.1%} get exactly one, and {p2plus:.1%} get \"\n            f\"two or more. \"\n            + (\"Even at MOI 1, more than a third of the cells are untouched.\"\n               if 0.8 < m < 1.25 else \"\")),\n        \"p_value\": None,\n    }\n",
  "phagequest_engine/simulation/ode.py": "\"\"\"Host-phage population dynamics (spec section 03.3).\n\nThe spec's finding, which shaped this module:\n\n    \"There is NO maintained, general-purpose phage-dynamics package anywhere.\n    The field writes its own ODEs and solves them with generic solvers.\n    ...that means this block is genuinely ours to define.\"\n\nSo this is our own model library over `scipy.integrate.solve_ivp`. Every model\nis about thirty lines, runs in Pyodide, and costs nothing per student.\n\nThe one real modelling problem is the latent period. A one-step growth curve\nneeds an explicit delay between infection and lysis, which is formally a delay\ndifferential equation that `solve_ivp` cannot do. The fix, per the spec, is an\nErlang chain: I1 -> I2 -> ... -> In -> lysis, which is ordinary ODEs. It is\nalso the better teaching object, because the student can *see* the latent\nperiod as stages rather than as a hidden parameter.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any, Dict, List, Optional, Sequence\n\nimport numpy as np\nfrom scipy.integrate import solve_ivp\n\nfrom ..transcript import bound\n\n__all__ = [\"MODELS\", \"simulate\", \"parameter_sweep\", \"one_step_growth\", \"PARAM_META\"]\n\n\n# --------------------------------------------------------------------------\n# Parameter metadata. Drives the UI sliders, the units shown to a student, and\n# the plausibility warnings -- so a Grade 8 cannot silently run a phage with a\n# burst size of 100000 and believe the answer.\n# --------------------------------------------------------------------------\nPARAM_META: Dict[str, Dict[str, Any]] = {\n    \"mu\":    {\"label\": \"Bacterial growth rate\", \"unit\": \"per hour\", \"min\": 0.0, \"max\": 3.0,\n              \"typical\": [0.2, 1.5], \"default\": 0.7,\n              \"explain\": \"How fast the bacteria divide when nothing is stopping them. \"\n                         \"0.7/hour is a doubling time of about an hour.\"},\n    \"K\":     {\"label\": \"Carrying capacity\", \"unit\": \"cells/mL\", \"min\": 1e5, \"max\": 1e11,\n              \"typical\": [1e8, 1e10], \"default\": 1e9, \"log\": True,\n              \"explain\": \"How many cells the flask can hold before it runs out of food.\"},\n    \"adsorption\": {\"label\": \"Adsorption rate\", \"unit\": \"mL/(phage x hour)\", \"min\": 1e-12,\n              \"max\": 1e-6, \"typical\": [1e-10, 1e-8], \"default\": 1e-9, \"log\": True,\n              \"explain\": \"How good the phage is at finding and sticking to a cell. This is the \"\n                         \"single most important number in the whole model.\"},\n    \"burst\": {\"label\": \"Burst size\", \"unit\": \"phage per cell\", \"min\": 1, \"max\": 500,\n              \"typical\": [20, 200], \"default\": 100,\n              \"explain\": \"How many new phage come out when one infected cell bursts.\"},\n    \"latent\": {\"label\": \"Latent period\", \"unit\": \"hours\", \"min\": 0.05, \"max\": 4.0,\n              \"typical\": [0.3, 1.5], \"default\": 0.5,\n              \"explain\": \"The wait between a phage getting in and the cell bursting. During this \"\n                         \"time nothing appears to happen -- which is exactly what makes it \"\n                         \"interesting.\"},\n    \"decay\": {\"label\": \"Phage decay rate\", \"unit\": \"per hour\", \"min\": 0.0, \"max\": 1.0,\n              \"typical\": [0.0, 0.2], \"default\": 0.05,\n              \"explain\": \"Free phage falling apart on their own, with no bacteria involved.\"},\n    \"n_stages\": {\"label\": \"Latent-period stages\", \"unit\": \"compartments\", \"min\": 1, \"max\": 40,\n              \"typical\": [8, 25], \"default\": 15, \"integer\": True,\n              \"explain\": \"How finely the latent period is chopped up. With 1 stage the burst is \"\n                         \"smeared out; with 20 it is sharp. This knob IS the Erlang trick.\"},\n    \"lysogeny\": {\"label\": \"Probability of lysogeny\", \"unit\": \"fraction\", \"min\": 0.0, \"max\": 1.0,\n              \"typical\": [0.0, 0.5], \"default\": 0.1,\n              \"explain\": \"The chance an infection hides in the genome instead of killing. \"\n                         \"This is the 'does it kill, or does it hide?' question from G8-L10.\"},\n    \"induction\": {\"label\": \"Induction rate\", \"unit\": \"per hour\", \"min\": 0.0, \"max\": 0.5,\n              \"typical\": [1e-4, 0.01], \"default\": 0.001, \"log\": True,\n              \"explain\": \"How often a hidden prophage wakes up and kills its host anyway.\"},\n    \"resistance\": {\"label\": \"Resistance mutation rate\", \"unit\": \"per division\", \"min\": 0.0,\n              \"max\": 1e-4, \"typical\": [1e-9, 1e-6], \"default\": 1e-7, \"log\": True,\n              \"explain\": \"How often a dividing cell produces a daughter the phage cannot infect. \"\n                         \"This is why the culture comes back.\"},\n    \"cost\":  {\"label\": \"Cost of resistance\", \"unit\": \"fraction of growth rate\", \"min\": 0.0,\n              \"max\": 0.9, \"typical\": [0.0, 0.3], \"default\": 0.1,\n              \"explain\": \"Resistant cells usually grow more slowly. If they did not, they would \"\n                         \"already be everywhere.\"},\n}\n\n\ndef _logistic(S: float, total: float, mu: float, K: float) -> float:\n    return mu * S * (1.0 - total / K)\n\n\n# --------------------------------------------------------------------------\n# Models\n# --------------------------------------------------------------------------\n\ndef _lytic_rhs(t, y, p):\n    \"\"\"Classic lytic model with an Erlang latent chain.\n\n    State: [S, I1..In, P]\n    \"\"\"\n    n = int(p[\"n_stages\"])\n    S = y[0]\n    I = y[1:1 + n]\n    P = y[1 + n]\n    S, P = max(S, 0.0), max(P, 0.0)\n    I = np.maximum(I, 0.0)\n\n    total_cells = S + I.sum()\n    infect = p[\"adsorption\"] * S * P\n    # Erlang: to get a mean latent period L from n stages, each stage runs at n/L.\n    rate = n / p[\"latent\"]\n\n    dS = _logistic(S, total_cells, p[\"mu\"], p[\"K\"]) - infect\n    dI = np.empty(n)\n    dI[0] = infect - rate * I[0]\n    for i in range(1, n):\n        dI[i] = rate * I[i - 1] - rate * I[i]\n    dP = p[\"burst\"] * rate * I[-1] - infect - p[\"decay\"] * P\n    return np.concatenate([[dS], dI, [dP]])\n\n\ndef _lysogenic_rhs(t, y, p):\n    \"\"\"Lytic + lysogenic. State: [S, I1..In, L, P]\n\n    A fraction `lysogeny` of infections become lysogens (L) that grow normally\n    and carry the prophage; they induce back into the lytic cycle at\n    `induction`. This is the model behind BACPHLIP's question.\n    \"\"\"\n    n = int(p[\"n_stages\"])\n    S, I, L, P = y[0], y[1:1 + n], y[1 + n], y[2 + n]\n    S, L, P = max(S, 0.0), max(L, 0.0), max(P, 0.0)\n    I = np.maximum(I, 0.0)\n\n    total = S + I.sum() + L\n    infect = p[\"adsorption\"] * S * P\n    rate = n / p[\"latent\"]\n    f = p[\"lysogeny\"]\n\n    dS = _logistic(S, total, p[\"mu\"], p[\"K\"]) - infect\n    dI = np.empty(n)\n    dI[0] = (1 - f) * infect + p[\"induction\"] * L - rate * I[0]\n    for i in range(1, n):\n        dI[i] = rate * I[i - 1] - rate * I[i]\n    dL = f * infect + _logistic(L, total, p[\"mu\"], p[\"K\"]) - p[\"induction\"] * L\n    dP = p[\"burst\"] * rate * I[-1] - infect - p[\"decay\"] * P\n    return np.concatenate([[dS], dI, [dL], [dP]])\n\n\ndef _resistance_rhs(t, y, p):\n    \"\"\"Lytic + an evolving resistant subpopulation. State: [S, I1..In, R, P]\n\n    This is the model that produces the crash-and-rebound every student expects\n    to see and no textbook figure ever shows them: the culture collapses, then\n    comes back, and the phage cannot touch it the second time.\n    \"\"\"\n    n = int(p[\"n_stages\"])\n    S, I, R, P = y[0], y[1:1 + n], y[1 + n], y[2 + n]\n    S, R, P = max(S, 0.0), max(R, 0.0), max(P, 0.0)\n    I = np.maximum(I, 0.0)\n\n    total = S + I.sum() + R\n    growth_S = _logistic(S, total, p[\"mu\"], p[\"K\"])\n    growth_R = _logistic(R, total, p[\"mu\"] * (1 - p[\"cost\"]), p[\"K\"])\n    mutate = p[\"resistance\"] * max(growth_S, 0.0)\n    infect = p[\"adsorption\"] * S * P\n    rate = n / p[\"latent\"]\n\n    dS = growth_S - mutate - infect\n    dI = np.empty(n)\n    dI[0] = infect - rate * I[0]\n    for i in range(1, n):\n        dI[i] = rate * I[i - 1] - rate * I[i]\n    dR = growth_R + mutate\n    dP = p[\"burst\"] * rate * I[-1] - infect - p[\"decay\"] * P\n    return np.concatenate([[dS], dI, [dR], [dP]])\n\n\ndef _chemostat_rhs(t, y, p):\n    \"\"\"Resource-explicit chemostat. State: [Resource, S, I1..In, P]\n\n    Monod growth on an explicit nutrient with dilution. This is the model where\n    \"what is actually limiting?\" has an answer, and it is the on-ramp to the\n    real literature for a Grade 11-12 capstone.\n    \"\"\"\n    n = int(p[\"n_stages\"])\n    Rn, S, I, P = y[0], y[1], y[2:2 + n], y[2 + n]\n    Rn, S, P = max(Rn, 0.0), max(S, 0.0), max(P, 0.0)\n    I = np.maximum(I, 0.0)\n\n    monod = p[\"mu\"] * Rn / (p[\"Ks\"] + Rn)\n    infect = p[\"adsorption\"] * S * P\n    rate = n / p[\"latent\"]\n    D, R0, yld = p[\"dilution\"], p[\"inflow\"], p[\"yield_coeff\"]\n\n    dR = D * (R0 - Rn) - monod * S / yld\n    dS = monod * S - infect - D * S\n    dI = np.empty(n)\n    dI[0] = infect - rate * I[0] - D * I[0]\n    for i in range(1, n):\n        dI[i] = rate * I[i - 1] - rate * I[i] - D * I[i]\n    dP = p[\"burst\"] * rate * I[-1] - infect - p[\"decay\"] * P - D * P\n    return np.concatenate([[dR], [dS], dI, [dP]])\n\n\n@dataclass\nclass ModelSpec:\n    key: str\n    label: str\n    rhs: Any\n    params: List[str]\n    state_names: Any        # callable(p) -> list[str]\n    initial: Any            # callable(p, y0) -> np.ndarray\n    teaches: str\n    grades: str\n\n\ndef _lytic_states(p):\n    return [\"Susceptible\"] + [f\"Infected (stage {i + 1})\" for i in range(int(p[\"n_stages\"]))] + [\"Free phage\"]\n\n\ndef _lytic_init(p, y0):\n    n = int(p[\"n_stages\"])\n    return np.concatenate([[y0[\"S\"]], np.zeros(n), [y0[\"P\"]]])\n\n\nMODELS: Dict[str, ModelSpec] = {\n    \"lytic\": ModelSpec(\n        \"lytic\", \"Lytic infection (kill only)\", _lytic_rhs,\n        [\"mu\", \"K\", \"adsorption\", \"burst\", \"latent\", \"decay\", \"n_stages\"],\n        _lytic_states, _lytic_init,\n        \"The phage wins, then starves. Watch what happens to the phage count AFTER the \"\n        \"bacteria are gone -- nothing in the model creates more, so it can only fall.\",\n        \"8-10\",\n    ),\n    \"lysogenic\": ModelSpec(\n        \"lysogenic\", \"Lytic + lysogenic (kill or hide)\", _lysogenic_rhs,\n        [\"mu\", \"K\", \"adsorption\", \"burst\", \"latent\", \"decay\", \"n_stages\", \"lysogeny\", \"induction\"],\n        lambda p: _lytic_states(p)[:-1] + [\"Lysogens\", \"Free phage\"],\n        lambda p, y0: np.concatenate([[y0[\"S\"]], np.zeros(int(p[\"n_stages\"])), [0.0], [y0[\"P\"]]]),\n        \"Turn the lysogeny probability up from 0 and the plaque goes cloudy instead of clear. \"\n        \"That is the difference a student can see on a plate, explained.\",\n        \"9-11\",\n    ),\n    \"resistance\": ModelSpec(\n        \"resistance\", \"Lytic + evolving resistance\", _resistance_rhs,\n        [\"mu\", \"K\", \"adsorption\", \"burst\", \"latent\", \"decay\", \"n_stages\", \"resistance\", \"cost\"],\n        lambda p: _lytic_states(p)[:-1] + [\"Resistant\", \"Free phage\"],\n        lambda p, y0: np.concatenate([[y0[\"S\"]], np.zeros(int(p[\"n_stages\"])), [0.0], [y0[\"P\"]]]),\n        \"The crash and the rebound. The culture comes back and the phage cannot touch it. \"\n        \"This is the single most important thing to know before anyone says 'phage therapy'.\",\n        \"9-12\",\n    ),\n    \"chemostat\": ModelSpec(\n        \"chemostat\", \"Resource-explicit chemostat\", _chemostat_rhs,\n        [\"mu\", \"adsorption\", \"burst\", \"latent\", \"decay\", \"n_stages\",\n         \"Ks\", \"dilution\", \"inflow\", \"yield_coeff\"],\n        lambda p: [\"Resource\"] + _lytic_states(p),\n        lambda p, y0: np.concatenate(\n            [[y0.get(\"R\", p[\"inflow\"])], [y0[\"S\"]], np.zeros(int(p[\"n_stages\"])), [y0[\"P\"]]]),\n        \"Now the food is in the model too. Coexistence and oscillation appear, and they are not \"\n        \"a bug -- predator and prey cycling is what these equations do.\",\n        \"11-12\",\n    ),\n}\n\n_EXTRA_DEFAULTS = {\"Ks\": 1e6, \"dilution\": 0.2, \"inflow\": 1e9, \"yield_coeff\": 1e6}\n\n\ndef _defaults(model: str) -> Dict[str, float]:\n    spec = MODELS[model]\n    out = {}\n    for k in spec.params:\n        if k in PARAM_META:\n            out[k] = PARAM_META[k][\"default\"]\n        else:\n            out[k] = _EXTRA_DEFAULTS[k]\n    return out\n\n\ndef _plausibility(p: Dict[str, float]) -> List[str]:\n    warn = []\n    for k, v in p.items():\n        meta = PARAM_META.get(k)\n        if not meta:\n            continue\n        lo, hi = meta[\"typical\"]\n        if v < lo or v > hi:\n            warn.append(\n                f\"{meta['label']} = {v:g} {meta['unit']} is outside the range usually measured \"\n                f\"for real phage ({lo:g} to {hi:g}). The simulation will still run -- that is the \"\n                f\"point of a simulation -- but do not report the result as what a real phage does.\")\n    return warn\n\n\n@bound(\"simulate\")\ndef simulate(model: str = \"lytic\", params: Optional[Dict[str, float]] = None,\n             S0: float = 1e6, P0: float = 1e4, hours: float = 24.0,\n             n_points: int = 400, R0: Optional[float] = None) -> Dict[str, Any]:\n    \"\"\"Run one host-phage simulation.\n\n    Uses LSODA, which switches between a non-stiff and a stiff method on its\n    own. These systems go stiff the moment the susceptible population crashes,\n    and a fixed non-stiff solver silently produces garbage there.\n    \"\"\"\n    spec = MODELS.get(model)\n    if spec is None:\n        return {\"refused\": True, \"reason\": f\"Unknown model {model!r}.\",\n                \"available_models\": list(MODELS)}\n\n    p = _defaults(model)\n    p.update({k: float(v) for k, v in (params or {}).items() if k in p})\n    p[\"n_stages\"] = max(1, int(round(p[\"n_stages\"])))\n    if p.get(\"latent\", 1.0) <= 0:\n        return {\"refused\": True, \"reason\": \"The latent period must be greater than zero.\"}\n\n    y0 = {\"S\": float(S0), \"P\": float(P0)}\n    if R0 is not None:\n        y0[\"R\"] = float(R0)\n    init = spec.initial(p, y0)\n    t_eval = np.linspace(0.0, float(hours), int(n_points))\n\n    sol = solve_ivp(spec.rhs, (0.0, float(hours)), init, args=(p,),\n                    method=\"LSODA\", t_eval=t_eval, rtol=1e-8, atol=1e-3, max_step=0.1)\n    if not sol.success:\n        return {\"refused\": True, \"reason\": f\"The solver failed: {sol.message}. \"\n                                           f\"This usually means a parameter is extreme.\"}\n\n    names = spec.state_names(p)\n    Y = np.maximum(sol.y, 0.0)\n    n = p[\"n_stages\"]\n\n    # Collapse the Erlang chain for display -- a student wants one \"infected\"\n    # curve, not fifteen. The stages stay available for the Grade 11 view.\n    if model == \"chemostat\":\n        series = {\"Resource\": Y[0], \"Susceptible\": Y[1],\n                  \"Infected\": Y[2:2 + n].sum(axis=0), \"Free phage\": Y[2 + n]}\n    elif model == \"lytic\":\n        series = {\"Susceptible\": Y[0], \"Infected\": Y[1:1 + n].sum(axis=0), \"Free phage\": Y[1 + n]}\n    elif model == \"lysogenic\":\n        series = {\"Susceptible\": Y[0], \"Infected\": Y[1:1 + n].sum(axis=0),\n                  \"Lysogens\": Y[1 + n], \"Free phage\": Y[2 + n]}\n    else:\n        series = {\"Susceptible\": Y[0], \"Infected\": Y[1:1 + n].sum(axis=0),\n                  \"Resistant\": Y[1 + n], \"Free phage\": Y[2 + n]}\n\n    t = sol.t\n    host_total = sum(v for k, v in series.items() if k not in (\"Free phage\", \"Resource\"))\n    phage = series[\"Free phage\"]\n    host0 = host_total[0]\n    nadir_i = int(np.argmin(host_total))\n    peak_phage_i = int(np.argmax(phage))\n\n    collapsed = bool(host_total.min() < 0.01 * max(host0, 1e-12))\n    rebounded = bool(nadir_i < len(t) - 2 and host_total[-1] > 10 * max(host_total[nadir_i], 1e-12))\n    amplification = float(phage.max() / max(phage[0], 1e-12))\n\n    summary = {\n        \"initial_moi\": float(P0 / max(S0, 1e-12)),\n        \"host_collapsed\": collapsed,\n        \"host_rebounded\": rebounded,\n        \"nadir_time\": float(t[nadir_i]), \"nadir_host\": float(host_total[nadir_i]),\n        \"final_host\": float(host_total[-1]), \"final_phage\": float(phage[-1]),\n        \"peak_phage\": float(phage.max()), \"peak_phage_time\": float(t[peak_phage_i]),\n        \"phage_amplification\": amplification,\n        \"log10_amplification\": float(np.log10(max(amplification, 1e-12))),\n    }\n    if model == \"resistance\":\n        r = series[\"Resistant\"]\n        summary[\"final_resistant_fraction\"] = float(r[-1] / max(host_total[-1], 1e-12))\n\n    return {\n        \"model\": model, \"model_label\": spec.label, \"teaches\": spec.teaches,\n        \"grades\": spec.grades,\n        \"parameters\": p, \"initial\": {\"S0\": float(S0), \"P0\": float(P0)},\n        \"time\": t.tolist(),\n        \"series\": {k: v.tolist() for k, v in series.items()},\n        \"stage_series\": {f\"Infected stage {i + 1}\": Y[(1 if model != 'chemostat' else 2) + i].tolist()\n                         for i in range(n)} if n <= 8 else {},\n        \"summary\": summary,\n        \"solver\": {\"method\": \"LSODA\", \"rtol\": 1e-8, \"atol\": 1e-3, \"n_eval\": int(t.size),\n                   \"message\": sol.message},\n        \"notes\": _plausibility(p),\n        \"plain_language\": _narrate(model, summary, p),\n        \"p_value\": None,\n    }\n\n\ndef _narrate(model: str, s: Dict[str, Any], p: Dict[str, float]) -> str:\n    bits = [f\"Starting at MOI {s['initial_moi']:.3g} \"\n            f\"({'more phage than bacteria' if s['initial_moi'] > 1 else 'fewer phage than bacteria'}):\"]\n    if s[\"host_collapsed\"]:\n        bits.append(f\"the bacteria crashed by {s['nadir_time']:.2g} hours\")\n    else:\n        bits.append(f\"the bacteria were knocked back but never wiped out \"\n                    f\"(lowest point {s['nadir_host']:.3g} cells/mL at {s['nadir_time']:.2g} h)\")\n    bits.append(f\"and the phage multiplied {s['log10_amplification']:.1f} orders of magnitude, \"\n                f\"peaking at {s['peak_phage']:.3g}/mL around {s['peak_phage_time']:.2g} h\")\n    if s.get(\"host_rebounded\"):\n        extra = \"\"\n        if \"final_resistant_fraction\" in s:\n            extra = (f\", and {s['final_resistant_fraction'] * 100:.0f}% of the survivors are \"\n                     f\"resistant -- the phage cannot clear them\")\n        bits.append(f\"then the culture recovered{extra}\")\n    elif model == \"resistance\" and s.get(\"final_resistant_fraction\", 0) > 0.5:\n        bits.append(\"and the survivors are almost entirely resistant\")\n    return \". \".join([\" \".join(bits[:2])] + bits[2:]) + \".\"\n\n\n@bound(\"parameter_sweep\")\ndef parameter_sweep(model: str = \"lytic\", parameter: str = \"adsorption\",\n                    values: Optional[Sequence[float]] = None, n_values: int = 9,\n                    log_scale: bool = True, base_params: Optional[Dict[str, float]] = None,\n                    S0: float = 1e6, P0: float = 1e4, hours: float = 24.0) -> Dict[str, Any]:\n    \"\"\"Sweep one parameter and tabulate the outcome (spec section 03.3 / G8-L12).\n\n    G8-L12 already establishes the entire pedagogy: set four parameters, sweep\n    each one, compute a rate, plot it, write a conclusion. This is that lesson\n    with a phage in the flask instead of an enzyme, and the output table is\n    shaped so it drops straight into `fit_curve` -- the student sweeps, then\n    fits, then gets an interval, without leaving the platform.\n    \"\"\"\n    spec = MODELS.get(model)\n    if spec is None:\n        return {\"refused\": True, \"reason\": f\"Unknown model {model!r}.\"}\n    if parameter not in spec.params:\n        return {\"refused\": True, \"reason\": f\"{parameter!r} is not a parameter of the {model} model.\",\n                \"available_parameters\": spec.params}\n\n    base = _defaults(model)\n    base.update({k: float(v) for k, v in (base_params or {}).items() if k in base})\n\n    if values is None:\n        meta = PARAM_META.get(parameter)\n        if meta is None:\n            lo, hi = base[parameter] / 10, base[parameter] * 10\n            use_log = True\n        else:\n            lo, hi = meta[\"typical\"]\n            use_log = bool(meta.get(\"log\")) and log_scale\n            lo = max(lo, meta[\"min\"]) or meta[\"min\"]\n        vals = (np.logspace(np.log10(max(lo, 1e-300)), np.log10(max(hi, 1e-299)), n_values)\n                if use_log else np.linspace(lo, hi, n_values))\n        if PARAM_META.get(parameter, {}).get(\"integer\"):\n            vals = np.unique(np.round(vals)).astype(float)\n    else:\n        vals = np.asarray(values, dtype=float)\n\n    rows = []\n    for v in vals:\n        p = dict(base)\n        p[parameter] = float(v)\n        r = simulate.__wrapped__(model=model, params=p, S0=S0, P0=P0, hours=hours, n_points=300)\n        if r.get(\"refused\"):\n            continue\n        s = r[\"summary\"]\n        rows.append({\n            parameter: float(v),\n            \"log10_amplification\": s[\"log10_amplification\"],\n            \"peak_phage\": s[\"peak_phage\"],\n            \"time_to_nadir\": s[\"nadir_time\"],\n            \"final_host\": s[\"final_host\"],\n            \"host_collapsed\": s[\"host_collapsed\"],\n            \"clearance\": float(1.0 - s[\"final_host\"] / max(S0, 1e-12)),\n        })\n\n    if not rows:\n        return {\"refused\": True, \"reason\": \"Every simulation in the sweep failed.\"}\n\n    x = np.array([r[parameter] for r in rows])\n    y = np.array([r[\"log10_amplification\"] for r in rows])\n    collapsed = [r[parameter] for r in rows if r[\"host_collapsed\"]]\n    threshold = float(min(collapsed)) if collapsed else None\n\n    return {\n        \"model\": model, \"parameter\": parameter,\n        \"parameter_label\": PARAM_META.get(parameter, {}).get(\"label\", parameter),\n        \"parameter_unit\": PARAM_META.get(parameter, {}).get(\"unit\", \"\"),\n        \"values\": x.tolist(), \"rows\": rows,\n        \"base_parameters\": base,\n        \"response\": {\"x\": x.tolist(), \"y\": y.tolist(), \"y_label\": \"log10 phage amplification\"},\n        \"collapse_threshold\": threshold,\n        \"monotonic\": bool(np.all(np.diff(y) >= -1e-9) or np.all(np.diff(y) <= 1e-9)),\n        \"plain_language\": (\n            f\"Swept {PARAM_META.get(parameter, {}).get('label', parameter)} across \"\n            f\"{len(rows)} values. Phage amplification ranged from {y.min():.1f} to {y.max():.1f} \"\n            f\"orders of magnitude\"\n            + (f\", and the bacteria were wiped out once {parameter} reached {threshold:.3g}.\"\n               if threshold is not None else\n               \", and the bacteria survived at every value tried.\")\n            + \" Feed the response column into a curve fit to get the shape and its interval.\"),\n        \"next_step\": {\"tool\": \"fit_curve\", \"x\": x.tolist(), \"y\": y.tolist(),\n                      \"suggested_model\": \"four_pl\"},\n        \"p_value\": None,\n    }\n\n\n@bound(\"one_step_growth\")\ndef one_step_growth(latent: float = 0.5, burst: float = 100, n_stages: int = 20,\n                    adsorption: float = 1e-8, S0: float = 1e8, P0: float = 1e4,\n                    hours: float = 3.0) -> Dict[str, Any]:\n    \"\"\"The one-step growth curve, and why the Erlang chain exists.\n\n    Runs the same experiment at n_stages = 1 and at the chosen n_stages, so the\n    student sees directly that with one compartment the burst is smeared into an\n    exponential and with twenty it is a step. The latent period becomes visible\n    as a thing made of stages, which is the whole pedagogical point of using an\n    ODE chain instead of hiding a delay in a solver.\n    \"\"\"\n    out = {}\n    for n in sorted({1, 3, int(n_stages)}):\n        r = simulate.__wrapped__(\n            model=\"lytic\",\n            params={\"adsorption\": adsorption, \"burst\": burst, \"latent\": latent,\n                    \"n_stages\": n, \"decay\": 0.0, \"mu\": 0.0, \"K\": 1e12},\n            S0=S0, P0=P0, hours=hours, n_points=400)\n        if r.get(\"refused\"):\n            continue\n        t = np.array(r[\"time\"])\n        P = np.array(r[\"series\"][\"Free phage\"])\n        # In a one-step experiment free phage first FALL, as they adsorb onto\n        # cells, and only rise when the first cells burst. So the latent period\n        # is the time from the minimum to the first clear rise off it -- not a\n        # fraction of the (much later, much larger) plateau.\n        dip = int(np.argmin(P))\n        after = P[dip:]\n        rose = np.nonzero(after > 1.5 * max(P[dip], 1e-12))[0]\n        idx = dip + int(rose[0]) if rose.size else int(np.argmax(P))\n        out[f\"{n}_stages\"] = {\n            \"n_stages\": n, \"time\": t.tolist(), \"free_phage\": P.tolist(),\n            \"observed_rise_start\": float(t[idx]),\n            \"plateau\": float(P.max()),\n            \"adsorption_minimum\": float(P.min()),\n            \"burst_size_estimate\": float(P.max() / max(P.min(), 1e-12)),\n        }\n\n    ref = out.get(f\"{int(n_stages)}_stages\")\n    return {\n        \"runs\": out, \"requested_stages\": int(n_stages),\n        \"true_latent_period\": float(latent), \"true_burst_size\": float(burst),\n        \"recovered_latent_period\": ref[\"observed_rise_start\"] if ref else None,\n        \"teaches\": (\n            \"With 1 stage the phage start appearing immediately and the 'latent period' is \"\n            \"invisible -- the model is wrong in a way you can see. Add stages and a real plateau \"\n            \"appears before the rise. That plateau is the latent period, and it is made of \"\n            \"compartments, not of a hidden delay.\"),\n        \"plain_language\": (\n            f\"With {n_stages} stages the free-phage count stays flat until about \"\n            f\"{ref['observed_rise_start']:.3g} h (true latent period {latent:g} h), then rises to \"\n            f\"about {ref['burst_size_estimate']:.3g} times the starting count \"\n            f\"(true burst size {burst:g}). Compare the 1-stage run to see why the chain matters.\"\n            if ref else \"The simulation did not complete.\"),\n        \"p_value\": None,\n    }\n",
  "phagequest_engine/simulation/plaque.py": "\"\"\"Agent-based plaque formation on a lattice (spec section 03.3).\n\n    \"A visual, spatial model of a plaque spreading through a lawn. This is the\n    screen that makes G8-L10's clear circles click.\"\n\nMesa is the Tier-1 choice; it is not in Pyodide and, for a lattice of a few\nhundred cells a side, it is also considerably slower than doing it with numpy.\nSo this is a vectorised cellular automaton: every step is array arithmetic, a\n250x250 lawn runs 200 steps in well under a second in the browser, and the\nframes stream straight to a canvas.\n\nThe model is deliberately simple enough that a student can state its rules in\none breath -- which is the difference between a simulation they learn from and\nan animation they watch.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Dict, List, Optional\n\nimport numpy as np\n\nfrom ..transcript import bound\n\n__all__ = [\"plaque_growth\", \"STATES\"]\n\n# Lattice states\nUNINFECTED, INFECTED, LYSED, RESISTANT = 0, 1, 2, 3\nSTATES = {UNINFECTED: \"lawn\", INFECTED: \"infected\", LYSED: \"plaque (lysed)\", RESISTANT: \"resistant\"}\n\n\n@bound(\"plaque_growth\")\ndef plaque_growth(size: int = 151, steps: int = 120, latent_steps: int = 4,\n                  spread_probability: float = 0.45, diffusion_radius: int = 1,\n                  resistant_fraction: float = 0.0, n_seeds: int = 1,\n                  capture_every: int = 4, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"Grow plaques on a bacterial lawn and measure them.\n\n    Rules, in full:\n      1. Start with a lawn of susceptible cells, a few of them resistant.\n      2. Drop `n_seeds` infected cells.\n      3. An infected cell waits `latent_steps` steps, then lyses.\n      4. When it lyses, each susceptible neighbour within `diffusion_radius`\n         becomes infected with probability `spread_probability`.\n      5. Resistant cells never become infected.\n\n    What it measures: plaque radius over time, final area, and -- the point --\n    the *edge roughness*, which is what actually distinguishes phage on a real\n    plate and which no textbook diagram ever shows.\n    \"\"\"\n    size = int(np.clip(size, 21, 401))\n    steps = int(np.clip(steps, 5, 600))\n    rng = np.random.default_rng(seed)\n\n    grid = np.full((size, size), UNINFECTED, dtype=np.int8)\n    if resistant_fraction > 0:\n        grid[rng.random((size, size)) < float(resistant_fraction)] = RESISTANT\n\n    timer = np.zeros((size, size), dtype=np.int16)\n    centre = size // 2\n    seeds = [(centre, centre)]\n    for _ in range(max(0, int(n_seeds) - 1)):\n        seeds.append((int(rng.integers(3, size - 3)), int(rng.integers(3, size - 3))))\n    for r, c in seeds:\n        grid[r, c] = INFECTED\n        timer[r, c] = int(latent_steps)\n\n    rad = int(np.clip(diffusion_radius, 1, 4))\n    # Moore neighbourhood (Chebyshev distance). The von Neumann version -- four\n    # neighbours only -- makes the process barely supercritical at realistic\n    # spread probabilities, so a student's first run often dies out and looks\n    # broken. Diagonals included, the automaton behaves like a plaque.\n    offsets = [(dr, dc) for dr in range(-rad, rad + 1) for dc in range(-rad, rad + 1)\n               if (dr or dc)]\n\n    frames: List[List[List[int]]] = []\n    series = {\"step\": [], \"infected\": [], \"lysed\": [], \"uninfected\": [],\n              \"radius\": [], \"perimeter\": []}\n\n    for step in range(steps):\n        timer[grid == INFECTED] -= 1\n        lysing = (grid == INFECTED) & (timer <= 0)\n\n        if lysing.any():\n            # Vectorised spread: shift the lysing mask in each direction, and\n            # infect susceptible cells there with the given probability.\n            newly = np.zeros_like(lysing)\n            for dr, dc in offsets:\n                shifted = np.zeros_like(lysing)\n                r0, r1 = max(0, dr), size + min(0, dr)\n                c0, c1 = max(0, dc), size + min(0, dc)\n                shifted[r0:r1, c0:c1] = lysing[r0 - dr:r1 - dr, c0 - dc:c1 - dc]\n                hit = shifted & (grid == UNINFECTED) & (rng.random((size, size)) < spread_probability)\n                newly |= hit\n            grid[lysing] = LYSED\n            grid[newly] = INFECTED\n            timer[newly] = int(latent_steps)\n\n        lysed_mask = grid == LYSED\n        n_lysed = int(lysed_mask.sum())\n        n_inf = int((grid == INFECTED).sum())\n\n        if n_lysed:\n            rr, cc = np.nonzero(lysed_mask)\n            radius = float(np.sqrt(((rr - centre) ** 2 + (cc - centre) ** 2).max()))\n            # Perimeter: lysed cells with at least one non-lysed 4-neighbour.\n            pad = np.pad(lysed_mask, 1, constant_values=False)\n            edge = lysed_mask & ~(pad[:-2, 1:-1] & pad[2:, 1:-1] & pad[1:-1, :-2] & pad[1:-1, 2:])\n            perimeter = int(edge.sum())\n        else:\n            radius, perimeter = 0.0, 0\n\n        series[\"step\"].append(step)\n        series[\"infected\"].append(n_inf)\n        series[\"lysed\"].append(n_lysed)\n        series[\"uninfected\"].append(int((grid == UNINFECTED).sum()))\n        series[\"radius\"].append(radius)\n        series[\"perimeter\"].append(perimeter)\n\n        if step % max(1, int(capture_every)) == 0:\n            frames.append(grid.tolist())\n\n        if n_inf == 0:\n            break\n\n    frames.append(grid.tolist())\n\n    lysed_mask = grid == LYSED\n    area = int(lysed_mask.sum())\n    final_radius = series[\"radius\"][-1] if series[\"radius\"] else 0.0\n    perimeter = series[\"perimeter\"][-1] if series[\"perimeter\"] else 0\n    # Circularity: 1 for a perfect disc, lower for a ragged edge. Real plaques\n    # are rarely above 0.8 and the students' own plates will not be either.\n    circularity = float(4 * np.pi * area / perimeter ** 2) if perimeter else float(\"nan\")\n\n    steps_run = len(series[\"step\"])\n    growth_rate = float(np.polyfit(series[\"step\"][-min(20, steps_run):],\n                                   series[\"radius\"][-min(20, steps_run):], 1)[0]) \\\n        if steps_run >= 4 else float(\"nan\")\n\n    stopped = series[\"infected\"][-1] == 0 if series[\"infected\"] else True\n    fizzled = stopped and area < 20\n    if not stopped:\n        reason = \"the simulation reached its step limit\"\n    elif fizzled:\n        reason = (f\"the infection fizzled out after only {area} cells -- with a spread probability \"\n                  f\"of {spread_probability:.2f} each lysis produces about \"\n                  f\"{spread_probability * len(offsets):.1f} new infections on average, and a chain \"\n                  f\"that close to 1 often dies by chance. That is a real result about real phage, \"\n                  f\"not a broken simulation: raise the spread probability and watch the threshold\")\n    elif resistant_fraction > 0:\n        reason = \"the infection ran out of susceptible neighbours\"\n    else:\n        reason = \"the infection died out\"\n\n    return {\n        \"size\": size, \"steps_run\": steps_run,\n        \"parameters\": {\"latent_steps\": int(latent_steps),\n                       \"spread_probability\": float(spread_probability),\n                       \"diffusion_radius\": rad, \"resistant_fraction\": float(resistant_fraction),\n                       \"n_seeds\": len(seeds), \"seed\": int(seed)},\n        \"frames\": frames, \"frame_every\": int(capture_every),\n        \"state_legend\": {str(k): v for k, v in STATES.items()},\n        \"series\": series,\n        \"final\": {\n            \"plaque_area_cells\": area,\n            \"plaque_radius_cells\": float(final_radius),\n            \"perimeter_cells\": perimeter,\n            \"circularity\": circularity,\n            \"radial_growth_rate\": growth_rate,\n            \"fraction_lawn_cleared\": float(area / (size * size)),\n            \"stopped_because\": reason,\n        },\n        \"fizzled\": bool(fizzled),\n        \"expected_offspring_per_lysis\": float(spread_probability * len(offsets)),\n        \"teaches\": (\n            \"A plaque is not a hole that appears -- it is a wave that travels. Its radius grows \"\n            \"roughly linearly with time, which is why plaques are round and why a plate left \"\n            \"overnight has bigger ones than a plate read after four hours.\"),\n        \"plain_language\": (\n            f\"After {steps_run} steps the plaque is about {final_radius:.0f} cells across the \"\n            f\"radius, covering {area:,} cells ({area / (size * size):.1%} of the lawn), and it grew \"\n            f\"at roughly {growth_rate:.2f} cells of radius per step. Its circularity is \"\n            f\"{circularity:.2f} (1.0 would be a perfect circle) -- the edge is ragged because \"\n            f\"infection spreads by chance, not by rule. \"\n            + (f\"With {resistant_fraction:.0%} of the lawn resistant, \" if resistant_fraction > 0 else \"\")\n            + f\"the run ended because {reason}.\"),\n        \"p_value\": None,\n    }\n",
  "phagequest_engine/simulation/stochastic.py": "\"\"\"Stochastic simulation (spec section 03.3).\n\n    \"For the capstone question: why does the same sample sometimes give plaques\n    and sometimes not? The curriculum's own 'no result is also a result'\n    discussion has a mathematical answer, and it is Poisson.\"\n\nGillesPy2 and StochPy are Tier-1 and not in Pyodide. The Gillespie direct\nmethod is forty lines and exact, so it lives here in Tier-0 where it belongs:\nthis is the module that answers a Grade 8's question about their own plate, and\nit must not require a server round-trip to do it.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Dict, List, Optional\n\nimport numpy as np\nfrom scipy import stats\n\nfrom ..transcript import bound\n\n__all__ = [\"gillespie_lytic\", \"extinction_probability\", \"poisson_plaques\"]\n\n\n@bound(\"gillespie_lytic\")\ndef gillespie_lytic(S0: int = 200, P0: int = 5, adsorption: float = 1e-3,\n                    burst: int = 50, lysis_rate: float = 2.0, growth: float = 0.5,\n                    decay: float = 0.05, t_max: float = 20.0, n_runs: int = 30,\n                    max_events: int = 400_000, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"Exact stochastic simulation (Gillespie direct method), repeated n_runs times.\n\n    Small numbers are where chance actually bites: with 5 phage and 200 cells,\n    the deterministic model says \"infection happens\" and the real world says\n    \"sometimes\". Running the same experiment thirty times and drawing all thirty\n    trajectories is the single clearest demonstration of that a student can see.\n\n    Reactions:\n        S            -> 2S          rate  growth * S\n        S + P        -> I           rate  adsorption * S * P\n        I            -> burst * P   rate  lysis_rate * I\n        P            -> 0           rate  decay * P\n    \"\"\"\n    rng = np.random.default_rng(seed)\n    runs: List[Dict[str, Any]] = []\n    extinctions = 0\n    peak_phages: List[float] = []\n    clear_times: List[float] = []\n\n    for r in range(int(n_runs)):\n        S, I, P = int(S0), 0, int(P0)\n        t = 0.0\n        ts, Ss, Is, Ps = [0.0], [S], [I], [P]\n        events = 0\n        while t < t_max and events < max_events:\n            a1 = growth * S\n            a2 = adsorption * S * P\n            a3 = lysis_rate * I\n            a4 = decay * P\n            a0 = a1 + a2 + a3 + a4\n            if a0 <= 0:\n                break\n            t += float(rng.exponential(1.0 / a0))\n            if t > t_max:\n                break\n            u = rng.random() * a0\n            if u < a1:\n                S += 1\n            elif u < a1 + a2:\n                S -= 1\n                I += 1\n                P -= 1\n            elif u < a1 + a2 + a3:\n                I -= 1\n                P += int(burst)\n            else:\n                P -= 1\n            events += 1\n            # Subsample the trace: 400k events is not a drawable curve.\n            if events % 50 == 0:\n                ts.append(t); Ss.append(S); Is.append(I); Ps.append(P)\n        ts.append(min(t, t_max)); Ss.append(S); Is.append(I); Ps.append(P)\n\n        died_out = (P == 0 and I == 0)\n        extinctions += int(died_out)\n        peak_phages.append(float(max(Ps)))\n        if S == 0:\n            idx = next((i for i, v in enumerate(Ss) if v == 0), None)\n            if idx is not None:\n                clear_times.append(float(ts[idx]))\n        runs.append({\n            \"run\": r, \"time\": ts, \"S\": Ss, \"I\": Is, \"P\": Ps,\n            \"phage_extinct\": bool(died_out), \"host_cleared\": bool(S == 0),\n            \"final_S\": int(S), \"final_P\": int(P), \"events\": events,\n        })\n\n    n = len(runs)\n    p_ext = extinctions / n if n else float(\"nan\")\n    # Wilson interval -- correct at the small n and extreme proportions this\n    # produces, where the normal approximation is simply wrong.\n    lo, hi = _wilson(extinctions, n)\n\n    return {\n        \"n_runs\": n, \"runs\": runs,\n        \"extinction_count\": extinctions,\n        \"extinction_probability\": float(p_ext),\n        \"extinction_ci\": [lo, hi],\n        \"host_cleared_count\": sum(r[\"host_cleared\"] for r in runs),\n        \"peak_phage_median\": float(np.median(peak_phages)) if peak_phages else float(\"nan\"),\n        \"peak_phage_range\": [float(np.min(peak_phages)), float(np.max(peak_phages))]\n                            if peak_phages else [],\n        \"clearance_time_median\": float(np.median(clear_times)) if clear_times else None,\n        \"parameters\": {\"S0\": int(S0), \"P0\": int(P0), \"adsorption\": adsorption, \"burst\": int(burst),\n                       \"lysis_rate\": lysis_rate, \"growth\": growth, \"decay\": decay},\n        \"teaches\": (\n            \"Every one of these runs used identical settings. They did not come out the same. \"\n            \"That is not experimental error -- it is what small numbers do, and it is the reason \"\n            \"your plate sometimes has no plaques.\"),\n        \"plain_language\": (\n            f\"Ran the same experiment {n} times with {P0} phage and {S0} cells. The phage died out \"\n            f\"completely in {extinctions} of them ({p_ext:.0%}, 95% CI {lo:.0%} to {hi:.0%}), and \"\n            f\"cleared the culture in {sum(r['host_cleared'] for r in runs)}. \"\n            f\"Identical settings, different outcomes.\"),\n        \"p_value\": None,\n    }\n\n\ndef _wilson(successes: int, n: int, z: float = 1.96) -> tuple:\n    if n == 0:\n        return (float(\"nan\"), float(\"nan\"))\n    p = successes / n\n    d = 1 + z ** 2 / n\n    c = p + z ** 2 / (2 * n)\n    s = z * np.sqrt(p * (1 - p) / n + z ** 2 / (4 * n ** 2))\n    return (float(max(0.0, (c - s) / d)), float(min(1.0, (c + s) / d)))\n\n\n@bound(\"extinction_probability\")\ndef extinction_probability(burst: int = 50, adsorption: float = 1e-3, S0: int = 200,\n                           decay: float = 0.05, P0_values: Optional[List[int]] = None,\n                           n_runs: int = 60, seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"How likely is it that a few phage go extinct before they get going?\n\n    Also reports the branching-process prediction, so the student has a\n    theoretical curve to compare their simulated points against -- which is the\n    shape of a real scientific argument, not a demo.\n    \"\"\"\n    P0s = list(P0_values or [1, 2, 3, 5, 8, 12, 20])\n    rows = []\n    for p0 in P0s:\n        # growth=0: the branching-process prediction below assumes the host\n        # pool is fixed. Letting the bacteria divide would make the simulation\n        # and the theory answer subtly different questions.\n        r = gillespie_lytic.__wrapped__(\n            S0=S0, P0=int(p0), adsorption=adsorption, burst=burst, growth=0.0,\n            decay=decay, n_runs=n_runs, t_max=15.0, seed=seed + p0)\n        rows.append({\"P0\": int(p0), \"extinction_probability\": r[\"extinction_probability\"],\n                     \"ci\": r[\"extinction_ci\"], \"n_runs\": r[\"n_runs\"]})\n\n    # Branching process: a single phage either adsorbs (and yields `burst`\n    # offspring) or decays first. q = P(a lineage from one phage dies out).\n    ads = adsorption * S0\n    p_success = ads / (ads + decay)\n    q_single = _extinction_root(p_success, int(burst))\n    for row in rows:\n        row[\"theory\"] = float(q_single ** row[\"P0\"])\n\n    return {\n        \"rows\": rows,\n        \"single_phage_extinction\": float(q_single),\n        \"p_adsorb_before_decay\": float(p_success),\n        \"theory_note\": (\n            \"The theoretical curve is a branching process: one phage either finds a cell \"\n            \"(probability p) and makes `burst` descendants, or falls apart first. The chance a \"\n            \"whole lineage dies out is the smallest root of q = (1-p) + p*q^burst, and starting \"\n            \"with n phage just raises that to the n-th power. The bacteria are held at a fixed \"\n            \"number for this comparison; let them divide and the simulated points fall below the \"\n            \"theory, because a growing host pool gives late phage more chances.\"),\n        \"plain_language\": (\n            f\"A single phage in this culture has about a {q_single:.1%} chance of leaving no \"\n            f\"descendants at all. Start with {P0s[-1]} phage instead and that drops to \"\n            f\"{q_single ** P0s[-1]:.2%}. This is why 'we saw no plaques' does not mean \"\n            f\"'there was no phage'.\"),\n        \"p_value\": None,\n    }\n\n\ndef _extinction_root(p: float, burst: int) -> float:\n    \"\"\"Smallest root in [0,1] of q = (1-p) + p q^burst, by bisection.\"\"\"\n    if p <= 0:\n        return 1.0\n    f = lambda q: (1 - p) + p * q ** burst - q\n    if f(0.0) <= 0:\n        return 0.0\n    lo, hi = 0.0, 1.0 - 1e-12\n    if f(hi) > 0:\n        return 1.0\n    for _ in range(200):\n        mid = 0.5 * (lo + hi)\n        if f(mid) > 0:\n            lo = mid\n        else:\n            hi = mid\n    return float(0.5 * (lo + hi))\n\n\n@bound(\"poisson_plaques\")\ndef poisson_plaques(expected_plaques: float = 3.0, n_plates: int = 20,\n                    seed: int = 20260901) -> Dict[str, Any]:\n    \"\"\"The Grade 8 answer to \"why did my plate have none?\" (G8-L10).\n\n    Plaque counts are Poisson. At an expected 3 plaques per plate, one plate in\n    twenty comes up empty by pure chance -- and a student who does not know that\n    concludes their sample had no phage. This function simulates a class's worth\n    of plates and puts the exact probability next to them.\n    \"\"\"\n    lam = float(expected_plaques)\n    if lam < 0:\n        return {\"refused\": True, \"reason\": \"Expected plaque count cannot be negative.\"}\n    rng = np.random.default_rng(seed)\n    counts = rng.poisson(lam, int(n_plates))\n    p_zero = float(stats.poisson.pmf(0, lam))\n    p_ge_double = float(stats.poisson.sf(2 * lam - 1, lam)) if lam > 0 else 0.0\n\n    return {\n        \"expected\": lam, \"n_plates\": int(n_plates),\n        \"simulated_counts\": counts.tolist(),\n        \"observed_mean\": float(counts.mean()), \"observed_variance\": float(counts.var(ddof=1)),\n        \"n_empty_plates\": int((counts == 0).sum()),\n        \"probability_of_empty_plate\": p_zero,\n        \"probability_of_double_or_more\": p_ge_double,\n        \"pmf\": {int(k): float(stats.poisson.pmf(k, lam)) for k in range(0, int(max(12, 3 * lam)))},\n        \"counting_interval_for_one_plate\": [\n            float(stats.chi2.ppf(0.025, 2 * max(1, int(lam))) / 2),\n            float(stats.chi2.ppf(0.975, 2 * (int(lam) + 1)) / 2)],\n        \"teaches\": (\n            \"For Poisson counts the variance equals the mean, so the uncertainty on a count of n \"\n            \"is about the square root of n. Count 9 plaques and you know the number to about \"\n            \"plus-or-minus 3 -- which is why you never report a titre from a single plate.\"),\n        \"plain_language\": (\n            f\"If a plate should average {lam:g} plaques, then {p_zero:.1%} of plates come up \"\n            f\"completely empty by chance alone. In this simulated set of {n_plates} plates, \"\n            f\"{int((counts == 0).sum())} were empty. An empty plate is not proof of no phage -- \"\n            f\"it is evidence, and weak evidence at that.\"),\n        \"p_value\": None,\n    }\n",
  "phagequest_engine/stability.py": "\"\"\"The automatic stability check (spec section 06, point 5).\n\n    \"a model's own stated confidence is no help here: it is a fluency signal,\n    not a stability measurement. The only thing that tells you whether a\n    conclusion holds is perturbing the data and re-running it -- which is why\n    the stability check below is automatic rather than optional.\"\n\nSo: it is not a flag the student can turn off, and not a separate menu item.\nEvery inferential result carries a StabilityReport, and if the conclusion flips\nthe frontend renders that *above* the p-value.\n\nThis is the Predictability-Computability-Stability sanity check, operationalised.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, asdict, field\nfrom typing import Callable, Dict, List, Sequence\n\nimport numpy as np\n\n__all__ = [\"StabilityReport\", \"stability_check\"]\n\n\n@dataclass\nclass StabilityReport:\n    ran: bool\n    n_perturbations: int\n    conclusion: str                    # the conclusion on the full data\n    agreement: float                   # fraction of perturbations agreeing\n    flipped: bool\n    p_range: List[float] = field(default_factory=list)\n    effect_range: List[float] = field(default_factory=list)\n    most_influential: Dict | None = None\n    verdict: str = \"\"\n    severity: str = \"info\"             # info | warn | block\n\n    def to_dict(self) -> Dict:\n        return asdict(self)\n\n\ndef _conclusion(p: float, alpha: float) -> str:\n    if not np.isfinite(p):\n        return \"undetermined\"\n    return \"difference\" if p < alpha else \"no difference\"\n\n\ndef stability_check(\n    groups: Sequence[Sequence[float]],\n    test_fn: Callable[[List[np.ndarray]], tuple],\n    alpha: float = 0.05,\n    n_boot: int = 400,\n    seed: int = 20260901,\n) -> StabilityReport:\n    \"\"\"Three perturbations, run automatically on every inferential result.\n\n    1. Leave-one-out -- does one observation carry the whole conclusion?\n    2. Bootstrap resampling -- how often does the conclusion survive?\n    3. The range of p and of the effect size across both.\n\n    `test_fn` takes a list of arrays and returns (p_value, effect_size).\n    \"\"\"\n    gs = [np.asarray(g, dtype=float).ravel() for g in groups]\n    gs = [g[np.isfinite(g)] for g in gs]\n    if len(gs) < 2 or min(len(g) for g in gs) < 3:\n        return StabilityReport(\n            ran=False, n_perturbations=0, conclusion=\"undetermined\", agreement=float(\"nan\"),\n            flipped=False,\n            verdict=\"Too few observations to perturb meaningfully. Treat this result as a \"\n                    \"description of what happened, not as evidence about anything else.\",\n            severity=\"warn\",\n        )\n\n    p0, e0 = test_fn(gs)\n    base = _conclusion(p0, alpha)\n    ps: List[float] = []\n    es: List[float] = []\n    agree = 0\n    total = 0\n\n    # 1. leave-one-out, and remember which single point moves the answer most\n    worst_delta = -1.0\n    worst: Dict | None = None\n    for gi, g in enumerate(gs):\n        for j in range(len(g)):\n            trial = list(gs)\n            trial[gi] = np.delete(g, j)\n            if len(trial[gi]) < 2:\n                continue\n            p, e = test_fn(trial)\n            ps.append(p)\n            es.append(e)\n            total += 1\n            same = _conclusion(p, alpha) == base\n            agree += int(same)\n            d = abs(p - p0)\n            if d > worst_delta:\n                worst_delta = d\n                worst = {\n                    \"group_index\": gi, \"observation_index\": int(j),\n                    \"value\": float(g[j]), \"p_without_it\": float(p),\n                    \"flips_conclusion\": not same,\n                }\n\n    # 2. bootstrap\n    rng = np.random.default_rng(seed)\n    for _ in range(n_boot):\n        trial = [rng.choice(g, len(g), replace=True) for g in gs]\n        if any(np.allclose(t, t[0]) for t in trial):\n            continue\n        try:\n            p, e = test_fn(trial)\n        except Exception:\n            continue\n        if not np.isfinite(p):\n            continue\n        ps.append(p)\n        es.append(e)\n        total += 1\n        agree += int(_conclusion(p, alpha) == base)\n\n    agreement = agree / total if total else float(\"nan\")\n    finite_ps = [p for p in ps if np.isfinite(p)]\n    finite_es = [e for e in es if np.isfinite(e)]\n    flipped = bool(np.isfinite(agreement) and agreement < 0.9)\n\n    if not np.isfinite(agreement):\n        verdict, sev = \"Stability could not be assessed.\", \"warn\"\n    elif worst is not None and worst[\"flips_conclusion\"]:\n        verdict = (f\"Removing a single observation (value {worst['value']:g}) changes the conclusion. \"\n                   f\"This result rests on one data point. Collect more data before claiming anything.\")\n        sev = \"block\"\n    elif agreement < 0.7:\n        verdict = (f\"The conclusion held in only {agreement:.0%} of perturbed re-runs. \"\n                   f\"This is not a stable finding.\")\n        sev = \"block\"\n    elif agreement < 0.9:\n        verdict = (f\"The conclusion held in {agreement:.0%} of perturbed re-runs -- shaky. \"\n                   f\"Report the interval, not the p-value.\")\n        sev = \"warn\"\n    else:\n        verdict = (f\"The conclusion held in {agreement:.0%} of perturbed re-runs, and no single \"\n                   f\"observation changes it. This is a stable finding for this dataset.\")\n        sev = \"info\"\n\n    return StabilityReport(\n        ran=True,\n        n_perturbations=total,\n        conclusion=base,\n        agreement=float(agreement),\n        flipped=flipped,\n        p_range=[float(min(finite_ps)), float(max(finite_ps))] if finite_ps else [],\n        effect_range=[float(min(finite_es)), float(max(finite_es))] if finite_es else [],\n        most_influential=worst,\n        verdict=verdict,\n        severity=sev,\n    )\n",
  "phagequest_engine/transcript.py": "\"\"\"Execution records: the binding that makes a number renderable.\n\nThe platform invariant (spec section 06):\n\n    No numeric statistical claim may be rendered to a user unless it is bound\n    to a specific execution record -- code, engine version, raw output,\n    timestamp -- produced by a real statistics engine.\n\nThis module is the mechanism. Every public engine function is wrapped by\n`@bound`, which:\n\n  1. records the exact arguments it was called with,\n  2. records the engine versions in play,\n  3. hashes the input data so the same data always yields the same data_id,\n  4. stores the raw result,\n  5. returns a `Bound` whose payload carries a `transcript_id`.\n\nA result without a transcript_id is, by construction, not renderable. The\nfrontend enforces the other half: it refuses to display a numeric field whose\nowning object has no transcript_id, and the chatbot guard (guards.py) refuses\nto emit a number in prose that is not present in some transcript in the turn.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport platform\nimport time\nimport uuid\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Any, Callable, Dict, List, Optional\n\nimport numpy as np\n\n__all__ = [\n    \"Transcript\",\n    \"TranscriptStore\",\n    \"Bound\",\n    \"bound\",\n    \"engine_versions\",\n    \"data_fingerprint\",\n    \"get_store\",\n    \"set_store\",\n]\n\n\ndef engine_versions() -> Dict[str, str]:\n    \"\"\"Exact versions of every library that can influence a number.\"\"\"\n    import scipy\n\n    v = {\n        \"phagequest-engine\": \"0.1.0\",\n        \"numpy\": np.__version__,\n        \"scipy\": scipy.__version__,\n        \"python\": platform.python_version(),\n    }\n    # statsmodels is Tier-1 only; report it when present so server-side\n    # transcripts are distinguishable from browser-side ones.\n    try:  # pragma: no cover - depends on tier\n        import statsmodels  # type: ignore\n\n        v[\"statsmodels\"] = statsmodels.__version__\n    except Exception:  # pragma: no cover\n        pass\n    v[\"runtime\"] = \"pyodide\" if _in_pyodide() else \"cpython\"\n    return v\n\n\ndef _in_pyodide() -> bool:\n    try:\n        import sys\n\n        return \"pyodide\" in sys.modules or platform.machine() == \"wasm32\"\n    except Exception:  # pragma: no cover\n        return False\n\n\ndef _canonical(obj: Any) -> Any:\n    \"\"\"Make an argument JSON-serialisable and stable across runs.\n\n    Arrays are replaced by a fingerprint rather than inlined: a transcript must\n    stay small enough to display, and the fingerprint is what makes the run\n    reproducible.\n    \"\"\"\n    if isinstance(obj, np.ndarray):\n        return {\"__array__\": {\"shape\": list(obj.shape), \"dtype\": str(obj.dtype),\n                              \"sha256\": data_fingerprint(obj)}}\n    if isinstance(obj, (np.floating, np.integer)):\n        return obj.item()\n    if isinstance(obj, np.bool_):\n        return bool(obj)\n    if isinstance(obj, dict):\n        return {str(k): _canonical(v) for k, v in obj.items()}\n    if isinstance(obj, (list, tuple)):\n        # Long numeric sequences are data, not parameters: fingerprint them.\n        if len(obj) > 64 and all(isinstance(x, (int, float, np.number)) for x in obj):\n            arr = np.asarray(obj, dtype=float)\n            return {\"__array__\": {\"shape\": list(arr.shape), \"dtype\": \"float64\",\n                                  \"sha256\": data_fingerprint(arr)}}\n        return [_canonical(v) for v in obj]\n    if isinstance(obj, (str, int, float, bool)) or obj is None:\n        return obj\n    if hasattr(obj, \"__dataclass_fields__\"):\n        return _canonical(asdict(obj))\n    return repr(obj)\n\n\ndef data_fingerprint(*arrays: Any) -> str:\n    \"\"\"Stable sha256 over one or more array-likes.\n\n    Two runs on the same data produce the same fingerprint, which is how a\n    teacher can tell that a student re-ran an analysis rather than changing it.\n    \"\"\"\n    h = hashlib.sha256()\n    for a in arrays:\n        arr = np.asarray(a)\n        if arr.dtype.kind in \"OUS\":\n            h.update(json.dumps(arr.tolist(), sort_keys=True, default=str).encode())\n        else:\n            h.update(str(arr.shape).encode())\n            h.update(np.ascontiguousarray(arr.astype(np.float64)).tobytes())\n    return h.hexdigest()[:32]\n\n\n@dataclass\nclass Transcript:\n    \"\"\"One execution record. This is the product (spec section 08).\"\"\"\n\n    transcript_id: str\n    tool: str\n    call: str                      # human-readable reconstruction of the call\n    params: Dict[str, Any]\n    data_id: Optional[str]\n    engine: Dict[str, str]\n    started_at: float\n    duration_ms: float\n    result: Dict[str, Any]\n    notes: List[str] = field(default_factory=list)\n    parent_id: Optional[str] = None\n    error: Optional[str] = None\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n    @property\n    def engine_string(self) -> str:\n        e = self.engine\n        parts = [f\"scipy {e.get('scipy')}\", f\"numpy {e.get('numpy')}\"]\n        if \"statsmodels\" in e:\n            parts.append(f\"statsmodels {e['statsmodels']}\")\n        return \" / \".join(parts)\n\n\nclass TranscriptStore:\n    \"\"\"In-memory transcript log for one workspace session.\n\n    Also carries the multiple-comparison ledger, because the ledger is only\n    meaningful relative to a set of executions on the same data.\n    \"\"\"\n\n    def __init__(self) -> None:\n        self._records: Dict[str, Transcript] = {}\n        self._order: List[str] = []\n\n    def put(self, t: Transcript) -> Transcript:\n        self._records[t.transcript_id] = t\n        self._order.append(t.transcript_id)\n        return t\n\n    def get(self, transcript_id: str) -> Optional[Transcript]:\n        return self._records.get(transcript_id)\n\n    def all(self) -> List[Transcript]:\n        return [self._records[i] for i in self._order]\n\n    def since(self, marker: int) -> List[Transcript]:\n        return [self._records[i] for i in self._order[marker:]]\n\n    def marker(self) -> int:\n        return len(self._order)\n\n    def inferential_on(self, data_id: Optional[str]) -> List[Transcript]:\n        \"\"\"Every inferential test already run against this dataset.\n\n        This is the raw material of the visible multiple-comparison ledger\n        (spec section 06, point 4).\n        \"\"\"\n        if data_id is None:\n            return []\n        return [\n            t for t in self.all()\n            if t.data_id == data_id\n            and t.error is None\n            and isinstance(t.result, dict)\n            and t.result.get(\"p_value\") is not None\n        ]\n\n    def numbers(self) -> List[float]:\n        \"\"\"Every numeric value this store has ever produced.\n\n        The chatbot guard cross-checks model prose against exactly this set.\n\n        Numbers inside the engine's own generated sentences count too. A result\n        carries a `plain_language` field that the engine wrote -- \"95% CI 0.12\n        to 0.45\", \"held in 97% of 412 re-runs\" -- and a model quoting that\n        sentence is reporting, not inventing. Excluding those strings made the\n        guard fire on the engine's own words, which trains people to ignore it,\n        and a guard that is routinely ignored protects nobody.\n        \"\"\"\n        import re as _re\n\n        out: List[float] = []\n        num_re = _re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n        def walk(v: Any) -> None:\n            if isinstance(v, bool):\n                return\n            if isinstance(v, (int, float)) and np.isfinite(v):\n                out.append(float(v))\n            elif isinstance(v, str):\n                for m in num_re.findall(v.replace(\",\", \"\")):\n                    try:\n                        f = float(m)\n                    except ValueError:\n                        continue\n                    if np.isfinite(f):\n                        out.append(f)\n            elif isinstance(v, dict):\n                for x in v.values():\n                    walk(x)\n            elif isinstance(v, (list, tuple)):\n                for x in v:\n                    walk(x)\n\n        for t in self.all():\n            walk(t.result)\n        return out\n\n    def clear(self) -> None:\n        self._records.clear()\n        self._order.clear()\n\n\n_STORE = TranscriptStore()\n\n\ndef get_store() -> TranscriptStore:\n    return _STORE\n\n\ndef set_store(store: TranscriptStore) -> TranscriptStore:\n    global _STORE\n    _STORE = store\n    return _STORE\n\n\n@dataclass\nclass Bound:\n    \"\"\"A result and the execution record that licenses its display.\"\"\"\n\n    value: Dict[str, Any]\n    transcript: Transcript\n\n    def to_dict(self) -> Dict[str, Any]:\n        out = dict(self.value)\n        out[\"transcript_id\"] = self.transcript.transcript_id\n        out[\"engine\"] = self.transcript.engine_string\n        out[\"transcript\"] = self.transcript.to_dict()\n        return out\n\n\ndef bound(tool_name: str, data_args: tuple = ()) -> Callable:\n    \"\"\"Decorator: bind a function's numeric output to an execution record.\n\n    `data_args` names the parameters that carry the student's data, so the\n    fingerprint is computed over the data and not over the knobs. Two analyses\n    of the same table share a data_id, which is what lets the ledger know a\n    fifth test has been run on it.\n    \"\"\"\n\n    def deco(fn: Callable) -> Callable:\n        def wrapper(*args: Any, **kwargs: Any) -> Dict[str, Any]:\n            import inspect\n\n            sig = inspect.signature(fn)\n            try:\n                b = sig.bind(*args, **kwargs)\n                b.apply_defaults()\n                all_kw = dict(b.arguments)\n            except TypeError:\n                all_kw = dict(kwargs)\n\n            data_id = None\n            if data_args:\n                present = [all_kw[n] for n in data_args if n in all_kw and all_kw[n] is not None]\n                if present:\n                    data_id = data_fingerprint(*present)\n\n            params = {k: _canonical(v) for k, v in all_kw.items() if k not in data_args}\n            started = time.time()\n            tid = f\"tx_{uuid.uuid4().hex[:16]}\"\n            err = None\n            result: Dict[str, Any] = {}\n            try:\n                result = fn(*args, **kwargs)\n                if not isinstance(result, dict):\n                    result = {\"value\": result}\n            except Exception as exc:  # record failures too -- they are evidence\n                err = f\"{type(exc).__name__}: {exc}\"\n                raise\n            finally:\n                t = Transcript(\n                    transcript_id=tid,\n                    tool=tool_name,\n                    call=_render_call(tool_name, all_kw, data_args),\n                    params=params,\n                    data_id=data_id,\n                    engine=engine_versions(),\n                    started_at=started,\n                    duration_ms=round((time.time() - started) * 1000, 3),\n                    result=_canonical(result) if err is None else {},\n                    notes=list(result.get(\"notes\", [])) if isinstance(result, dict) else [],\n                    error=err,\n                )\n                _STORE.put(t)\n\n            out = dict(result)\n            out[\"transcript_id\"] = tid\n            out[\"engine\"] = t.engine_string\n            return out\n\n        wrapper.__name__ = fn.__name__\n        wrapper.__doc__ = fn.__doc__\n        wrapper.__wrapped__ = fn  # type: ignore[attr-defined]\n        wrapper._tool_name = tool_name  # type: ignore[attr-defined]\n        wrapper._data_args = data_args  # type: ignore[attr-defined]\n        return wrapper\n\n    return deco\n\n\ndef _render_call(tool: str, kwargs: Dict[str, Any], data_args: tuple) -> str:\n    bits = []\n    for k, v in kwargs.items():\n        if k in data_args:\n            arr = np.asarray(v, dtype=object)\n            bits.append(f\"{k}=<data n={arr.size if arr.ndim else 1}>\")\n        elif isinstance(v, str):\n            bits.append(f\"{k}={v!r}\")\n        elif isinstance(v, (int, float, bool)) or v is None:\n            bits.append(f\"{k}={v}\")\n        else:\n            bits.append(f\"{k}=<{type(v).__name__}>\")\n    return f\"{tool}({', '.join(bits)})\"\n",
  "phagequest_engine/validation.py": "\"\"\"Upload validation (spec section 03.1).\n\n    \"Declarative schemas checked on every student upload. Catches the swapped\n    column, the text in a numeric field, the impossible pH of 19 -- *before*\n    the statistics run, with an error that names the row.\"\n\npandera is the Tier-1 choice and is not in Pyodide, and its error messages are\nwritten for data engineers. A Grade 6 needs \"row 14, the pH column says 19 --\npH only goes from 0 to 14; did you mean 1.9?\". So this is a small declarative\nschema checker whose entire output budget goes on the message.\n\nIt also ships the curriculum's own experiment templates as ready-made schemas,\nso a teacher can upload the table their class already fills in by hand and have\nit understood on the first try.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport math\nimport re\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Any, Dict, List, Optional, Sequence\n\nfrom .transcript import bound\n\n__all__ = [\"Column\", \"Schema\", \"TEMPLATES\", \"validate_table\", \"infer_schema\", \"coerce_table\"]\n\n_NUMERIC_RE = re.compile(r\"^\\s*[-+]?(\\d+\\.?\\d*|\\.\\d+)([eE][-+]?\\d+)?\\s*$\")\n_MISSING = {\"\", \"na\", \"n/a\", \"nan\", \"none\", \"null\", \"-\", \"--\", \"?\", \"nd\", \"n.d.\"}\n\n\n@dataclass\nclass Column:\n    name: str\n    dtype: str = \"number\"          # number | integer | text | category | date\n    required: bool = True\n    minimum: Optional[float] = None\n    maximum: Optional[float] = None\n    allowed: Optional[List[str]] = None\n    unit: Optional[str] = None\n    describes: str = \"\"\n    hint: str = \"\"                 # shown when a value fails, in the student's language\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\n@dataclass\nclass Schema:\n    key: str\n    label: str\n    columns: List[Column]\n    curriculum: str = \"\"\n    min_rows: int = 3\n    notes: List[str] = field(default_factory=list)\n\n    def to_dict(self) -> Dict[str, Any]:\n        d = asdict(self)\n        return d\n\n\n# --------------------------------------------------------------------------\n# Curriculum templates. These are the tables the classes already produce.\n# --------------------------------------------------------------------------\nTEMPLATES: Dict[str, Schema] = {\n    \"serial_dilution\": Schema(\n        \"serial_dilution\", \"Serial dilution series\",\n        [Column(\"tube\", \"integer\", minimum=0, describes=\"Which tube in the chain (0 = undiluted)\"),\n         Column(\"dilution_factor\", \"number\", minimum=1,\n                describes=\"How many times weaker than the original\",\n                hint=\"A dilution factor is at least 1. If you wrote 0.1, you meant 10.\"),\n         Column(\"count\", \"integer\", required=False, minimum=0,\n                describes=\"Plaques or colonies counted\",\n                hint=\"Counts are whole numbers and cannot be negative.\"),\n         Column(\"volume_plated_mL\", \"number\", required=False, minimum=1e-6, maximum=10,\n                unit=\"mL\", describes=\"Volume put on the plate\")],\n        curriculum=\"G5-L6\"),\n    \"water_quality\": Schema(\n        \"water_quality\", \"Water-quality strip readings\",\n        [Column(\"sample\", \"text\", describes=\"Where the water came from\"),\n         Column(\"pH\", \"number\", required=False, minimum=0, maximum=14,\n                hint=\"pH runs from 0 to 14. A value of 19 is usually a typo for 1.9.\"),\n         Column(\"nitrate_ppm\", \"number\", required=False, minimum=0, unit=\"ppm\"),\n         Column(\"hardness_ppm\", \"number\", required=False, minimum=0, unit=\"ppm\"),\n         Column(\"chlorine_ppm\", \"number\", required=False, minimum=0, unit=\"ppm\")],\n        curriculum=\"G5-L9\"),\n    \"growth_vs_factor\": Schema(\n        \"growth_vs_factor\", \"Growth against one environmental factor\",\n        [Column(\"level\", \"text\", describes=\"The condition: temperature, pH, salt level...\"),\n         Column(\"replicate\", \"integer\", required=False, minimum=1,\n                describes=\"Which repeat this row is\",\n                hint=\"Replicates are numbered from 1. Every level needs at least three.\"),\n         Column(\"measurement\", \"number\", describes=\"What you measured\"),\n         Column(\"units\", \"text\", required=False)],\n        curriculum=\"G6-L9 / G7-L9 / G8-L9\",\n        notes=[\"This is the one-way design behind three different lessons. Keep one row per \"\n               \"replicate -- do not average before uploading, because the spread between \"\n               \"replicates is most of the information.\"]),\n    \"daily_readings\": Schema(\n        \"daily_readings\", \"Daily time series\",\n        [Column(\"day\", \"number\", minimum=0, describes=\"Day number or date\"),\n         Column(\"reading\", \"number\", describes=\"Today's measurement\"),\n         Column(\"group\", \"text\", required=False, describes=\"Control or treatment\"),\n         Column(\"notes\", \"text\", required=False)],\n        curriculum=\"G7-L7 / G9-L9\", min_rows=4,\n        notes=[\"A missed day is fine -- leave the row out rather than writing 0. \"\n               \"A 0 means you measured zero, and the trend test will believe you.\"]),\n    \"plaque_assay\": Schema(\n        \"plaque_assay\", \"Plaque assay\",\n        [Column(\"sample\", \"text\", describes=\"Which sample or site\"),\n         Column(\"dilution_factor\", \"number\", minimum=1),\n         Column(\"plaque_count\", \"integer\", minimum=0,\n                hint=\"Count whole plaques. 'TNTC' (too numerous to count) should be left blank, \"\n                     \"not written as a number.\"),\n         Column(\"volume_plated_mL\", \"number\", required=False, minimum=1e-6, maximum=10, unit=\"mL\"),\n         Column(\"plaque_morphology\", \"text\", required=False,\n                describes=\"Clear, cloudy, large, small -- clear suggests lytic, cloudy suggests \"\n                          \"the phage sometimes hides\")],\n        curriculum=\"G8-L10 / G9-L11\"),\n    \"site_survey\": Schema(\n        \"site_survey\", \"Sampling sites\",\n        [Column(\"site_id\", \"text\"),\n         Column(\"latitude\", \"number\", required=False, minimum=-90, maximum=90,\n                hint=\"Latitude runs -90 to 90. If your number is bigger, it is probably longitude.\"),\n         Column(\"longitude\", \"number\", required=False, minimum=-180, maximum=180),\n         Column(\"habitat\", \"text\", required=False),\n         Column(\"soil_pH\", \"number\", required=False, minimum=0, maximum=14),\n         Column(\"moisture_percent\", \"number\", required=False, minimum=0, maximum=100)],\n        curriculum=\"G8-L10 / G9-L11\"),\n    \"community_counts\": Schema(\n        \"community_counts\", \"Community composition (counts per taxon)\",\n        [Column(\"sample\", \"text\", describes=\"Which layer or site\"),\n         Column(\"taxon\", \"text\", describes=\"What you saw\"),\n         Column(\"count\", \"integer\", minimum=0)],\n        curriculum=\"G9-L12\",\n        notes=[\"Long format: one row per taxon per sample. The diversity tools pivot it for you.\"]),\n}\n\n\ndef _is_missing(v: Any) -> bool:\n    if v is None:\n        return True\n    if isinstance(v, float) and math.isnan(v):\n        return True\n    return str(v).strip().lower() in _MISSING\n\n\ndef _as_number(v: Any) -> Optional[float]:\n    if isinstance(v, (int, float)) and not isinstance(v, bool):\n        return float(v)\n    s = str(v).strip().replace(\",\", \"\")\n    # Tolerate the units students type into the cell: \"7.2 pH\", \"35 C\", \"12%\"\n    s = re.sub(r\"[^\\d.eE+\\-]\", \"\", s)\n    if _NUMERIC_RE.match(s):\n        try:\n            return float(s)\n        except ValueError:\n            return None\n    return None\n\n\n@bound(\"validate_table\", data_args=(\"rows\",))\ndef validate_table(rows: Sequence[Dict[str, Any]], template: Optional[str] = None,\n                   schema: Optional[Dict[str, Any]] = None,\n                   max_issues: int = 60) -> Dict[str, Any]:\n    \"\"\"Check an uploaded table before any statistics touch it.\n\n    Every issue names the row number the student can see in their spreadsheet\n    (1-based, counting the header as row 1), the column, the offending value,\n    and what to do about it. Nothing is silently coerced.\n    \"\"\"\n    data = list(rows)\n    if not data:\n        return {\"valid\": False, \"issues\": [{\"severity\": \"block\", \"row\": None, \"column\": None,\n                                            \"message\": \"The file has no rows.\"}],\n                \"n_rows\": 0, \"p_value\": None}\n\n    sch: Optional[Schema] = None\n    if schema is not None:\n        sch = Schema(key=schema.get(\"key\", \"custom\"), label=schema.get(\"label\", \"Custom schema\"),\n                     columns=[Column(**c) for c in schema.get(\"columns\", [])],\n                     curriculum=schema.get(\"curriculum\", \"\"),\n                     min_rows=int(schema.get(\"min_rows\", 3)))\n    elif template is not None:\n        sch = TEMPLATES.get(template)\n        if sch is None:\n            return {\"valid\": False, \"n_rows\": len(data),\n                    \"issues\": [{\"severity\": \"block\", \"row\": None, \"column\": None,\n                                \"message\": f\"Unknown template {template!r}.\"}],\n                    \"available_templates\": sorted(TEMPLATES), \"p_value\": None}\n\n    present = list({k for r in data for k in r.keys()})\n    issues: List[Dict[str, Any]] = []\n    add = issues.append\n\n    if sch is not None:\n        lower = {c.lower().strip(): c for c in present}\n        for col in sch.columns:\n            if col.name.lower() not in lower:\n                if col.required:\n                    close = _closest(col.name, present)\n                    add({\"severity\": \"block\", \"row\": None, \"column\": col.name,\n                         \"message\": (f\"The required column '{col.name}' is missing.\"\n                                     + (f\" Did you mean '{close}'?\" if close else \"\")\n                                     + (f\" It should hold: {col.describes}\" if col.describes else \"\"))})\n                continue\n            actual = lower[col.name.lower()]\n            for i, row in enumerate(data):\n                rownum = i + 2  # header is row 1 in the student's spreadsheet\n                v = row.get(actual)\n                if _is_missing(v):\n                    if col.required:\n                        add({\"severity\": \"warn\", \"row\": rownum, \"column\": col.name, \"value\": v,\n                             \"message\": f\"Row {rownum} has no value for '{col.name}'. That row \"\n                                        f\"will be left out of any calculation using this column.\"})\n                    continue\n                if col.dtype in (\"number\", \"integer\"):\n                    num = _as_number(v)\n                    if num is None:\n                        add({\"severity\": \"block\", \"row\": rownum, \"column\": col.name, \"value\": v,\n                             \"message\": (f\"Row {rownum}, column '{col.name}': '{v}' is not a \"\n                                         f\"number. Statistics cannot be computed on text. If this \"\n                                         f\"means 'no reading', leave the cell empty instead.\")})\n                        continue\n                    if col.dtype == \"integer\" and abs(num - round(num)) > 1e-9:\n                        add({\"severity\": \"warn\", \"row\": rownum, \"column\": col.name, \"value\": v,\n                             \"message\": f\"Row {rownum}: '{col.name}' should be a whole number but \"\n                                        f\"is {num}.\"})\n                    if col.minimum is not None and num < col.minimum:\n                        add({\"severity\": \"block\", \"row\": rownum, \"column\": col.name, \"value\": num,\n                             \"message\": (f\"Row {rownum}: '{col.name}' is {num}, below the minimum \"\n                                         f\"of {col.minimum}. \" + (col.hint or \"\"))})\n                    if col.maximum is not None and num > col.maximum:\n                        add({\"severity\": \"block\", \"row\": rownum, \"column\": col.name, \"value\": num,\n                             \"message\": (f\"Row {rownum}: '{col.name}' is {num}, above the maximum \"\n                                         f\"of {col.maximum}. \" + (col.hint or \"\"))})\n                elif col.allowed:\n                    if str(v).strip() not in col.allowed:\n                        add({\"severity\": \"warn\", \"row\": rownum, \"column\": col.name, \"value\": v,\n                             \"message\": f\"Row {rownum}: '{col.name}' is '{v}', which is not one of \"\n                                        f\"{col.allowed}.\"})\n                if len(issues) >= max_issues:\n                    break\n\n        extra = [c for c in present if c.lower() not in {x.name.lower() for x in sch.columns}]\n        if extra:\n            add({\"severity\": \"info\", \"row\": None, \"column\": None,\n                 \"message\": f\"Extra columns kept as-is: {', '.join(sorted(extra))}.\"})\n        if len(data) < sch.min_rows:\n            add({\"severity\": \"warn\", \"row\": None, \"column\": None,\n                 \"message\": (f\"Only {len(data)} rows. This kind of experiment needs at least \"\n                             f\"{sch.min_rows} before any analysis means anything.\")})\n    else:\n        # Schema-free pass: still catch the things that break statistics.\n        for col in present:\n            vals = [r.get(col) for r in data if not _is_missing(r.get(col))]\n            nums = [_as_number(v) for v in vals]\n            n_num = sum(1 for x in nums if x is not None)\n            if vals and 0 < n_num < len(vals) and n_num / len(vals) > 0.7:\n                bad = [(i + 2, r.get(col)) for i, r in enumerate(data)\n                       if not _is_missing(r.get(col)) and _as_number(r.get(col)) is None]\n                for rownum, v in bad[:5]:\n                    add({\"severity\": \"block\", \"row\": rownum, \"column\": col, \"value\": v,\n                         \"message\": (f\"Column '{col}' is mostly numbers, but row {rownum} says \"\n                                     f\"'{v}'. One piece of text turns the whole column into text \"\n                                     f\"and stops every calculation on it.\")})\n\n    # Duplicate-row check: a copy-paste accident that quietly doubles your n.\n    seen: Dict[str, int] = {}\n    for i, row in enumerate(data):\n        key = \"|\".join(f\"{k}={row[k]}\" for k in sorted(row))\n        if key in seen:\n            add({\"severity\": \"warn\", \"row\": i + 2, \"column\": None,\n                 \"message\": (f\"Row {i + 2} is identical to row {seen[key] + 2}. If that is a \"\n                             f\"copy-paste accident it inflates your sample size and makes every \"\n                             f\"result look more certain than it is.\")})\n        else:\n            seen[key] = i\n\n    blocking = [i for i in issues if i[\"severity\"] == \"block\"]\n    return {\n        \"valid\": not blocking,\n        \"template\": sch.key if sch else None,\n        \"template_label\": sch.label if sch else None,\n        \"curriculum\": sch.curriculum if sch else None,\n        \"n_rows\": len(data), \"columns\": present,\n        \"issues\": issues[:max_issues],\n        \"n_issues\": len(issues),\n        \"n_blocking\": len(blocking),\n        \"schema_notes\": sch.notes if sch else [],\n        \"plain_language\": (\n            f\"{len(data)} rows checked. \"\n            + (\"Everything looks usable.\"\n               if not issues else\n               f\"{len(blocking)} problem{'s' if len(blocking) != 1 else ''} must be fixed before \"\n               f\"the statistics will run\"\n               f\"{f', and {len(issues) - len(blocking)} thing(s) worth a look' if len(issues) > len(blocking) else ''}.\")),\n        \"p_value\": None,\n    }\n\n\ndef _closest(name: str, candidates: Sequence[str]) -> Optional[str]:\n    \"\"\"Cheap edit-distance suggestion for a mistyped column name.\"\"\"\n    def dist(a: str, b: str) -> int:\n        a, b = a.lower(), b.lower()\n        prev = list(range(len(b) + 1))\n        for i, ca in enumerate(a, 1):\n            cur = [i]\n            for j, cb in enumerate(b, 1):\n                cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))\n            prev = cur\n        return prev[-1]\n    best, bd = None, 99\n    for c in candidates:\n        d = dist(name, c)\n        if d < bd:\n            best, bd = c, d\n    return best if bd <= max(2, len(name) // 3) else None\n\n\n@bound(\"infer_schema\", data_args=(\"rows\",))\ndef infer_schema(rows: Sequence[Dict[str, Any]]) -> Dict[str, Any]:\n    \"\"\"Guess a schema from an unfamiliar upload, and suggest the closest template.\"\"\"\n    data = list(rows)\n    if not data:\n        return {\"refused\": True, \"reason\": \"No rows.\"}\n    present = list({k for r in data for k in r.keys()})\n    cols = []\n    for c in present:\n        vals = [r.get(c) for r in data if not _is_missing(r.get(c))]\n        nums = [x for x in (_as_number(v) for v in vals) if x is not None]\n        if vals and len(nums) == len(vals):\n            integral = all(abs(x - round(x)) < 1e-9 for x in nums)\n            cols.append(Column(c, \"integer\" if integral else \"number\",\n                               required=len(vals) == len(data),\n                               minimum=min(nums), maximum=max(nums)).to_dict())\n        else:\n            uniq = sorted({str(v).strip() for v in vals})\n            cols.append(Column(c, \"category\" if len(uniq) <= max(2, len(data) // 3) else \"text\",\n                               required=len(vals) == len(data),\n                               allowed=uniq if len(uniq) <= 12 else None).to_dict())\n\n    lowered = {c.lower() for c in present}\n    scores = {k: len(lowered & {col.name.lower() for col in s.columns})\n              for k, s in TEMPLATES.items()}\n    best = max(scores, key=scores.get) if scores else None\n    return {\n        \"columns\": cols, \"n_rows\": len(data),\n        \"suggested_template\": best if best and scores[best] >= 2 else None,\n        \"template_match_score\": scores.get(best, 0) if best else 0,\n        \"plain_language\": (\n            f\"Found {len(present)} columns across {len(data)} rows.\"\n            + (f\" This looks like the '{TEMPLATES[best].label}' template \"\n               f\"({TEMPLATES[best].curriculum}).\" if best and scores[best] >= 2 else \"\")),\n        \"p_value\": None,\n    }\n\n\n@bound(\"coerce_table\", data_args=(\"rows\",))\ndef coerce_table(rows: Sequence[Dict[str, Any]], numeric_columns: Sequence[str]) -> Dict[str, Any]:\n    \"\"\"Convert named columns to numbers, reporting every value it could not convert.\n\n    Deliberately separate from validation and never automatic: a platform that\n    quietly turns 'TNTC' into 0 has fabricated a measurement.\n    \"\"\"\n    out, dropped = [], []\n    for i, row in enumerate(rows):\n        new = dict(row)\n        ok = True\n        for c in numeric_columns:\n            if c not in new:\n                continue\n            if _is_missing(new[c]):\n                new[c] = None\n                continue\n            v = _as_number(new[c])\n            if v is None:\n                dropped.append({\"row\": i + 2, \"column\": c, \"value\": row[c]})\n                ok = False\n            new[c] = v\n        out.append(new) if ok else None\n    return {\n        \"rows\": out, \"n_in\": len(list(rows)), \"n_out\": len(out),\n        \"dropped\": dropped,\n        \"plain_language\": (\n            f\"Converted {len(numeric_columns)} column(s) to numbers; kept {len(out)} of \"\n            f\"{len(list(rows))} rows.\"\n            + (f\" {len(dropped)} value(s) could not be converted and their rows were left out -- \"\n               f\"they are listed so you can fix them rather than lose them silently.\"\n               if dropped else \"\")),\n        \"p_value\": None,\n    }\n",
}

